    def _preview_canvas_to_image_point(self, canvas_x: float, canvas_y: float):
        state = getattr(self, "_preview_render_state", None) or {}
        scale = max(0.001, float(state.get("scale", 0.0) or 0.0))
        image_left = float(state.get("image_left", 0.0))
        image_top = float(state.get("image_top", 0.0))
        orig_w = max(1.0, float(state.get("orig_w", 1.0)))
        orig_h = max(1.0, float(state.get("orig_h", 1.0)))

        img_x = (float(canvas_x) - image_left) / scale
        img_y = (float(canvas_y) - image_top) / scale
        img_x = max(0.0, min(orig_w, img_x))
        img_y = max(0.0, min(orig_h, img_y))
        return float(img_x), float(img_y)

    def _preview_image_to_canvas_point(self, img_x: float, img_y: float):
        state = getattr(self, "_preview_render_state", None) or {}
        scale = max(0.001, float(state.get("scale", 0.0) or 0.0))
        image_left = float(state.get("image_left", 0.0))
        image_top = float(state.get("image_top", 0.0))
        return (
            (float(img_x) * scale) + image_left,
            (float(img_y) * scale) + image_top,
        )

    def _preview_point_inside_image(self, canvas_x: float, canvas_y: float) -> bool:
        state = getattr(self, "_preview_render_state", None) or {}
        return bool(
            float(state.get("image_left", 0.0)) <= float(canvas_x) <= float(state.get("image_right", -1.0))
            and float(state.get("image_top", 0.0)) <= float(canvas_y) <= float(state.get("image_bottom", -1.0))
        )

    def _get_preview_metadata_path(self) -> Path | None:
        preview_dir_raw = str(getattr(self, "preview_dir_var", None).get() if hasattr(self, "preview_dir_var") else "").strip()
        if not preview_dir_raw:
            return None
        return Path(preview_dir_raw) / "metadata.json"

    def _get_preview_active_data(self, create: bool = False):
        pid = str(getattr(self, "_preview_active_pid", "") or "")
        if not pid:
            return None
        if create:
            return self.preview_metadata.setdefault(pid, {})
        return self.preview_metadata.get(pid)

    def _get_preview_active_character_records(self, create: bool = False):
        data = self._get_preview_active_data(create=create)
        if not isinstance(data, dict):
            return []
        chars = data.get("characters")
        if isinstance(chars, list):
            return chars
        if create:
            data["characters"] = []
            return data["characters"]
        return []

    def _get_preview_source_filename(self, data: dict | None = None) -> str:
        source_data = data if isinstance(data, dict) else self._get_preview_active_data(create=False)
        if not isinstance(source_data, dict):
            return ""

        source_image = str(source_data.get("source_image", "") or "").strip()
        if source_image:
            return Path(source_image).name

        for field_name in ("filename", "source_name"):
            candidate = str(source_data.get(field_name, "") or "").strip()
            if candidate:
                return Path(candidate).name
        return ""

    @staticmethod
    def _normalize_preview_source_path_key(raw_value: str) -> str:
        text = str(raw_value or "").strip()
        if not text:
            return ""
        try:
            path_obj = Path(text)
            if path_obj.exists():
                try:
                    return path_obj.resolve().as_posix().lower()
                except Exception:
                    return path_obj.absolute().as_posix().lower()
            if path_obj.is_absolute():
                try:
                    return path_obj.absolute().as_posix().lower()
                except Exception:
                    pass
        except Exception:
            pass
        return text.replace("\\", "/").lower()

    def _resolve_preview_source_image_path(self, data: dict | None = None) -> Path | None:
        source_data = data if isinstance(data, dict) else self._get_preview_active_data(create=False)
        if not isinstance(source_data, dict):
            return None

        candidate_paths = []
        images_dir_raw = str(self.images_dir_var.get() or "").strip() if hasattr(self, "images_dir_var") else ""
        raw_dir_raw = ""
        try:
            raw_dir_raw = str(CAMPAIGN.get_dir("raw") or "").strip()
        except Exception:
            raw_dir_raw = ""

        for field_name in ("source_image", "filename", "source_name"):
            raw_value = str(source_data.get(field_name, "") or "").strip()
            if not raw_value:
                continue
            raw_path = Path(raw_value)
            candidate_paths.append(raw_path)
            if not raw_path.is_absolute():
                if images_dir_raw:
                    candidate_paths.append(Path(images_dir_raw) / raw_path.name)
                if raw_dir_raw:
                    candidate_paths.append(Path(raw_dir_raw) / raw_path.name)

        seen = set()
        first_candidate = None
        for candidate in candidate_paths:
            normalized = self._normalize_preview_source_path_key(str(candidate))
            if not normalized or normalized in seen:
                continue
            seen.add(normalized)
            if first_candidate is None:
                first_candidate = candidate
            try:
                if candidate.exists() and candidate.is_file():
                    try:
                        return candidate.resolve()
                    except Exception:
                        return candidate.absolute()
            except Exception:
                continue

        if first_candidate is None:
            return None
        try:
            return first_candidate.absolute()
        except Exception:
            return first_candidate

    def _build_preview_plate_reextract_match_key(self, data: dict | None = None) -> str:
        source_data = data if isinstance(data, dict) else {}
        if not isinstance(source_data, dict):
            return ""

        source_key = self._normalize_preview_source_path_key(
            str(source_data.get("source_image", "") or source_data.get("source_name", "") or source_data.get("filename", "") or "").strip()
        )
        if not source_key:
            return ""

        bbox = list(source_data.get("source_bbox") or [])
        if len(bbox) >= 4:
            try:
                bbox_key = ":".join(str(int(round(float(value)))) for value in bbox[:4])
            except Exception:
                bbox_key = ":".join(str(value) for value in bbox[:4])
        else:
            bbox_key = ""

        return f"{source_key}|{bbox_key}"

    def _capture_preview_reextract_seed_metadata(self) -> dict:
        seed_source = {}
        preview_dir = None
        if isinstance(getattr(self, "preview_metadata", None), dict) and self.preview_metadata:
            seed_source = copy.deepcopy(self.preview_metadata)
            try:
                preview_dir_raw = str(self.preview_dir_var.get() or "").strip()
                preview_dir = Path(preview_dir_raw) if preview_dir_raw else None
            except Exception:
                preview_dir = None
        else:
            preview_dir_raw = str(self.preview_dir_var.get() or "").strip()
            if preview_dir_raw:
                meta_path = Path(preview_dir_raw) / "metadata.json"
                seed_source = self._load_json_file_safely(meta_path)
                preview_dir = Path(preview_dir_raw)

        if not isinstance(seed_source, dict):
            return {}

        seed_lookup: dict[str, dict] = {}
        for _pid, raw_data in seed_source.items():
            if not isinstance(raw_data, dict):
                continue
            match_key = self._build_preview_plate_reextract_match_key(raw_data)
            if not match_key or match_key in seed_lookup:
                continue
            seed_payload = copy.deepcopy(raw_data)
            try:
                seed_size = self._get_preview_plate_image_size(preview_dir, str(_pid or "").strip())
            except Exception:
                seed_size = None
            if seed_size:
                seed_payload["_seed_image_size"] = [int(seed_size[0]), int(seed_size[1])]
            seed_lookup[match_key] = seed_payload
        return seed_lookup

    @staticmethod
    def _preview_plate_has_renderable_boxes(data: dict | None) -> bool:
        if not isinstance(data, dict):
            return False
        for key_name in ("characters", "yolo_detections", "yolo_nms_detections", "yolo_raw_detections"):
            values = data.get(key_name)
            if isinstance(values, list) and len(values) > 0:
                return True
        return False

    def _collect_historical_preview_reextract_seed_metadata(self, current_preview_dir: Path | None = None) -> dict:
        run_root = None
        if current_preview_dir is not None:
            try:
                run_root = Path(current_preview_dir).parent
            except Exception:
                run_root = None
        if run_root is None:
            try:
                run_root = self._get_step3_chars_root_dir(ensure_exists=False)
            except Exception:
                run_root = None
        if run_root is None or not Path(run_root).exists():
            return {}

        current_meta = None
        if current_preview_dir is not None:
            try:
                current_meta = Path(current_preview_dir) / "metadata.json"
            except Exception:
                current_meta = None

        try:
            meta_files = sorted(
                (
                    path for path in Path(run_root).rglob("metadata.json")
                    if current_meta is None or path != current_meta
                ),
                key=lambda path: path.stat().st_mtime,
                reverse=True,
            )
        except Exception:
            return {}

        seed_lookup: dict[str, dict] = {}
        for meta_path in meta_files:
            metadata = self._load_json_file_safely(meta_path)
            if not isinstance(metadata, dict) or not metadata:
                continue
            for _pid, raw_data in metadata.items():
                if not isinstance(raw_data, dict) or not self._preview_plate_has_renderable_boxes(raw_data):
                    continue
                match_key = self._build_preview_plate_reextract_match_key(raw_data)
                if not match_key or match_key in seed_lookup:
                    continue
                seed_payload = copy.deepcopy(raw_data)
                try:
                    seed_size = self._get_preview_plate_image_size(meta_path.parent, str(_pid or "").strip())
                except Exception:
                    seed_size = None
                if seed_size:
                    seed_payload["_seed_image_size"] = [int(seed_size[0]), int(seed_size[1])]
                seed_lookup[match_key] = seed_payload
            if seed_lookup:
                # najnowszy sensowny run zwykle wystarcza; jeśli już coś znaleźliśmy,
                # nie schodzimy dalej, żeby nie mieszać bardzo starych poprawek.
                break
        return seed_lookup

    def _scale_preview_char_records_to_new_size(self, records, from_size, to_size):
        if not isinstance(records, list):
            return copy.deepcopy(records)
        try:
            from_w, from_h = (float(from_size[0]), float(from_size[1]))
            to_w, to_h = (float(to_size[0]), float(to_size[1]))
        except Exception:
            return copy.deepcopy(records)

        if from_w <= 0 or from_h <= 0 or to_w <= 0 or to_h <= 0:
            return copy.deepcopy(records)

        scale_x = to_w / from_w
        scale_y = to_h / from_h
        scaled_records = []
        for rec in list(records or []):
            cloned = copy.deepcopy(rec)
            bbox = self._char_record_bbox(cloned)
            if not bbox:
                scaled_records.append(cloned)
                continue
            x1, y1, x2, y2 = bbox
            scaled_bbox = [
                max(0.0, min(to_w, float(x1) * scale_x)),
                max(0.0, min(to_h, float(y1) * scale_y)),
                max(0.0, min(to_w, float(x2) * scale_x)),
                max(0.0, min(to_h, float(y2) * scale_y)),
            ]
            if scaled_bbox[2] < scaled_bbox[0]:
                scaled_bbox[0], scaled_bbox[2] = scaled_bbox[2], scaled_bbox[0]
            if scaled_bbox[3] < scaled_bbox[1]:
                scaled_bbox[1], scaled_bbox[3] = scaled_bbox[3], scaled_bbox[1]
            if isinstance(cloned, dict):
                cloned["bbox"] = [float(v) for v in scaled_bbox]
            else:
                try:
                    cloned.bbox = tuple(float(v) for v in scaled_bbox)
                except Exception:
                    pass
            scaled_records.append(cloned)
        return scaled_records

    def _adapt_reextract_seed_payload_to_current_preview(self, previous: dict, preview_dir: Path, pid: str) -> dict:
        adapted = copy.deepcopy(previous)
        from_size = adapted.get("_seed_image_size")
        to_size = self._get_preview_plate_image_size(preview_dir, pid)
        if from_size and to_size and list(from_size) != [int(to_size[0]), int(to_size[1])]:
            for key_name in ("characters", "yolo_detections", "yolo_nms_detections", "yolo_raw_detections"):
                if key_name in adapted:
                    adapted[key_name] = self._scale_preview_char_records_to_new_size(
                        adapted.get(key_name),
                        from_size,
                        to_size,
                    )
        adapted.pop("_seed_image_size", None)
        return adapted

    def _merge_reextract_seed_metadata_into_preview(self, preview_dir: Path | None, seed_lookup: dict | None = None) -> dict:
        if preview_dir is None:
            return {"matched": 0, "total": 0}

        meta_path = Path(preview_dir) / "metadata.json"
        if not meta_path.exists():
            return {"matched": 0, "total": 0}

        previous_lookup = dict(seed_lookup or getattr(self, "_campaign_step3_reextract_seed_metadata", {}) or {})
        if not previous_lookup or not any(self._preview_plate_has_renderable_boxes(item) for item in previous_lookup.values()):
            previous_lookup = self._collect_historical_preview_reextract_seed_metadata(preview_dir)
        if not previous_lookup:
            return {"matched": 0, "total": 0}

        metadata = self._load_json_file_safely(meta_path)
        if not isinstance(metadata, dict) or not metadata:
            return {"matched": 0, "total": 0}

        preserve_keys = (
            "characters",
            "status",
            "fusion_strategy",
            "fusion_details",
            "source_info",
            "gold_state",
            "yolo_detections",
            "yolo_nms_detections",
            "yolo_raw_detections",
        )

        matched = 0
        for pid, raw_data in list(metadata.items()):
            if not isinstance(raw_data, dict):
                continue
            match_key = self._build_preview_plate_reextract_match_key(raw_data)
            if not match_key:
                continue
            previous = previous_lookup.get(match_key)
            if not isinstance(previous, dict):
                continue
            previous = self._adapt_reextract_seed_payload_to_current_preview(
                previous,
                Path(preview_dir),
                str(pid or "").strip(),
            )
            for key_name in preserve_keys:
                if key_name in previous:
                    raw_data[key_name] = copy.deepcopy(previous.get(key_name))
            self._ensure_plate_source_metadata(raw_data, plate_id=str(pid or ""), meta_path=meta_path)
            matched += 1

        metadata = self._recalculate_preview_statuses_in_metadata(metadata)
        self._atomic_write_json(meta_path, metadata)
        return {"matched": int(matched), "total": int(len(metadata))}

    @staticmethod
    def _replace_preview_source_filename(raw_value: str, new_filename: str) -> str:
        raw_text = str(raw_value or "").strip()
        safe_name = str(new_filename or "").strip()
        if not raw_text:
            return safe_name
        for separator in ("\\", "/"):
            if separator in raw_text:
                prefix = raw_text.rsplit(separator, 1)[0]
                return f"{prefix}{separator}{safe_name}" if prefix else safe_name
        return safe_name

    def _sanitize_preview_char_symbol(self, value) -> str:
        text = str(value or "").strip().upper()
        if not text:
            return ""
        if len(text) == 1 and text in CHAR_CLASS_ALPHABET:
            return text
        return ""

    def _is_exportable_character_record(self, rec) -> bool:
        if isinstance(rec, dict):
            symbol = rec.get("character", "")
        else:
            symbol = getattr(rec, "character", "")
        if not self._sanitize_preview_char_symbol(symbol):
            return False

        bbox = self._char_record_bbox(rec)
        if not bbox:
            return False
        try:
            x1, y1, x2, y2 = (float(v) for v in bbox[:4])
        except Exception:
            return False
        return bool(x2 > x1 and y2 > y1)

    def _normalize_preview_char_bbox(self, bbox, *, min_size: float = 4.0):
        if not isinstance(bbox, (list, tuple)) or len(bbox) < 4:
            return None
        try:
            x1, y1, x2, y2 = (float(v) for v in bbox[:4])
        except Exception:
            return None
        if x2 < x1:
            x1, x2 = x2, x1
        if y2 < y1:
            y1, y2 = y2, y1

        state = getattr(self, "_preview_render_state", None) or {}
        max_w = max(1.0, float(state.get("orig_w", 1.0)))
        max_h = max(1.0, float(state.get("orig_h", 1.0)))
        x1 = max(0.0, min(max_w, x1))
        y1 = max(0.0, min(max_h, y1))
        x2 = max(0.0, min(max_w, x2))
        y2 = max(0.0, min(max_h, y2))

        if x2 - x1 < float(min_size):
            if x1 + float(min_size) <= max_w:
                x2 = x1 + float(min_size)
            else:
                x1 = max(0.0, x2 - float(min_size))
        if y2 - y1 < float(min_size):
            if y1 + float(min_size) <= max_h:
                y2 = y1 + float(min_size)
            else:
                y1 = max(0.0, y2 - float(min_size))

        return [float(x1), float(y1), float(x2), float(y2)]

    def _mark_preview_char_record_manual(self, rec: dict):
        if not isinstance(rec, dict):
            return
        rec["method"] = "manual"
        rec["source_tag"] = "manual"
        rec["source_kind"] = "local_manual"
        try:
            rec["confidence"] = float(rec.get("confidence", 1.0) or 1.0)
        except Exception:
            rec["confidence"] = 1.0

    def _derive_preview_status_from_characters(self, chars) -> str:
        if not isinstance(chars, list) or not chars:
            return "needs_fix"
        valid_count = 0
        for rec in chars:
            if self._is_exportable_character_record(rec):
                valid_count += 1
        return "perfect" if valid_count == len(chars) and valid_count > 0 else "needs_fix"

    def _preview_has_reference_text_source(self, data: dict | None = None) -> bool:
        source_data = data if isinstance(data, dict) else self._get_preview_active_data(create=False)
        return any(bool(value) for value in self._get_preview_reference_text_values(source_data))

    def _get_preview_reference_text_values(self, data: dict | None = None) -> list[str]:
        source_data = data if isinstance(data, dict) else self._get_preview_active_data(create=False)
        if not isinstance(source_data, dict):
            return []
        values = []
        for field_name in ("source_image", "source_name", "filename"):
            prepared = str(source_data.get(field_name, "") or "").strip()
            if prepared:
                values.append(prepared)
        return values

    def _get_preview_expected_texts(self, data: dict | None = None) -> list[str]:
        source_data = data if isinstance(data, dict) else self._get_preview_active_data(create=False)
        normalized = []
        seen = set()
        for candidate in self._get_preview_reference_text_values(source_data):
            if not candidate:
                continue
            for item in self._get_true_texts_from_filename(candidate):
                prepared = str(item or "").strip().upper()
                if not prepared or prepared in seen:
                    continue
                seen.add(prepared)
                normalized.append(prepared)
        return normalized

    def _derive_preview_status_from_data(self, data: dict | None, chars) -> str:
        base_status = self._derive_preview_status_from_characters(chars)
        if base_status != "perfect":
            return base_status

        expected_texts = self._get_preview_expected_texts(data)
        if not expected_texts:
            if self._preview_has_reference_text_source(data):
                return "needs_fix"
            return base_status

        candidate_text = self._characters_to_text(chars).strip().upper()
        if candidate_text and candidate_text in expected_texts:
            return "perfect"
        return "needs_fix"

    def _get_preview_live_status(self, data: dict | None = None, chars=None, plate_id: str | None = None) -> str:
        source_data = data if isinstance(data, dict) else self._get_preview_active_data(create=False)
        if not isinstance(source_data, dict):
            return str((data or {}).get("status", "unknown") or "unknown").strip().lower() if isinstance(data, dict) else "unknown"

        probe = dict(source_data)
        resolved_plate_id = str(plate_id or getattr(self, "_preview_active_pid", "") or probe.get("plate_id", "") or "").strip()
        if resolved_plate_id:
            probe["plate_id"] = resolved_plate_id

        source_chars = chars
        if source_chars is None:
            source_chars = probe.get("characters", [])
        return str(self._derive_preview_status_from_data(probe, source_chars) or "unknown").strip().lower()

    def _get_preview_status_presentation(self, data: dict | None = None, chars=None, plate_id: str | None = None) -> dict:
        source_data = data if isinstance(data, dict) else self._get_preview_active_data(create=False)
        source_chars = chars if isinstance(chars, list) else (
            source_data.get("characters", []) if isinstance(source_data, dict) else []
        )
        status = self._get_preview_live_status(data=source_data, chars=source_chars, plate_id=plate_id)
        expected_texts = self._get_preview_expected_texts(source_data if isinstance(source_data, dict) else None)

        total_boxes = len(source_chars) if isinstance(source_chars, list) else 0
        filled_boxes = 0
        if isinstance(source_chars, list):
            for rec in source_chars:
                symbol = ""
                if isinstance(rec, dict):
                    symbol = rec.get("character", "")
                else:
                    symbol = getattr(rec, "character", "")
                if self._sanitize_preview_char_symbol(symbol):
                    filled_boxes += 1

        candidate_text = self._characters_to_text(source_chars).strip().upper()
        severity = "muted"
        canvas_text = "Nieocenione"
        info_text = "status: nieoceniona"

        if status == "perfect":
            severity = "success"
            canvas_text = "Perfect"
            info_text = "status: OK"
        elif total_boxes <= 0:
            severity = "warning"
            canvas_text = "Brak boxów"
            info_text = "status: brak boxów"
        elif filled_boxes < total_boxes:
            severity = "warning"
            canvas_text = f"Niepełne {filled_boxes}/{total_boxes}"
            info_text = f"status: niepełne {filled_boxes}/{total_boxes}"
        elif expected_texts:
            expected_lengths = [len(str(text or "").strip().upper()) for text in expected_texts if str(text or "").strip()]
            target_len = min(expected_lengths, key=lambda value: abs(int(value) - int(total_boxes))) if expected_lengths else None
            if target_len is not None and int(total_boxes) != int(target_len):
                severity = "warning"
                canvas_text = f"Boxy {total_boxes}/{int(target_len)}"
                info_text = f"status: boxy {total_boxes}/{int(target_len)}"
            elif candidate_text:
                severity = "error"
                canvas_text = "Do korekty"
                info_text = "status: wymaga korekty"
            else:
                severity = "warning"
                canvas_text = "Brak znaków"
                info_text = "status: brak znaków"
        elif candidate_text:
            severity = "warning"
            canvas_text = "Bez wzorca"
            info_text = "status: brak wzorca"

        return {
            "status": status,
            "severity": severity,
            "canvas_text": canvas_text,
            "info_text": info_text,
            "candidate_text": candidate_text,
            "expected_texts": list(expected_texts or []),
            "filled_boxes": int(filled_boxes),
            "total_boxes": int(total_boxes),
        }

    def _recalculate_preview_statuses_in_metadata(self, metadata: dict | None):
        if not isinstance(metadata, dict):
            return metadata

        for plate_id, raw_data in list(metadata.items()):
            if not isinstance(raw_data, dict):
                continue
            self._ensure_plate_source_metadata(raw_data, plate_id=str(plate_id or ""))
            chars = raw_data.get("characters", None)
            if not isinstance(chars, list):
                continue
            if not chars:
                raw_data["status"] = "needs_fix"
                continue

            status_probe = dict(raw_data)
            status_probe["plate_id"] = str(plate_id)
            raw_data["status"] = self._derive_preview_status_from_data(status_probe, chars)

        return metadata

    def _persist_preview_metadata(self, *, success_message: str | None = None, refresh_list: bool = True):
        meta_path = self._get_preview_metadata_path()
        if meta_path is None:
            raise RuntimeError("Brak aktywnej paczki preview do zapisania.")

        self._atomic_write_json(meta_path, self.preview_metadata)
        self._loaded_meta_path = meta_path
        try:
            self._loaded_meta_mtime = meta_path.stat().st_mtime
        except Exception:
            self._loaded_meta_mtime = None

        if refresh_list:
            self._refresh_listbox_rows_from_metadata()
        self._sync_step3_access_from_preview_state(self.preview_metadata)
        if success_message:
            self._set_preview_box_info(success_message, "success")

    def _clone_preview_plate_data(self, plate_id: str | None = None):
        pid = str(plate_id or getattr(self, "_preview_active_pid", "") or "").strip()
        if not pid:
            return None
        data = self.preview_metadata.get(pid)
        return copy.deepcopy(data if isinstance(data, dict) else {})

    def _get_preview_history_stack(self, kind: str, plate_id: str | None = None, create: bool = False):
        pid = str(plate_id or getattr(self, "_preview_active_pid", "") or "").strip()
        if not pid:
            return None
        store_attr = "_preview_history_undo" if str(kind).lower() == "undo" else "_preview_history_redo"
        store = getattr(self, store_attr, None)
        if not isinstance(store, dict):
            store = {}
            setattr(self, store_attr, store)
        if create:
            return store.setdefault(pid, [])
        return store.get(pid)

    def _push_preview_history_snapshot(self, plate_id: str | None = None):
        if bool(getattr(self, "_preview_history_replaying", False)):
            return
        pid = str(plate_id or getattr(self, "_preview_active_pid", "") or "").strip()
        if not pid:
            return
        snapshot = self._clone_preview_plate_data(pid)
        if snapshot is None:
            return

        undo_stack = self._get_preview_history_stack("undo", pid, create=True)
        if isinstance(undo_stack, list) and undo_stack and undo_stack[-1] == snapshot:
            return

        undo_stack.append(snapshot)
        limit = max(10, int(getattr(self, "_preview_history_limit", 80) or 80))
        if len(undo_stack) > limit:
            del undo_stack[:-limit]

        redo_stack = self._get_preview_history_stack("redo", pid, create=True)
        if isinstance(redo_stack, list):
            redo_stack.clear()

    def _refresh_preview_listbox_row(self, plate_id: str | None = None):
        pid = str(plate_id or getattr(self, "_preview_active_pid", "") or "").strip()
        listbox = getattr(self, "plates_listbox", None)
        if not pid or listbox is None:
            return
        pid_map = getattr(self, "_listbox_pid_by_index", [])
        try:
            row_index = pid_map.index(pid)
        except Exception:
            return

        data = self.preview_metadata.get(pid, {})
        status = str(data.get("status", "unknown")).strip().lower()
        label = self._format_plate_listbox_label(pid, data)

        try:
            selected_rows = {int(idx) for idx in listbox.curselection()}
        except Exception:
            selected_rows = set()
        try:
            active_row = int(listbox.index(tk.ACTIVE))
        except Exception:
            active_row = None
        row_selected = row_index in selected_rows

        try:
            listbox.delete(row_index)
            listbox.insert(row_index, label)
            self._apply_plate_listbox_row_style(row_index, status)
            if row_selected:
                listbox.selection_set(row_index)
            if active_row == row_index:
                listbox.activate(row_index)
            if row_selected or active_row == row_index:
                listbox.see(row_index)
        except Exception as exc:
            logger.debug(f"Nie udało się odświeżyć pojedynczego wiersza listy tablic [{pid}]: {exc}")

    def _refresh_preview_live_metadata_ui(self, *, status_message: str | None = None, status_tone: str = "muted", render_preview: bool = True):
        pid = str(getattr(self, "_preview_active_pid", "") or "").strip()
        data = self._get_preview_active_data(create=False)
        if pid and isinstance(data, dict):
            self._refresh_preview_listbox_row(pid)
            self._update_preview_info_label()

            box_chars, box_source = self._get_preview_box_records(data)
            yolo_variants = self._get_preview_box_variants(data)
            self._update_preview_box_info_label(
                plate_id=pid,
                mode_key=box_source,
                shown_count=len(box_chars),
                yolo_raw_count=len(yolo_variants.get("YOLO_RAW", [])),
                yolo_nms_count=len(yolo_variants.get("YOLO_NMS", [])),
                yolo_filtered_count=len(yolo_variants.get("YOLO_FILTERED", [])),
            )
            self._sync_step3_access_from_preview_state(self.preview_metadata)

        self._refresh_preview_editor_toolbar()
        if status_message:
            self._update_preview_edit_status(status_message, tone=status_tone)
        else:
            self._update_preview_edit_status()
        if render_preview:
            self._on_preview_select(None)
        self._focus_preview_canvas()

    def _restore_preview_plate_history_snapshot(self, snapshot, *, action_label: str):
        pid = str(getattr(self, "_preview_active_pid", "") or "").strip()
        if not pid:
            return False

        self._preview_history_replaying = True
        try:
            self.preview_metadata[pid] = copy.deepcopy(snapshot if isinstance(snapshot, dict) else {})
            self._preview_char_selected_index = None
            self._preview_char_drag_state = None
            self._preview_char_add_state = None
            self._preview_char_hover_index = None
            self._preview_char_hover_label_index = None
            self._preview_char_label_active_index = None
            self._refresh_preview_live_metadata_ui(
                status_message=action_label,
                status_tone="info",
                render_preview=True,
            )
            self.frame.update_idletasks()
            self._persist_preview_metadata(success_message=None, refresh_list=False)
            return True
        finally:
            self._preview_history_replaying = False

    def _undo_preview_edit(self, event=None):
        pid = str(getattr(self, "_preview_active_pid", "") or "").strip()
        undo_stack = self._get_preview_history_stack("undo", pid, create=False)
        if not pid or not isinstance(undo_stack, list) or not undo_stack:
            self._update_preview_edit_status("Brak zmian do cofnięcia.", tone="warning")
            return "break"

        current_snapshot = self._clone_preview_plate_data(pid)
        redo_stack = self._get_preview_history_stack("redo", pid, create=True)
        if current_snapshot is not None:
            redo_stack.append(current_snapshot)

        target_snapshot = undo_stack.pop()
        self._restore_preview_plate_history_snapshot(target_snapshot, action_label="Cofnięto ostatnią zmianę boxów znaków.")
        return "break"

    def _redo_preview_edit(self, event=None):
        pid = str(getattr(self, "_preview_active_pid", "") or "").strip()
        redo_stack = self._get_preview_history_stack("redo", pid, create=False)
        if not pid or not isinstance(redo_stack, list) or not redo_stack:
            self._update_preview_edit_status("Brak zmian do ponowienia.", tone="warning")
            return "break"

        current_snapshot = self._clone_preview_plate_data(pid)
        undo_stack = self._get_preview_history_stack("undo", pid, create=True)
        if current_snapshot is not None:
            undo_stack.append(current_snapshot)

        target_snapshot = redo_stack.pop()
        self._restore_preview_plate_history_snapshot(target_snapshot, action_label="Przywrócono ostatnią cofniętą zmianę boxów znaków.")
        return "break"

    @staticmethod
    def _event_has_control_modifier(event=None) -> bool:
        if event is None:
            return False
        try:
            return bool(int(getattr(event, "state", 0) or 0) & 0x4)
        except Exception:
            return False

    @staticmethod
    def _event_has_shift_modifier(event=None) -> bool:
        if event is None:
            return False
        try:
            return bool(int(getattr(event, "state", 0) or 0) & 0x1)
        except Exception:
            return False

    def _event_has_alt_modifier(self, event=None) -> bool:
        if event is None:
            return bool(getattr(self, "_preview_alt_modifier_down", False))
        keysym = str(getattr(event, "keysym", "") or "").lower()
        if keysym in {"alt_l", "alt_r", "option_l", "option_r"}:
            return True
        try:
            state = int(getattr(event, "state", 0) or 0)
        except Exception:
            state = 0

        # Tk on Windows can leave high-order state bits on ordinary keypresses.
        # Treat 0x20000 as Alt only when we have seen the real Alt key go down.
        if bool(state & 0x8):
            return True
        return bool(getattr(self, "_preview_alt_modifier_down", False) and bool(state & 0x20000))

    @staticmethod
    def _pane_has_child(pane, child) -> bool:
        if pane is None or child is None:
            return False
        try:
            return str(child) in {str(item) for item in pane.panes()}
        except Exception:
            return False

    def _get_current_preview_list_index(self):
        listbox = getattr(self, "plates_listbox", None)
        if listbox is None:
            return None
        try:
            sel = listbox.curselection()
            if sel:
                idx = int(sel[0])
                if 0 <= idx < len(getattr(self, "_listbox_pid_by_index", [])):
                    return idx
        except Exception:
            pass
        try:
            idx = int(listbox.index(tk.ACTIVE))
            if 0 <= idx < len(getattr(self, "_listbox_pid_by_index", [])):
                return idx
        except Exception:
            pass
        return None

    @staticmethod
    def _clear_listbox_selection_fast(listbox) -> None:
        if listbox is None:
            return
        try:
            selected_indices = list(listbox.curselection() or ())
        except Exception:
            selected_indices = []
        for selected_index in selected_indices:
            try:
                listbox.selection_clear(selected_index)
            except Exception:
                pass

    def _on_preview_list_mouse_primary(self, event):
        try:
            self.plates_listbox.focus_set()
        except Exception:
            pass
        try:
            modifier_state = int(getattr(event, "state", 0) or 0)
        except Exception:
            modifier_state = 0

        try:
            target_index = int(self.plates_listbox.nearest(getattr(event, "y", 0)))
        except Exception:
            return None

        try:
            size = int(self.plates_listbox.size() or 0)
        except Exception:
            size = 0
        if size <= 0 or target_index < 0 or target_index >= size:
            return "break"

        shift_pressed = bool(modifier_state & 0x0001)
        control_pressed = bool(modifier_state & 0x0004)
        preserve_index = self._get_current_preview_list_index()
        if preserve_index is not None and not (0 <= int(preserve_index) < size):
            preserve_index = None
        preserve_preview = False

        try:
            if shift_pressed:
                try:
                    anchor_index = int(self.plates_listbox.index(tk.ANCHOR))
                except Exception:
                    anchor_index = -1
                if anchor_index < 0 or anchor_index >= size:
                    try:
                        anchor_index = int(self.plates_listbox.index(tk.ACTIVE))
                    except Exception:
                        anchor_index = target_index
                anchor_index = max(0, min(anchor_index, size - 1))
                start_index = min(anchor_index, target_index)
                end_index = max(anchor_index, target_index)
                if not control_pressed:
                    self._clear_listbox_selection_fast(self.plates_listbox)
                self.plates_listbox.selection_set(start_index, end_index)
                if preserve_index is not None:
                    self.plates_listbox.activate(preserve_index)
                else:
                    self.plates_listbox.activate(anchor_index)
                self.plates_listbox.see(target_index)
                preserve_preview = True
            elif control_pressed:
                if self.plates_listbox.selection_includes(target_index):
                    self.plates_listbox.selection_clear(target_index)
                else:
                    self.plates_listbox.selection_set(target_index)
                self.plates_listbox.selection_anchor(target_index)
                if preserve_index is not None:
                    self.plates_listbox.activate(preserve_index)
                else:
                    self.plates_listbox.activate(target_index)
                self.plates_listbox.see(target_index)
                preserve_preview = True
            else:
                self._suppress_preview_reload_on_list_select = False
                self._clear_listbox_selection_fast(self.plates_listbox)
                self.plates_listbox.selection_set(target_index)
                self.plates_listbox.selection_anchor(target_index)
                self.plates_listbox.activate(target_index)
                self.plates_listbox.see(target_index)
        except Exception:
            return "break"

        if preserve_preview:
            self._suppress_preview_reload_on_list_select = True
            self._refresh_preview_editor_toolbar()
            return "break"

        self._on_preview_select(None)
        return "break"

    def _handle_preview_list_arrow_nav(self, offset: int):
        try:
            self.plates_listbox.focus_set()
        except Exception:
            pass
        self._select_preview_relative(int(offset))
        return "break"

    def _select_preview_relative(self, offset: int):
        listbox = getattr(self, "plates_listbox", None)
        pid_map = getattr(self, "_listbox_pid_by_index", [])
        if listbox is None or not pid_map:
            return False

        current_idx = self._get_current_preview_list_index()
        if current_idx is None:
            current_idx = 0
        target_idx = max(0, min(len(pid_map) - 1, int(current_idx) + int(offset)))
        if target_idx == current_idx and current_idx is not None:
            return False

        try:
            self._clear_listbox_selection_fast(listbox)
            listbox.selection_set(target_idx)
            listbox.activate(target_idx)
            listbox.see(target_idx)
        except Exception:
            return False

        self._preview_char_label_active_index = None
        self._preview_char_hover_label_index = None
        self._preview_char_hover_index = None
        self._on_preview_select(None)
        return True

    @staticmethod
    def _append_preview_status_sentence(base: str, sentence: str) -> str:
        base_text = str(base or "").strip()
        addition = str(sentence or "").strip()
        if not addition:
            return base_text
        if not base_text:
            return addition
        if addition.lower() in base_text.lower():
            return base_text
        if base_text.endswith((".", "!", "?", ":")):
            return f"{base_text} {addition}"
        return f"{base_text}. {addition}"

    def _cancel_preview_char_label_interaction(self, *, reset_mode: bool = True, clear_hover: bool = True) -> bool:
        had_state = bool(getattr(self, "_preview_char_label_mode", False))
        had_state = had_state or getattr(self, "_preview_char_label_active_index", None) is not None
        had_state = had_state or getattr(self, "_preview_char_hover_label_index", None) is not None

        if reset_mode:
            self._preview_char_label_mode = False
        self._preview_char_label_active_index = None
        if clear_hover:
            self._preview_char_hover_label_index = None

        try:
            self._preview_typing_overlay_text = ""
        except Exception:
            pass

        if had_state:
            self._apply_preview_canvas_cursor()
            try:
                self._refresh_preview_editor_toolbar()
            except Exception:
                pass
            try:
                self._sync_preview_edit_status_visibility()
                self._refresh_preview_typing_overlay_visibility()
            except Exception:
                pass

        return had_state

    def _get_preview_typing_state(self) -> tuple[bool, bool]:
        label_mode_active = bool(getattr(self, "_preview_char_label_mode", False))
        label_input_active = getattr(self, "_preview_char_label_active_index", None) is not None
        return label_mode_active, label_input_active

    def _format_preview_typing_status(self, message: str | None = None, *, persistent: bool = False) -> str:
        base_text = str(message or "").strip()
        if persistent:
            if not base_text:
                base_text = "TRYB WPISYWANIA ZNAKÓW AKTYWNY. Kliknij box LPM albo użyj strzałek lewo/prawo, potem wpisz 0-9 lub A-Z."
            elif "tryb wpisywania znaków aktywny" not in base_text.lower():
                base_text = f"TRYB WPISYWANIA ZNAKÓW AKTYWNY. {base_text}"
            return self._append_preview_status_sentence(base_text, "Esc kończy tryb wpisywania.")

        if not base_text:
            base_text = "AKTYWNE POLE ZNAKU. Wpisz 0-9 lub A-Z, aby nadpisać etykietę."
        elif "aktywne pole znaku" not in base_text.lower() and "pole znaku jest aktywne" not in base_text.lower():
            base_text = f"AKTYWNE POLE ZNAKU. {base_text}"
        return self._append_preview_status_sentence(base_text, "Esc zamyka wpisywanie.")

    def _sync_preview_edit_status_visibility(self):
        label = getattr(self, "preview_edit_status_lbl", None)
        if label is None:
            return

        # Status operacji PZ2 jest teraz nakładką canvasa. Stary label był
        # elementem siatki i przy zmianie wysokości potrafił zmieniać rozmiar
        # canvasa, przez co tablica przeskakiwała pod komunikatem.
        try:
            label.grid_remove()
        except Exception:
            pass

    def _get_preview_typing_overlay_text(self) -> str:
        if not bool(getattr(self, "_preview_operation_assistant_visible", True)):
            return ""
        cached = str(getattr(self, "_preview_typing_overlay_text", "") or "").strip()
        if cached:
            return cached

        label_mode_active, label_input_active = self._get_preview_typing_state()
        if label_mode_active:
            return self._format_preview_typing_status(persistent=True)
        if label_input_active:
            return self._format_preview_typing_status(persistent=False)
        return self._format_preview_operation_assistant_status()

    def _format_preview_operation_assistant_status(self) -> str:
        if not self._preview_status_overlay_available():
            return ""
        if self._preview_char_add_requested():
            return "AS: rysuj box - D + przeciągnij LPM."
        if bool(getattr(self, "_preview_char_edit_mode", False)):
            return "AS: edycja boxów - S zaznacza, LPM przesuwa, uchwyty skalują."
        return (
            "AS: Q/E tablice, D+LPM nowy box, S zaznacza, Alt+W wpisywanie."
        )

    def _preview_status_overlay_available(self) -> bool:
        if getattr(self, "preview_canvas", None) is None:
            return False
        return bool(str(getattr(self, "_preview_active_pid", "") or "").strip())

    def _preview_operation_overlay_available(self) -> bool:
        if not bool(getattr(self, "_preview_operation_assistant_visible", True)):
            return False
        return self._preview_status_overlay_available()

    def _resolve_preview_typing_overlay_anchor(self, overlay_w: float, overlay_h: float) -> tuple[float, float] | None:
        canvas_w, canvas_h = self._get_preview_canvas_size()
        margin = 8.0
        bottom_offset = self._get_preview_typing_overlay_bottom_offset()
        max_y = max(margin, float(canvas_h) - float(overlay_h) - float(bottom_offset))

        base_x, base_y = self._get_preview_typing_overlay_anchor(overlay_h)
        base_x = max(margin, min(max(margin, float(canvas_w) - float(overlay_w) - margin), float(base_x)))
        base_y = max(margin, min(max_y, float(base_y)))
        # AS jest czystą nakładką canvasa: nie rezerwuje miejsca i nie omija tablicy.
        # Jeśli nachodzi na obraz, ma go jedynie przysłonić, nigdy przestawiać.
        return float(base_x), float(base_y)

    def _get_preview_typing_overlay_bottom_offset(self) -> float:
        legend_canvas = getattr(self, "preview_controls_canvas", None)
        if not bool(getattr(self, "_preview_fullscreen_active", False)) or legend_canvas is None:
            return 8.0

        try:
            legend_canvas.update_idletasks()
        except Exception:
            pass

        try:
            legend_height = float(max(0, int(legend_canvas.winfo_height() or 0)))
        except Exception:
            legend_height = 0.0
        return 12.0 + legend_height if legend_height > 0.0 else 8.0

    def _get_preview_typing_overlay_anchor(self, overlay_h: float) -> tuple[float, float]:
        canvas_w, canvas_h = self._get_preview_canvas_size()
        margin = 8.0
        x = margin
        y = margin

        top_bar_height = max(38.0, float(getattr(self, "_preview_overlay_top_bar_height", 38.0) or 38.0))
        y = max(y, float(top_bar_height + 6.0))

        mode_overlay = getattr(self, "preview_mode_overlay", None)
        mode_position = getattr(self, "_preview_mode_overlay_position", None)
        mode_y = margin
        mode_h = 0.0
        if mode_overlay is not None:
            try:
                mode_overlay.update_idletasks()
            except Exception:
                pass
            try:
                mode_h = float(max(0, int(mode_overlay.winfo_height() or mode_overlay.winfo_reqheight() or 0)))
            except Exception:
                mode_h = 0.0
        if isinstance(mode_position, dict):
            try:
                mode_y = float(mode_position.get("y", margin))
            except Exception:
                mode_y = margin
        y = max(y, mode_y + mode_h + 6.0)

        bottom_offset = self._get_preview_typing_overlay_bottom_offset()
        max_y = max(margin, float(canvas_h) - float(overlay_h) - float(bottom_offset))
        y = min(y, max_y)
        return float(x), float(y)

    def _refresh_preview_typing_overlay_visibility(self):
        overlay = getattr(self, "preview_typing_overlay", None)
        label = getattr(self, "preview_typing_overlay_lbl", None)
        canvas = getattr(self, "preview_canvas", None)
        if overlay is None or label is None or canvas is None:
            return

        overlay_text = self._get_preview_typing_overlay_text()
        if not overlay_text:
            try:
                overlay.place_forget()
            except Exception:
                pass
            return

        canvas_w, canvas_h = self._get_preview_canvas_size()
        if canvas_w <= 0.0 or canvas_h <= 0.0:
            return

        wraplength = max(130, min(185, int(canvas_w * 0.18)))
        try:
            label.configure(text=overlay_text, wraplength=wraplength)
        except Exception:
            pass

        try:
            overlay.update_idletasks()
        except Exception:
            pass

        try:
            overlay_w = float(max(0, int(overlay.winfo_reqwidth() or overlay.winfo_width() or 0)))
            overlay_h = float(max(0, int(overlay.winfo_reqheight() or overlay.winfo_height() or 0)))
        except Exception:
            overlay_w = 0.0
            overlay_h = 0.0

        anchor = self._resolve_preview_typing_overlay_anchor(overlay_w, overlay_h)
        if anchor is None:
            try:
                overlay.place_forget()
            except Exception:
                pass
            return
        x, y = anchor

        try:
            overlay.place(in_=canvas, x=x, y=y, anchor="nw")
            overlay.lift()
        except Exception:
            pass

    def _update_preview_edit_status(self, extra_message: str | None = None, tone: str = "muted", emphasis: bool | None = None):
        label_mode_active, label_input_active = self._get_preview_typing_state()
        message = str(extra_message or "").strip()
        overlay_only_message = ""
        overlay_available = self._preview_operation_overlay_available()

        if not message:
            if self._preview_char_add_requested():
                message = "Przytrzymaj D i przeciągnij LPM po tablicy, aby narysować nowy box."
                tone = "info"
                overlay_only_message = message if overlay_available else ""
            elif label_mode_active:
                overlay_only_message = self._format_preview_typing_status(persistent=True)
                message = "Tryb wpisywania znaków aktywny."
                tone = "info"
            elif label_input_active:
                overlay_only_message = self._format_preview_typing_status(persistent=False)
                message = "Aktywne pole znaku."
                tone = "info"
            elif bool(getattr(self, "_preview_char_edit_mode", False)):
                message = "Tryb edycji: S zaznacza lub odznacza hoverowany box, LPM+drag przesuwa zaznaczony box, uchwyty rogów zmieniają rozmiar, Alt+W włącza wpisywanie znaków, a strzałki lewo/prawo przełączają boxy."
                tone = "muted"
                overlay_only_message = message if overlay_available else ""
            else:
                message = "Q/E przełącza poprzednią/następną tablicę na liście, D+LPM rysuje nowy box, S zaznacza lub odznacza hoverowany box, Alt+W włącza wpisywanie znaków, Enter przełącza pełny ekran."
                tone = "muted"
                overlay_only_message = ""
        elif label_mode_active:
            overlay_only_message = self._format_preview_typing_status(message, persistent=True)
            message = "Tryb wpisywania znaków aktywny."
        elif label_input_active:
            overlay_only_message = self._format_preview_typing_status(message, persistent=False)
            message = "Aktywne pole znaku."
        elif overlay_available:
            overlay_only_message = message

        if emphasis is None:
            emphasis = False

        label = getattr(self, "preview_edit_status_lbl", None)
        use_canvas_overlay = bool(overlay_available)
        if use_canvas_overlay and label is not None:
            try:
                label.grid_remove()
            except Exception:
                pass

        try:
            self._preview_typing_overlay_text = str(overlay_only_message or "")
        except Exception:
            pass

        if not use_canvas_overlay:
            if hasattr(self, "preview_edit_status_var"):
                try:
                    self.preview_edit_status_var.set(message)
                except Exception:
                    pass
            if label is not None:
                self._set_inline_status_label_state(label, text=message, tone=tone, emphasis=bool(emphasis))

        self._sync_preview_edit_status_visibility()
        self._refresh_preview_typing_overlay_visibility()

    def _get_preview_char_label_canvas_rect(self, rec) -> tuple[float, float, float, float] | None:
        bbox = self._char_record_bbox(rec)
        if not bbox:
            return None
        cx1, cy1 = self._preview_image_to_canvas_point(bbox[0], bbox[1])
        cx2, _cy2 = self._preview_image_to_canvas_point(bbox[2], bbox[3])
        label_w = min(max(18.0, (cx2 - cx1) * 0.34), 28.0)
        label_h = 18.0
        inset = 2.0
        return (
            float(cx1 + inset),
            float(cy1 + inset),
            float(cx1 + inset + label_w),
            float(cy1 + inset + label_h),
        )

    def _find_preview_char_label_hit(self, canvas_x: float, canvas_y: float):
        if (
            not bool(getattr(self, "_preview_char_label_mode", False))
            and getattr(self, "_preview_char_label_active_index", None) is None
        ):
            return None
        chars = self._get_preview_active_character_records(create=False)
        for idx, rec in enumerate(chars):
            rect = self._get_preview_char_label_canvas_rect(rec)
            if rect is None:
                continue
            rx1, ry1, rx2, ry2 = rect
            pad = 2.0
            if (rx1 - pad) <= float(canvas_x) <= (rx2 + pad) and (ry1 - pad) <= float(canvas_y) <= (ry2 + pad):
                return idx
        return None

    def _resolve_preview_char_label_target_index(self, *, prefer_hover: bool = True) -> int | None:
        chars = self._get_preview_active_character_records(create=False)
        if not isinstance(chars, list) or not chars:
            return None

        total = len(chars)

        def _safe_index(value) -> int | None:
            try:
                idx = int(value)
            except Exception:
                return None
            return idx if 0 <= idx < total else None

        hover_idx = _safe_index(getattr(self, "_preview_char_hover_label_index", None))
        if hover_idx is None and bool(getattr(self, "_preview_char_label_mode", False)):
            hover_idx = _safe_index(getattr(self, "_preview_char_hover_index", None))
        active_idx = _safe_index(getattr(self, "_preview_char_label_active_index", None))
        selected_idx = _safe_index(getattr(self, "_preview_char_selected_index", None))

        ordered_candidates = (
            (hover_idx, active_idx, selected_idx)
            if bool(prefer_hover)
            else (active_idx, hover_idx, selected_idx)
        )
        for idx in ordered_candidates:
            if idx is not None:
                return idx
        return 0

    def _get_leftmost_preview_char_index(self, chars=None) -> int | None:
        local_chars = chars if isinstance(chars, list) else self._get_preview_active_character_records(create=False)
        if not isinstance(local_chars, list) or not local_chars:
            return None

        ordered_chars = self._sort_character_records_by_x(list(local_chars))
        target_rec = ordered_chars[0] if ordered_chars else None
        if target_rec is None:
            return None
        return self._find_preview_char_record_index(local_chars, target_rec)

    def _resolve_preview_char_label_entry_index(self) -> int | None:
        chars = self._get_preview_active_character_records(create=False)
        if not isinstance(chars, list) or not chars:
            return None

        total = len(chars)

        def _safe_index(value) -> int | None:
            try:
                idx = int(value)
            except Exception:
                return None
            return idx if 0 <= idx < total else None

        explicit_hover_idx = _safe_index(getattr(self, "_preview_char_hover_label_index", None))
        if explicit_hover_idx is None:
            explicit_hover_idx = _safe_index(getattr(self, "_preview_char_hover_index", None))
        if explicit_hover_idx is not None:
            return explicit_hover_idx

        explicit_active_idx = _safe_index(getattr(self, "_preview_char_label_active_index", None))
        if explicit_active_idx is not None:
            return explicit_active_idx

        return self._get_leftmost_preview_char_index(chars)

    def _activate_preview_char_label_input(self, char_idx: int | None, *, keep_selection: bool = True, status_message: str | None = None):
        if char_idx is None:
            self._preview_char_label_active_index = None
        else:
            self._preview_char_label_active_index = int(char_idx)
            if keep_selection:
                self._preview_char_selected_index = int(char_idx)
            self._preview_char_hover_label_index = int(char_idx)
        if status_message:
            self._update_preview_edit_status(status_message, tone="info")
        else:
            self._update_preview_edit_status()
        self._focus_preview_canvas()
        self._on_preview_select(None)

    def _assign_character_to_active_preview_label(self, symbol: str):
        idx = getattr(self, "_preview_char_label_active_index", None)
        chars = self._get_preview_active_character_records(create=False)
        if idx is None or not (0 <= int(idx) < len(chars)):
            return False

        symbol = self._sanitize_preview_char_symbol(symbol)
        if not symbol:
            return False

        rec = chars[int(idx)]
        if self._sanitize_preview_char_symbol(rec.get("character", "")) == symbol:
            self._preview_char_selected_index = int(idx)
            self._preview_char_label_active_index = int(idx)
            self._preview_char_hover_label_index = int(idx)
            self._update_preview_edit_status(
                "Znak już ma taką wartość. Użyj strzałek lewo/prawo albo kliknij inny box LPM.",
                tone="muted",
            )
            self._on_preview_select(None)
            return True
        self._push_preview_history_snapshot()
        rec["character"] = symbol
        self._mark_preview_char_record_manual(rec)
        self._preview_char_selected_index = int(idx)
        self._preview_char_label_active_index = int(idx)
        self._preview_char_hover_label_index = int(idx)
        self._persist_active_preview_characters(
            selected_record=rec,
            success_message=f"Zapisano znak {symbol} w metadata.json.",
        )
        if bool(getattr(self, "_preview_char_label_mode", False)):
            self._update_preview_edit_status(
                f"Zapisano znak {symbol}. Użyj strzałek lewo/prawo albo kliknij kolejny box LPM.",
                tone="success",
            )
        return True

    def _reset_current_preview_view(self):
        plate_id = str(getattr(self, "_preview_active_pid", "") or "")
        if plate_id:
            self._preview_badge_offsets.pop(plate_id, None)
        self._reset_preview_view_state()
        if getattr(self, "preview_canvas", None) is not None:
            self._on_preview_select(None)

    def _init_preview_vertical_split(self):
        pane = getattr(self, "preview_vertical_split", None)
        if pane is None or self._preview_vertical_split_ready:
            return

        try:
            total_w = int(pane.winfo_width() or 0)
            if total_w < 240:
                self.frame.after(120, self._init_preview_vertical_split)
                return
            total_w = max(760, total_w)
            min_left = 240
            max_left = 340
            target_x = max(min_left, min(int(total_w * 0.28), max_left))
            pane.sash_place(0, target_x, 1)
            self._preview_vertical_split_ready = True
        except Exception:
            pass

    def _apply_preview_badge_selection_style(self):
        canvas = getattr(self, "preview_canvas", None)
        if canvas is None:
            return

        for badge_key, runtime in getattr(self, "_preview_badge_runtime", {}).items():
            is_selected = str(badge_key) == str(getattr(self, "_preview_selected_badge_key", None))
            box_color = str(runtime.get("box_color", "#cccccc"))
            line_color = str(runtime.get("line_color", "#cccccc"))
            box_width = 4 if is_selected else int(runtime.get("box_width", 2))
            line_width = 3 if is_selected else int(runtime.get("line_width", 1))

            try:
                canvas.itemconfigure(runtime.get("box_id"), outline=box_color, width=box_width)
            except Exception:
                pass

            try:
                canvas.itemconfigure(runtime.get("line_id"), fill=line_color, width=line_width)
            except Exception:
                pass

    def _set_preview_selected_badge(self, badge_key: str = None):
        self._preview_selected_badge_key = str(badge_key) if badge_key else None
        self._apply_preview_badge_selection_style()

    def _move_preview_badge_to_offset(self, badge_key: str, dx: float, dy: float):
        runtime = self._preview_badge_runtime.get(str(badge_key))
        canvas = getattr(self, "preview_canvas", None)
        if runtime is None or canvas is None:
            return

        dx, dy = self._clamp_preview_badge_offset(badge_key, dx, dy)

        prev_dx = float(runtime.get("offset_dx", 0.0))
        prev_dy = float(runtime.get("offset_dy", 0.0))
        delta_x = float(dx) - prev_dx
        delta_y = float(dy) - prev_dy

        if abs(delta_x) > 0.001 or abs(delta_y) > 0.001:
            try:
                canvas.move(runtime["tag"], delta_x, delta_y)
            except Exception:
                pass

        runtime["offset_dx"] = float(dx)
        runtime["offset_dy"] = float(dy)

        try:
            canvas.coords(
                runtime["line_id"],
                float(runtime["base_center_x"]) + float(dx),
                float(runtime["base_bottom_y"]) + float(dy),
                float(runtime["box_center_x"]),
                float(runtime["box_top_y"]),
            )
        except Exception:
            pass

    def _on_preview_canvas_configure(self, event=None):
        self._ensure_preview_mode_overlay_position()
        self._refresh_preview_typing_overlay_visibility()
        self._on_preview_select(None)

    def _schedule_preview_stabilized_rerender(self, delay_ms: int = 35):
        canvas = getattr(self, "preview_canvas", None)
        if canvas is None:
            return

        previous_after_id = getattr(self, "_preview_stabilized_render_after_id", None)
        if previous_after_id:
            try:
                canvas.after_cancel(previous_after_id)
            except Exception:
                pass
            self._preview_stabilized_render_after_id = None

        def _rerender_after_layout_settles():
            self._preview_stabilized_render_after_id = None
            if getattr(self, "preview_canvas", None) is None:
                return
            if not bool(getattr(self, "_preview_active_pid", None)):
                return
            try:
                self.preview_canvas.delete("all")
                self.preview_canvas.update_idletasks()
            except Exception:
                pass
            self._on_preview_select(None)
            try:
                self.preview_canvas.update_idletasks()
            except Exception:
                pass

        try:
            self._preview_stabilized_render_after_id = canvas.after(
                max(1, int(delay_ms)),
                _rerender_after_layout_settles,
            )
        except Exception:
            self._preview_stabilized_render_after_id = None

    def _on_preview_mode_eye_press(self, event=None):
        if event is None:
            return "break"
        self._preview_mode_eye_drag_state = {
            "start_x": float(event.x_root),
            "start_y": float(event.y_root),
            "origin_x": float((getattr(self, "_preview_mode_overlay_position", {}) or {}).get("x", 12.0)),
            "origin_y": float((getattr(self, "_preview_mode_overlay_position", {}) or {}).get("y", 12.0)),
            "dragged": False,
        }
        return "break"

    def _on_preview_mode_eye_drag(self, event=None):
        drag_state = getattr(self, "_preview_mode_eye_drag_state", None)
        if not isinstance(drag_state, dict) or event is None:
            return "break"

        delta_x = float(event.x_root) - float(drag_state.get("start_x", 0.0))
        delta_y = float(event.y_root) - float(drag_state.get("start_y", 0.0))
        if abs(delta_x) >= 3.0 or abs(delta_y) >= 3.0:
            drag_state["dragged"] = True

        new_x, new_y = self._clamp_preview_mode_overlay_position(
            float(drag_state.get("origin_x", 12.0)) + delta_x,
            float(drag_state.get("origin_y", 12.0)) + delta_y,
        )
        self._preview_mode_overlay_position = {"x": float(new_x), "y": float(new_y)}
        self._ensure_preview_mode_overlay_position()
        return "break"

    def _on_preview_mode_eye_release(self, event=None):
        drag_state = getattr(self, "_preview_mode_eye_drag_state", None)
        self._preview_mode_eye_drag_state = None
        if isinstance(drag_state, dict) and bool(drag_state.get("dragged")):
            self._focus_preview_canvas()
            return "break"
        return self._toggle_preview_mode_overlay()

    def _get_preview_selected_char_record(self):
        chars = self._get_preview_active_character_records(create=False)
        idx = getattr(self, "_preview_char_selected_index", None)
        if idx is None:
            return None, None
        try:
            idx = int(idx)
        except Exception:
            self._preview_char_selected_index = None
            return None, None
        if not (0 <= idx < len(chars)):
            self._preview_char_selected_index = None
            return None, None
        return idx, chars[idx]

    def _preview_char_add_requested(self) -> bool:
        return bool(
            getattr(self, "_preview_char_add_state", None) is not None
            or getattr(self, "_preview_char_add_mode", False)
            or getattr(self, "_preview_char_add_modifier_down", False)
        )

    @staticmethod
    def _find_preview_char_record_index(chars, target_record) -> int | None:
        if not isinstance(chars, list) or target_record is None:
            return None
        for idx, rec in enumerate(chars):
            if rec is target_record:
                return idx
        return None

    def _select_preview_character_box(self, char_idx: int | None, *, activate_label: bool = False, status_message: str | None = None):
        chars = self._get_preview_active_character_records(create=False)
        if not isinstance(chars, list) or not chars:
            self._preview_char_selected_index = None
            self._preview_char_label_active_index = None
            self._preview_char_hover_label_index = None
            self._refresh_preview_editor_toolbar()
            self._update_preview_edit_status("Brak boxów znaków do zaznaczenia.", tone="warning")
            self._on_preview_select(None)
            return "break"

        try:
            safe_idx = max(0, min(int(char_idx), len(chars) - 1))
        except Exception:
            self._update_preview_edit_status("Nie udało się zaznaczyć boxu znaku.", tone="warning")
            return "break"

        self._ensure_preview_final_box_mode()
        label_mode_active = bool(getattr(self, "_preview_char_label_mode", False))
        self._preview_char_edit_mode = False if label_mode_active else True
        self._preview_char_add_mode = False
        self._preview_char_add_modifier_down = False
        self._preview_char_add_state = None
        self._preview_char_selected_index = safe_idx
        self._preview_char_hover_index = safe_idx
        label_target_active = bool(activate_label or label_mode_active)
        self._preview_char_hover_label_index = safe_idx if label_target_active else None
        self._preview_char_label_active_index = safe_idx if label_target_active else None
        self._refresh_preview_editor_toolbar()
        self._update_preview_edit_status(
            status_message or (
                "Tryb wpisywania znaków jest aktywny. Kliknij kolejny box LPM albo użyj strzałek lewo/prawo, a potem wpisz znak."
                if label_mode_active else
                "Box znaku jest aktywny. LPM+drag przesuwa, uchwyty zmieniają rozmiar, PPM usuwa aktywny box, a Alt+W włącza wpisywanie znaków."
            ),
            tone="info",
        )
        self._focus_preview_canvas()
        self._on_preview_select(None)
        return "break"

    def _select_hovered_preview_char_box(self, event=None):
        hover_idx = getattr(self, "_preview_char_hover_index", None)
        if hover_idx is None:
            selected_idx, _selected_rec = self._get_preview_selected_char_record()
            if selected_idx is not None:
                self._preview_char_selected_index = None
                self._preview_char_label_active_index = None
                self._preview_char_hover_label_index = None
                self._refresh_preview_editor_toolbar()
                self._update_preview_edit_status("Odznaczono aktywny box znaku.", tone="muted")
                self._on_preview_select(None)
                return "break"
            self._update_preview_edit_status("Najedź kursorem na box i naciśnij S, aby go zaznaczyć.", tone="warning")
            return "break"
        selected_idx, _selected_rec = self._get_preview_selected_char_record()
        if selected_idx is not None and int(selected_idx) == int(hover_idx):
            self._preview_char_selected_index = None
            self._preview_char_label_active_index = None
            self._preview_char_hover_label_index = None
            self._refresh_preview_editor_toolbar()
            self._update_preview_edit_status("Odznaczono hoverowany box znaku.", tone="muted")
            self._on_preview_select(None)
            return "break"
        return self._select_preview_character_box(
            int(hover_idx),
            activate_label=False,
            status_message="Zaznaczono hoverowany box. PPM usuwa aktywny box, a S ponownie go odznacza.",
        )

    def _cycle_preview_character_selection(self, step: int, *, activate_label: bool = False):
        chars = self._get_preview_active_character_records(create=False)
        if not isinstance(chars, list) or not chars:
            self._update_preview_edit_status("Brak boxów znaków do przełączenia.", tone="warning")
            return "break"

        ordered_chars = self._sort_character_records_by_x(list(chars))
        selected_idx, selected_rec = self._get_preview_selected_char_record()
        ordered_pos = None
        if selected_rec is not None:
            for idx, rec in enumerate(ordered_chars):
                if rec is selected_rec:
                    ordered_pos = idx
                    break

        if ordered_pos is None:
            target_pos = 0 if int(step) >= 0 else (len(ordered_chars) - 1)
        else:
            target_pos = (int(ordered_pos) + int(step)) % len(ordered_chars)

        target_rec = ordered_chars[int(target_pos)]
        target_idx = self._find_preview_char_record_index(chars, target_rec)
        if target_idx is None:
            if selected_idx is not None:
                target_idx = max(0, min(int(selected_idx), len(chars) - 1))
            else:
                target_idx = 0

        return self._select_preview_character_box(
            int(target_idx),
            activate_label=(activate_label or bool(getattr(self, "_preview_char_label_mode", False))),
            status_message=(
                f"Wybrano box {int(target_pos) + 1}/{len(ordered_chars)} według rosnącego X. "
                + (
                    "Wpisz znak z klawiatury, aby nadpisać etykietę."
                    if bool(getattr(self, "_preview_char_label_mode", False))
                    else "Strzałki lewo/prawo przełączają kolejne boxy."
                )
            ),
        )

    def _get_preview_char_handle_radius(self) -> float:
        state = getattr(self, "_preview_render_state", None) or {}
        scale = float(state.get("scale", 1.0) or 1.0)
        return max(5.0, min(9.0, 4.0 + (scale * 0.12)))

    def _find_preview_character_box_hit(self, canvas_x: float, canvas_y: float):
        chars = self._get_preview_active_character_records(create=False)
        for idx in range(len(chars) - 1, -1, -1):
            bbox = self._char_record_bbox(chars[idx])
            if not bbox:
                continue
            cx1, cy1 = self._preview_image_to_canvas_point(bbox[0], bbox[1])
            cx2, cy2 = self._preview_image_to_canvas_point(bbox[2], bbox[3])
            pad = 3.0
            if (cx1 - pad) <= float(canvas_x) <= (cx2 + pad) and (cy1 - pad) <= float(canvas_y) <= (cy2 + pad):
                return idx
        return None

    def _find_preview_character_handle_hit(self, canvas_x: float, canvas_y: float):
        idx, rec = self._get_preview_selected_char_record()
        if rec is None:
            return None

        bbox = self._char_record_bbox(rec)
        if not bbox:
            return None

        cx1, cy1 = self._preview_image_to_canvas_point(bbox[0], bbox[1])
        cx2, cy2 = self._preview_image_to_canvas_point(bbox[2], bbox[3])
        radius = self._get_preview_char_handle_radius()
        handles = {
            "nw": (cx1, cy1),
            "ne": (cx2, cy1),
            "sw": (cx1, cy2),
            "se": (cx2, cy2),
        }
        for handle_name, (hx, hy) in handles.items():
            if abs(float(canvas_x) - float(hx)) <= radius and abs(float(canvas_y) - float(hy)) <= radius:
                return idx, handle_name
        return None

    @staticmethod
    def _get_preview_character_canvas_tag(box_source: str, box_idx: int) -> str:
        return f"preview_char::{box_source}:{int(box_idx)}"

    def _redraw_preview_add_box_overlay_only(self) -> bool:
        canvas = getattr(self, "preview_canvas", None)
        if canvas is None:
            return False

        try:
            canvas.delete("preview_char_add_preview")
        except Exception:
            pass

        add_state = getattr(self, "_preview_char_add_state", None)
        if not isinstance(add_state, dict):
            return True

        preview_bbox = add_state.get("bbox")
        if not isinstance(preview_bbox, (list, tuple)) or len(preview_bbox) < 4:
            return True

        try:
            ax1, ay1, ax2, ay2 = (float(v) for v in preview_bbox[:4])
        except Exception:
            return False
        if ax2 < ax1:
            ax1, ax2 = ax2, ax1
        if ay2 < ay1:
            ay1, ay2 = ay2, ay1

        add_cx1, add_cy1 = self._preview_image_to_canvas_point(ax1, ay1)
        add_cx2, add_cy2 = self._preview_image_to_canvas_point(ax2, ay2)
        selection_color = getattr(self.app, "palette", {}).get("accent", "#ffd166")
        try:
            canvas.create_rectangle(
                add_cx1,
                add_cy1,
                add_cx2,
                add_cy2,
                outline=selection_color,
                width=2,
                dash=(5, 3),
                tags=("preview_char_add_preview",),
            )
            canvas.create_text(
                add_cx1 + 4,
                max(8, add_cy1 - 8),
                text="Nowy box",
                fill=selection_color,
                font=("Segoe UI", 8, "bold"),
                anchor=tk.SW,
                tags=("preview_char_add_preview",),
            )
            return True
        except Exception:
            return False

    def _redraw_preview_character_overlay_only(self, char_idx: int) -> bool:
        canvas = getattr(self, "preview_canvas", None)
        state = getattr(self, "_preview_render_state", None) or {}
        if canvas is None or not state:
            return False

        data = self._get_preview_active_data(create=False)
        if not isinstance(data, dict):
            return False

        box_chars, box_source = self._get_preview_box_records(data)
        if str(box_source) != "FINAL":
            return False
        try:
            char_idx = int(char_idx)
        except Exception:
            return False
        if not (0 <= char_idx < len(box_chars)):
            return False

        c = box_chars[char_idx]
        if not isinstance(c, dict):
            return False
        bbox = self._char_record_bbox(c)
        if not bbox:
            return False

        tag = self._get_preview_character_canvas_tag(box_source, char_idx)
        tags = ("preview_char", tag)
        try:
            canvas.delete(tag)
        except Exception:
            pass

        try:
            render_scale = max(0.001, float(state.get("scale", 1.0) or 1.0))
            x_off = float(state.get("image_left", 0.0) or 0.0)
            y_off = float(state.get("image_top", 0.0) or 0.0)
            image_bottom_y = float(state.get("image_bottom", 0.0) or 0.0)
            c_h = max(50, int(canvas.winfo_height() or 50))
        except Exception:
            return False

        x1, y1, x2, y2 = bbox[:4]
        cx1, cy1 = (float(x1) * render_scale) + x_off, (float(y1) * render_scale) + y_off
        cx2, cy2 = (float(x2) * render_scale) + x_off, (float(y2) * render_scale) + y_off
        center_x = cx1 + (cx2 - cx1) / 2.0

        source_tag = self._get_character_source_tag(c, data=data, fallback_index=char_idx)
        source_style = self._get_preview_source_visual_style(source_tag)
        box_color = source_style["outline"]
        guide_color = source_style["guide"]
        char_fill = box_color
        selection_color = getattr(self.app, "palette", {}).get("accent", "#ffd166")
        label_focus_color = getattr(self.app, "palette", {}).get("warning", "#f59e0b")
        selected_idx = getattr(self, "_preview_char_selected_index", None)
        is_selected_box = bool(selected_idx is not None and int(selected_idx) == int(char_idx))

        try:
            box_id = canvas.create_rectangle(
                cx1,
                cy1,
                cx2,
                cy2,
                outline=box_color,
                width=(3 if is_selected_box else 2),
                tags=tags,
            )
            if is_selected_box:
                canvas.create_rectangle(
                    cx1 - 2,
                    cy1 - 2,
                    cx2 + 2,
                    cy2 + 2,
                    outline=selection_color,
                    width=1,
                    dash=(4, 2),
                    tags=tags,
                )

            text_anchor_y = min(c_h - 24, image_bottom_y + 35)
            canvas.create_line(
                center_x,
                cy2,
                center_x,
                text_anchor_y - 20,
                fill=guide_color,
                dash=(2, 2),
                tags=tags,
            )
            char_text = str(c.get("character", ""))
            canvas.create_text(
                center_x + 1,
                text_anchor_y + 1,
                text=char_text,
                fill="#000000",
                font=("Segoe UI", 18, "bold"),
                anchor=tk.CENTER,
                tags=tags,
            )
            canvas.create_text(
                center_x,
                text_anchor_y,
                text=char_text,
                fill=char_fill,
                font=("Segoe UI", 18, "bold"),
                anchor=tk.CENTER,
                tags=tags,
            )

            if is_selected_box and bool(getattr(self, "_preview_char_edit_mode", False)):
                handle_radius = self._get_preview_char_handle_radius()
                for handle_x, handle_y in ((cx1, cy1), (cx2, cy1), (cx1, cy2), (cx2, cy2)):
                    canvas.create_rectangle(
                        handle_x - handle_radius,
                        handle_y - handle_radius,
                        handle_x + handle_radius,
                        handle_y + handle_radius,
                        fill=selection_color,
                        outline="#111111",
                        width=1,
                        tags=tags,
                    )

            label_mode_active = bool(getattr(self, "_preview_char_label_mode", False))
            active_label_idx = getattr(self, "_preview_char_label_active_index", None)
            hover_label_idx = getattr(self, "_preview_char_hover_label_index", None)
            show_label_box = bool(
                label_mode_active
                or (active_label_idx is not None and int(active_label_idx) == int(char_idx))
                or (
                    hover_label_idx is not None
                    and int(hover_label_idx) == int(char_idx)
                    and (label_mode_active or active_label_idx is not None)
                )
            )
            if show_label_box:
                label_rect = self._get_preview_char_label_canvas_rect(c)
                if label_rect is not None:
                    lx1, ly1, lx2, ly2 = label_rect
                    label_active = bool(active_label_idx is not None and int(active_label_idx) == int(char_idx))
                    label_hovered = bool(hover_label_idx is not None and int(hover_label_idx) == int(char_idx))
                    label_highlight = bool(label_active or label_hovered)
                    label_accent = label_focus_color if (label_mode_active and label_highlight) else selection_color
                    label_fill = blend_hex_colors("#ffffff", label_accent, 0.22 if label_highlight else 0.08)
                    canvas.create_rectangle(
                        lx1,
                        ly1,
                        lx2,
                        ly2,
                        fill=label_fill,
                        outline=(label_accent if label_highlight else box_color),
                        width=(2 if label_active else 1),
                        tags=tags,
                    )
                    valid_char = self._sanitize_preview_char_symbol(char_text)
                    if valid_char:
                        canvas.create_text(
                            (lx1 + lx2) / 2.0,
                            (ly1 + ly2) / 2.0 + 0.5,
                            text=valid_char,
                            fill="#111111",
                            font=("Segoe UI", 8, "bold"),
                            anchor=tk.CENTER,
                            tags=tags,
                        )
                    elif label_active:
                        canvas.create_line(
                            lx1 + 7,
                            ly1 + 4,
                            lx1 + 7,
                            ly2 - 4,
                            fill="#111111",
                            width=1,
                            tags=tags,
                        )
        except Exception:
            return False

        runtime_map = getattr(self, "_preview_char_runtime", None)
        if not isinstance(runtime_map, dict):
            runtime_map = {}
            self._preview_char_runtime = runtime_map
        runtime_map[f"{box_source}:{char_idx}"] = {"tag": tag, "box_id": box_id}

        badge_key = f"{box_source}:{char_idx}"
        badge_runtime = getattr(self, "_preview_badge_runtime", {}).get(badge_key)
        if isinstance(badge_runtime, dict):
            badge_runtime["box_id"] = box_id
            line_id = badge_runtime.get("line_id")
            if line_id is not None:
                try:
                    badge_center_x = float(badge_runtime.get("base_center_x", center_x)) + float(badge_runtime.get("offset_dx", 0.0))
                    badge_bottom_y = float(badge_runtime.get("base_bottom_y", cy1)) + float(badge_runtime.get("offset_dy", 0.0))
                    canvas.coords(line_id, badge_center_x, badge_bottom_y, center_x, cy1)
                except Exception:
                    pass

        try:
            canvas.tag_raise(tag)
            canvas.tag_raise("preview_char_add_preview")
            canvas.tag_raise("preview_overlay_action")
            canvas.tag_raise("preview_overlay")
        except Exception:
            pass
        return True

    def _refresh_preview_editor_toolbar(self):
        hidden_controls = getattr(self, "preview_hidden_controls", None)
        if hidden_controls is not None:
            try:
                if not str(hidden_controls.winfo_manager()):
                    return
            except Exception:
                pass

        active_data = self._get_preview_active_data(create=False)
        has_plate = isinstance(active_data, dict)
        selected_idx, _selected_rec = self._get_preview_selected_char_record()
        has_selection = selected_idx is not None

        button_specs = (
            ("preview_edit_toggle_btn", has_plate, "Edytuj boxy", "Edytowanie boxów"),
            ("preview_add_box_btn", has_plate, "Nowy box", "Rysowanie boxu"),
            ("preview_edit_char_btn", has_selection, "Zmień znak", "Zmień znak"),
            ("preview_delete_char_btn", has_selection, "Usuń box", "Usuń box"),
        )

        for attr_name, enabled, idle_text, active_text in button_specs:
            widget = getattr(self, attr_name, None)
            if widget is None:
                continue
            is_active = bool(
                (attr_name == "preview_edit_toggle_btn" and getattr(self, "_preview_char_edit_mode", False))
                or (attr_name == "preview_add_box_btn" and getattr(self, "_preview_char_add_mode", False))
            )
            try:
                widget.configure(
                    state=(tk.NORMAL if enabled else tk.DISABLED),
                    text=(active_text if is_active else idle_text),
                )
            except Exception:
                pass

        try:
            self._update_preview_toolbar_state()
        except Exception:
            pass
    def _ensure_preview_final_box_mode(self):
        if self._get_preview_box_mode_key() == "FINAL":
            return
        try:
            self.preview_box_mode_var.set(PREVIEW_BOX_MODE_LABELS["FINAL"])
        except Exception:
            pass
        self._on_preview_box_mode_change()

    def _set_preview_char_editor_modes(self, *, edit: bool | None = None, add: bool | None = None, message: str | None = None):
        if edit is not None:
            self._preview_char_edit_mode = bool(edit)
            if not self._preview_char_edit_mode:
                self._preview_char_drag_state = None
            else:
                self._preview_char_label_mode = False
                self._preview_char_label_active_index = None
                self._preview_char_hover_label_index = None
        if add is not None:
            self._preview_char_add_mode = bool(add)
            if not self._preview_char_add_mode:
                self._preview_char_add_state = None
            else:
                self._preview_char_label_mode = False
                self._preview_char_label_active_index = None
                self._preview_char_hover_label_index = None
        if bool(getattr(self, "_preview_char_add_mode", False)):
            self._preview_char_label_active_index = None
        self._refresh_preview_editor_toolbar()
        if message:
            self._set_preview_box_info(message, "info")
            self._update_preview_edit_status(message, tone="info")
        else:
            self._update_preview_edit_status()
        self._focus_preview_canvas()
        self._on_preview_select(None)

    def _toggle_preview_char_edit_mode(self, event=None):
        if self._get_preview_active_data(create=False) is None:
            self._set_preview_box_info("Najpierw wybierz tablicę z listy.", "warning")
            return "break"
        self._ensure_preview_final_box_mode()
        self._set_preview_char_editor_modes(
            edit=(not bool(getattr(self, "_preview_char_edit_mode", False))),
            add=False,
            message="Tryb korekty boxów znaków działa na wyniku końcowym.",
        )
        return "break"

    def _toggle_preview_char_add_mode(self, event=None):
        if self._get_preview_active_data(create=False) is None:
            self._set_preview_box_info("Najpierw wybierz tablicę z listy.", "warning")
            return "break"
        self._ensure_preview_final_box_mode()
        self._set_preview_char_editor_modes(
            edit=False,
            add=(not bool(getattr(self, "_preview_char_add_mode", False))),
            message="Narysuj nowy box na znaku w podglądzie tablicy.",
        )
        return "break"

    def _toggle_preview_char_label_mode(self, event=None):
        if self._get_preview_active_data(create=False) is None:
            self._set_preview_box_info("Najpierw wybierz tablicę z listy.", "warning")
            return "break"

        self._ensure_preview_final_box_mode()
        next_state = not bool(getattr(self, "_preview_char_label_mode", False))
        self._preview_char_label_mode = next_state
        self._preview_char_edit_mode = False
        self._preview_char_add_mode = False
        self._preview_char_add_modifier_down = False
        self._preview_char_add_state = None
        self._preview_char_drag_state = None

        if next_state:
            target_idx = self._resolve_preview_char_label_entry_index()
            if target_idx is not None:
                self._preview_char_selected_index = int(target_idx)
                self._preview_char_hover_label_index = int(target_idx)
                self._preview_char_label_active_index = int(target_idx)
            self._update_preview_edit_status(
                "Tryb wpisywania znaków aktywny. Kliknij box LPM albo użyj strzałek lewo/prawo, a potem wpisz znak z klawiatury.",
                tone="info",
            )
        else:
            self._preview_char_hover_label_index = None
            self._preview_char_label_active_index = None
            self._update_preview_edit_status("Wylaczono tryb wpisywania znaków.", tone="muted")

        self._refresh_preview_editor_toolbar()
        self._focus_preview_canvas()
        self._apply_preview_canvas_cursor()
        self._on_preview_select(None)
        self._schedule_preview_stabilized_rerender()
        return "break"

    def _on_preview_char_label_shortcut(self, event=None):
        self._preview_alt_modifier_down = False
        return self._toggle_preview_char_label_mode(event)

    def _prompt_preview_char_symbol(self, initial_value: str = ""):
        current_value = self._sanitize_preview_char_symbol(initial_value)
        while True:
            value = self._prompt_dark_text_input(
                title="Znak tablicy",
                prompt="Podaj pojedynczy znak [0-9, A-Z]:",
                initial_value=current_value,
                width=420,
            )
            if value is None:
                return None
            normalized = self._sanitize_preview_char_symbol(value)
            if normalized:
                return normalized
            messagebox.showerror("Nieprawidłowy znak", "Wpisz pojedynczy znak z zakresu 0-9 lub A-Z.")

    def _prompt_dark_text_input(
        self,
        *,
        title: str,
        prompt: str,
        initial_value: str = "",
        width: int = 520,
    ) -> str | None:
        result = {"value": None}
        palette = getattr(self.app, "palette", {}) or {}

        dialog = tk.Toplevel(self.frame)
        try:
            dialog.withdraw()
        except Exception:
            pass

        dialog_styler = getattr(self.app, "style_dialog_window", None)
        if callable(dialog_styler):
            try:
                dialog_styler(
                    dialog,
                    title=str(title or "").strip(),
                    geometry=f"{int(max(420, width))}x220",
                    parent=self.frame,
                )
            except Exception:
                try:
                    dialog.title(str(title or "").strip())
                    dialog.resizable(False, False)
                except Exception:
                    pass
        else:
            try:
                dialog.title(str(title or "").strip())
                dialog.resizable(False, False)
            except Exception:
                pass

        panel_bg = palette.get("panel", "#252526")
        field_bg = palette.get("field", palette.get("panel_alt", "#2d2d30"))
        border = palette.get("panel_border", palette.get("border", "#3c3c3c"))
        fg = palette.get("fg", "#f3f3f3")
        muted = palette.get("muted", "#c7c7c7")

        try:
            dialog.configure(bg=panel_bg, highlightbackground=panel_bg, highlightcolor=panel_bg)
        except Exception:
            pass

        body_surface_builder = getattr(self.app, "_build_themed_dialog_surface", None)
        if callable(body_surface_builder):
            try:
                body_surface = body_surface_builder(dialog, tone="info")
            except Exception:
                body_surface = tk.Frame(dialog, bg=panel_bg, bd=0, highlightthickness=0)
                body_surface.pack(fill=tk.BOTH, expand=True)
        else:
            body_surface = tk.Frame(dialog, bg=panel_bg, bd=0, highlightthickness=0)
            body_surface.pack(fill=tk.BOTH, expand=True)

        body = tk.Frame(body_surface, bg=panel_bg, bd=0, highlightthickness=0)
        body.pack(fill=tk.BOTH, expand=True, padx=16, pady=16)

        tk.Label(
            body,
            text=str(prompt or "").strip(),
            bg=panel_bg,
            fg=muted,
            font=("Segoe UI", 9),
            anchor="w",
            justify=tk.LEFT,
            wraplength=max(360, int(width) - 100),
        ).pack(anchor=tk.W, fill=tk.X)

        entry = tk.Entry(
            body,
            bd=0,
            highlightthickness=1,
            relief=tk.FLAT,
            bg=field_bg,
            fg=fg,
            insertbackground=fg,
            highlightbackground=border,
            highlightcolor=border,
        )
        entry.pack(fill=tk.X, pady=(12, 0), ipady=6)
        try:
            entry.insert(0, str(initial_value or ""))
            entry.selection_range(0, tk.END)
        except Exception:
            pass

        buttons = tk.Frame(body, bg=panel_bg, bd=0, highlightthickness=0)
        buttons.pack(fill=tk.X, pady=(16, 0))

        def _close(value):
            result["value"] = value
            try:
                dialog.destroy()
            except Exception:
                pass

        ttk.Button(buttons, text="Anuluj", command=lambda: _close(None)).pack(side=tk.RIGHT)
        ttk.Button(buttons, text="OK", command=lambda: _close(entry.get())).pack(side=tk.RIGHT, padx=(0, 8))

        try:
            dialog.bind("<Return>", lambda _e: _close(entry.get()))
            dialog.bind("<Escape>", lambda _e: _close(None))
        except Exception:
            pass

        try:
            dialog.update_idletasks()
            dialog.deiconify()
            dialog.lift()
            entry.focus_force()
        except Exception:
            pass

        dialog.wait_window()
        return result.get("value")

    def _persist_active_preview_characters(self, *, selected_record=None, success_message: str):
        data = self._get_preview_active_data(create=True)
        previous_chars = list(data.get("characters", [])) if isinstance(data.get("characters"), list) else []
        previous_status = str(data.get("status", "unknown") or "unknown").strip().lower()
        chars = self._get_preview_active_character_records(create=True)
        normalized_chars = []
        for rec in list(chars):
            if not isinstance(rec, dict):
                continue
            bbox = self._normalize_preview_char_bbox(rec.get("bbox"))
            if bbox is None:
                continue
            rec["bbox"] = bbox
            normalized_chars.append(rec)

        sorted_chars = self._sort_character_records_by_x(normalized_chars)
        data["characters"] = sorted_chars
        status_now = self._derive_preview_status_from_data(data, sorted_chars)
        if (
            status_now == "perfect"
            and previous_status == "perfect"
            and len(sorted_chars) != len(previous_chars)
            and not self._get_preview_expected_texts(data)
        ):
            status_now = "needs_fix"
        data["status"] = status_now
        data["fusion_strategy"] = "manual_correction"
        data["fusion_details"] = {"source": "preview_editor"}
        self._ensure_plate_source_metadata(
            data,
            plate_id=str(getattr(self, "_preview_active_pid", "") or data.get("plate_id", "") or ""),
            default_bucket="local_manual",
            default_origin="preview_editor",
            modified_by="human",
        )

        if selected_record is not None:
            self._preview_char_selected_index = None
            for idx, rec in enumerate(sorted_chars):
                if rec is selected_record:
                    self._preview_char_selected_index = idx
                    break
        elif self._preview_char_selected_index is not None:
            self._preview_char_selected_index = min(int(self._preview_char_selected_index), len(sorted_chars) - 1) if sorted_chars else None

        status_suffix = "Status tablicy: OK." if status_now == "perfect" else "Status tablicy: wymaga korekty."
        live_message = f"{success_message} {status_suffix}".strip()
        live_tone = "success" if status_now == "perfect" else "info"
        self._refresh_preview_live_metadata_ui(
            status_message=live_message,
            status_tone=live_tone,
            render_preview=True,
        )
        try:
            self.frame.update_idletasks()
        except Exception:
            pass
        self._persist_preview_metadata(success_message=None, refresh_list=False)

    def _edit_selected_preview_char_symbol(self, event=None):
        idx, rec = self._get_preview_selected_char_record()
        if rec is None:
            self._set_preview_box_info("Najpierw zaznacz box znaku do korekty.", "warning")
            return "break"
        self._activate_preview_char_label_input(
            idx,
            status_message="Pole znaku jest aktywne tymczasowo. Wpisz 0-9 lub A-Z, aby nadpisać etykietę, albo Esc aby wyjść.",
        )
        return "break"

    def _edit_preview_source_filename(self, event=None):
        try:
            from ..campaign_manager import CAMPAIGN

            in_campaign = bool(CAMPAIGN.get_active_project_name())
        except Exception:
            in_campaign = False

        guidance_lines = [
            "Zmianę nazwy pliku źródłowego wykonuj w Z2, a nie w Z3/PZ2.",
            "",
            "Dlaczego:",
            "• Z2 pracuje jeszcze na obrazie źródłowym i całym workflow tablic.",
            "• Z3 powinno służyć już do pracy na wyciętych tablicach i znakach.",
            "",
            "W Z2 zmienisz nazwę bezpieczniej, zanim dane zostaną użyte w kolejnych etapach.",
        ]
        if in_campaign:
            guidance_lines.extend(
                [
                    "",
                    "Przejdź do wizarda i wróć do Z2, aby wykonać zmianę nazwy na właściwym etapie.",
                ]
            )

        messagebox.showinfo(
            "Zmiana nazwy w Z2",
            "\n".join(guidance_lines),
            parent=self.frame.winfo_toplevel() if self.frame is not None else None,
        )
        self._update_preview_edit_status(
            "Zmianę nazwy pliku źródłowego przenieśliśmy do Z2. W Z3/PZ2 ta operacja jest już tylko informacyjna.",
            tone="info",
        )
        self._focus_preview_canvas()
        return "break"

    def _delete_selected_preview_char_box(self, event=None):
        idx, rec = self._get_preview_selected_char_record()
        chars = self._get_preview_active_character_records(create=False)
        if rec is None or not isinstance(chars, list):
            self._set_preview_box_info("Najpierw zaznacz box klawiszem S, aby go usunąć.", "warning")
            self._update_preview_edit_status("Najpierw zaznacz box klawiszem S, a potem użyj PPM albo przycisku Usuń box.", tone="warning")
            return "break"

        self._push_preview_history_snapshot()
        try:
            chars.pop(idx)
        except Exception:
            return "break"

        self._preview_char_selected_index = min(idx, len(chars) - 1) if chars else None
        self._preview_char_label_active_index = None
        self._preview_char_hover_label_index = None
        self._persist_active_preview_characters(
            selected_record=(chars[self._preview_char_selected_index] if self._preview_char_selected_index is not None and chars else None),
            success_message="Usunięto box znaku i zapisano zmianę do metadata.json.",
        )
        return "break"

    def _on_preview_canvas_motion(self, event=None):
        if event is None:
            return
        if (
            self._preview_badge_drag_state is not None
            or self._preview_pan_drag_state is not None
            or self._preview_char_drag_state is not None
            or self._preview_char_add_state is not None
        ):
            return

        action_key = self._extract_preview_action_from_current_item()
        if action_key in {"reset_view", "edit_source_filename"}:
            had_hover = bool(
                getattr(self, "_preview_char_hover_index", None) is not None
                or getattr(self, "_preview_char_hover_label_index", None) is not None
            )
            self._preview_char_hover_index = None
            if not bool(getattr(self, "_preview_char_label_mode", False)):
                self._preview_char_hover_label_index = None
            self._apply_preview_canvas_cursor("hand2")
            if had_hover and bool(
                getattr(self, "_preview_char_label_mode", False)
                or getattr(self, "_preview_char_label_active_index", None) is not None
            ):
                self._on_preview_select(None)
            return

        self._apply_preview_canvas_cursor()
        label_mode_active = bool(getattr(self, "_preview_char_label_mode", False))
        next_hover_box = self._find_preview_character_box_hit(event.x, event.y)
        next_hover_label = self._find_preview_char_label_hit(event.x, event.y)
        if label_mode_active:
            next_hover_label = next_hover_box if next_hover_box is not None else next_hover_label
        elif bool(getattr(self, "_preview_char_edit_mode", False)) and getattr(self, "_preview_char_label_active_index", None) is None:
            next_hover_label = None
        if (
            next_hover_box == getattr(self, "_preview_char_hover_index", None)
            and next_hover_label == getattr(self, "_preview_char_hover_label_index", None)
        ):
            return

        previous_hover_box = getattr(self, "_preview_char_hover_index", None)
        previous_hover_label = getattr(self, "_preview_char_hover_label_index", None)
        self._preview_char_hover_index = next_hover_box
        self._preview_char_hover_label_index = next_hover_label
        if label_mode_active or getattr(self, "_preview_char_label_active_index", None) is not None:
            affected = {
                idx for idx in (previous_hover_box, previous_hover_label, next_hover_box, next_hover_label)
                if idx is not None
            }
            redrawn = False
            for idx in affected:
                redrawn = self._redraw_preview_character_overlay_only(int(idx)) or redrawn
            if not redrawn:
                self._on_preview_select(None)

    def _on_preview_canvas_leave(self, event=None):
        if (
            getattr(self, "_preview_char_hover_index", None) is None
            and getattr(self, "_preview_char_hover_label_index", None) is None
        ):
            self._apply_preview_canvas_cursor()
            return
        previous_hover_box = getattr(self, "_preview_char_hover_index", None)
        previous_hover_label = getattr(self, "_preview_char_hover_label_index", None)
        self._preview_char_hover_index = None
        self._preview_char_hover_label_index = None
        self._apply_preview_canvas_cursor()
        if bool(
            getattr(self, "_preview_char_label_mode", False)
            or getattr(self, "_preview_char_label_active_index", None) is not None
        ):
            affected = {idx for idx in (previous_hover_box, previous_hover_label) if idx is not None}
            redrawn = False
            for idx in affected:
                redrawn = self._redraw_preview_character_overlay_only(int(idx)) or redrawn
            if not redrawn:
                self._on_preview_select(None)

    def _on_preview_prev_shortcut(self, event=None):
        if (
            getattr(self, "_preview_char_label_active_index", None) is not None
            and not bool(getattr(self, "_preview_char_label_mode", False))
        ):
            return None
        if self._select_preview_relative(-1):
            self._update_preview_edit_status()
            return "break"
        return None

    def _on_preview_next_shortcut(self, event=None):
        if (
            getattr(self, "_preview_char_label_active_index", None) is not None
            and not bool(getattr(self, "_preview_char_label_mode", False))
        ):
            return None
        if self._select_preview_relative(1):
            self._update_preview_edit_status()
            return "break"
        return None

    def _on_preview_fit_shortcut(self, event=None):
        if not bool(getattr(self, "_preview_render_state", None)):
            return None
        self._reset_current_preview_view()
        self._update_preview_edit_status("Dopasowano widok tablicy.", tone="muted")
        return "break"

    def _on_preview_enter_fullscreen_shortcut(self, event=None):
        self._toggle_preview_fullscreen()
        return "break"

    def _on_preview_escape_shortcut(self, event=None):
        if bool(getattr(self, "_preview_char_label_mode", False)):
            self._preview_char_label_mode = False
            self._preview_char_hover_label_index = None
            self._preview_char_label_active_index = None
            self._refresh_preview_editor_toolbar()
            self._apply_preview_canvas_cursor()
            self._update_preview_edit_status("Wylaczono tryb wpisywania znaków klawiszem Esc.", tone="muted")
            self._on_preview_select(None)
            return "break"
        if getattr(self, "_preview_char_label_active_index", None) is not None:
            self._preview_char_label_active_index = None
            self._preview_char_hover_label_index = None
            self._refresh_preview_editor_toolbar()
            self._apply_preview_canvas_cursor()
            self._update_preview_edit_status("Zamknieto aktywne pole znaku klawiszem Esc.", tone="muted")
            self._on_preview_select(None)
            return "break"
        return None

    def _on_preview_canvas_keypress(self, event=None):
        if event is None:
            return None

        keysym = str(getattr(event, "keysym", "") or "").lower()
        if keysym in {"alt_l", "alt_r", "option_l", "option_r"}:
            self._preview_alt_modifier_down = True
            return "break"

        label_mode_active = bool(getattr(self, "_preview_char_label_mode", False))
        if self._event_has_control_modifier(event):
            if keysym == "z":
                return self._undo_preview_edit(event)
            if keysym == "y":
                return self._redo_preview_edit(event)

        active_label_idx = getattr(self, "_preview_char_label_active_index", None)
        if keysym in {"left", "right"} and (label_mode_active or active_label_idx is not None):
            step = -1 if keysym == "left" else 1
            return self._cycle_preview_character_selection(step, activate_label=True)
        typed_symbol = self._sanitize_preview_char_symbol(getattr(event, "char", ""))
        if active_label_idx is not None and typed_symbol:
            if self._assign_character_to_active_preview_label(typed_symbol):
                return "break"

        if keysym in {"return", "kp_enter"}:
            return self._on_preview_enter_fullscreen_shortcut(event)
        if keysym == "escape":
            return self._on_preview_escape_shortcut(event)
        if keysym == "q":
            return self._on_preview_prev_shortcut(event)
        if keysym == "e":
            return self._on_preview_next_shortcut(event)
        if keysym == "f":
            return self._on_preview_fit_shortcut(event)
        if keysym == "space":
            step = -1 if self._event_has_shift_modifier(event) else 1
            return self._cycle_preview_character_selection(
                step,
                activate_label=bool(getattr(self, "_preview_char_label_mode", False)),
            )
        if keysym == "d":
            if active_label_idx is None:
                self._ensure_preview_final_box_mode()
                self._preview_char_add_modifier_down = True
                self._apply_preview_canvas_cursor()
                self._update_preview_edit_status("Przytrzymaj D i przeciągnij LPM, aby narysować nowy box znaku.", tone="info")
                return "break"
            return None
        if keysym == "n":
            if active_label_idx is None:
                return self._toggle_preview_char_add_mode(event)
            return None
        if keysym == "s":
            if not bool(getattr(self, "_preview_char_label_mode", False)):
                return self._select_hovered_preview_char_box(event)
            return None
        if keysym == "t":
            if active_label_idx is None:
                return self._edit_selected_preview_char_symbol(event)
            return None
        return None

    def _on_preview_canvas_keyrelease(self, event=None):
        if event is None:
            return None
        keysym = str(getattr(event, "keysym", "") or "").lower()
        if keysym in {"alt_l", "alt_r", "option_l", "option_r"}:
            self._preview_alt_modifier_down = False
            return "break"
        if keysym == "d" and bool(getattr(self, "_preview_char_add_modifier_down", False)):
            self._preview_char_add_modifier_down = False
            self._apply_preview_canvas_cursor()
            if getattr(self, "_preview_char_add_state", None) is None:
                self._update_preview_edit_status()
            return "break"
        return None

    def _toggle_preview_fullscreen(self):
        self._set_preview_fullscreen(not bool(getattr(self, "_preview_fullscreen_active", False)))

    def _get_preview_legend_font(self, size: int, weight: str = "normal"):
        cache = getattr(self, "_preview_legend_font_cache", None)
        if cache is None:
            cache = {}
            self._preview_legend_font_cache = cache

        key = (int(size), str(weight))
        font_obj = cache.get(key)
        if font_obj is None:
            font_obj = tkfont.Font(self.frame, family="Segoe UI", size=int(size), weight=str(weight))
            cache[key] = font_obj
        return font_obj

    @staticmethod
    def _truncate_preview_filename(filename: str, max_chars: int = 44) -> str:
        text = str(filename or "").strip()
        if len(text) <= max_chars:
            return text
        head = max(10, (max_chars // 2) - 2)
        tail = max(10, max_chars - head - 3)
        return f"{text[:head]}...{text[-tail:]}"

    def _get_preview_legend_context(self):
        current_idx = self._get_current_preview_list_index()
        total = len(getattr(self, "_listbox_pid_by_index", []))
        current_no = (int(current_idx) + 1) if current_idx is not None and total > 0 else 0
        pid = str(getattr(self, "_preview_active_pid", "") or "Brak tablicy")
        active_data = self._get_preview_active_data(create=False) or {}
        source_image = str(active_data.get("source_image", "") or "")
        filename = self._truncate_preview_filename(Path(source_image).name if source_image else pid)
        chars = self._get_preview_active_character_records(create=False)
        mode_text = (
            "Tryb: nowy box" if self._preview_char_add_requested() else
            ("Tryb: znakowanie" if bool(getattr(self, "_preview_char_label_mode", False)) else
             ("Tryb: edycja" if self._preview_char_edit_mode else "Tryb: podgląd"))
        )
        return {
            "filename": filename or "Brak obrazu",
            "image_text": f"Tablica: {current_no}/{total}",
            "vehicle_text": mode_text,
            "plate_text": f"Boxy: {len(chars)}",
        }

    @staticmethod
    def _legend_color_is_light(color: str) -> bool:
        value = str(color or "").strip().lstrip("#")
        if len(value) == 3:
            value = "".join(ch * 2 for ch in value)
        if len(value) != 6:
            return False
        try:
            red = int(value[0:2], 16)
            green = int(value[2:4], 16)
            blue = int(value[4:6], 16)
        except Exception:
            return False
        luminance = ((0.2126 * red) + (0.7152 * green) + (0.0722 * blue)) / 255.0
        return luminance >= 0.62

    def _get_preview_legend_text_color(self, fill: str) -> str:
        palette = getattr(self.app, "palette", {})
        if self._legend_color_is_light(fill):
            return palette.get("fg", "#111111")
        return palette.get("accent_text", "#ffffff")

    @staticmethod
    def _hex_to_rgba(value: str, alpha: int = 255) -> tuple[int, int, int, int]:
        raw = str(value or "").strip().lstrip("#")
        if len(raw) == 3:
            raw = "".join(ch * 2 for ch in raw)
        try:
            return (
                int(raw[0:2], 16),
                int(raw[2:4], 16),
                int(raw[4:6], 16),
                int(alpha),
            )
        except Exception:
            return 32, 36, 42, int(alpha)

    def _get_preview_legend_compass_photo(self, theme: dict, *, size: int = 38):
        if not PIL_AVAILABLE:
            return None
        cache = getattr(self, "_preview_legend_image_cache", None)
        if cache is None:
            cache = {}
            self._preview_legend_image_cache = cache

        key = ("compass", int(size), str(theme.get("badge_plate_outline", "")), str(theme.get("token_fill", "")))
        photo = cache.get(key)
        if photo is not None:
            return photo

        scale = 6
        px = int(size * scale)
        img = Image.new("RGBA", (px, px), (0, 0, 0, 0))
        draw = ImageDraw.Draw(img)
        accent = self._hex_to_rgba(str(theme.get("badge_plate_outline", "#2fbf71")), 255)
        token_fill = self._hex_to_rgba(str(theme.get("token_fill", "#3c3c3c")), 245)
        north_fill = self._hex_to_rgba("#d64545", 255)
        south_fill = self._hex_to_rgba("#183a63", 248)
        guide_fill = self._hex_to_rgba("#d7dde4", 96)

        margin = int(2.5 * scale)
        outer = (margin, margin, px - margin, px - margin)
        inner_margin = int(10 * scale / 2.0)
        inner = (inner_margin, inner_margin, px - inner_margin, px - inner_margin)
        draw.ellipse(outer, outline=accent, width=max(2, scale))
        draw.ellipse(
            (margin + scale, margin + scale, px - margin - scale, px - margin - scale),
            outline=self._hex_to_rgba(blend_hex_colors(str(theme.get("badge_plate_outline", "#2fbf71")), "#ffffff", 0.25), 180),
            width=max(1, scale - 1),
        )
        draw.ellipse(inner, fill=token_fill)
        center = px / 2.0
        inner_r = (inner[2] - inner[0]) / 2.0
        draw.line((center, center - inner_r + (1.0 * scale), center, center + inner_r - (1.0 * scale)), fill=guide_fill, width=max(1, scale - 1))
        draw.line((center - inner_r + (1.0 * scale), center, center + inner_r - (1.0 * scale), center), fill=guide_fill, width=max(1, scale - 1))

        north = [
            (center, center - (14.5 * scale / 2.0)),
            (center + (2.9 * scale), center + (1.2 * scale)),
            (center, center - (2.4 * scale)),
            (center - (2.9 * scale), center + (1.2 * scale)),
        ]
        south = [
            (center, center + (14.5 * scale / 2.0)),
            (center + (2.6 * scale), center - (1.2 * scale)),
            (center, center + (2.4 * scale)),
            (center - (2.6 * scale), center - (1.2 * scale)),
        ]
        draw.polygon(north, fill=north_fill)
        draw.polygon(south, fill=south_fill)
        dot_r = 1.8 * scale
        draw.ellipse((center - dot_r, center - dot_r, center + dot_r, center + dot_r), fill=self._hex_to_rgba("#f3f3f3", 255))

        img = img.resize((int(size), int(size)), Image.Resampling.LANCZOS)
        photo = ImageTk.PhotoImage(img, master=self.frame)
        cache[key] = photo
        return photo

    def _is_preview_controls_legend_expanded(self) -> bool:
        if bool(getattr(self, "_preview_fullscreen_active", False)):
            return bool(getattr(self, "_preview_controls_legend_fullscreen_expanded", False))
        return bool(getattr(self, "_preview_controls_legend_inline_expanded", False))

    def _get_preview_controls_legend_context(self) -> dict:
        data = self._get_preview_active_data(create=False)
        pid = str(getattr(self, "_preview_active_pid", "") or "").strip()
        ordinal = self._get_plate_listbox_ordinal(pid) if pid else None
        total = len(getattr(self, "_listbox_pid_by_index", []) or [])
        source_image = str((data or {}).get("source_image", "") or "").strip() if isinstance(data, dict) else ""
        filename = self._truncate_preview_filename(Path(source_image).name if source_image else (pid or "Brak tablicy"), max_chars=30)
        status_meta = self._get_preview_status_presentation(data=data, plate_id=pid)
        chars = list((data or {}).get("characters", []) or []) if isinstance(data, dict) else []
        return {
            "filename": filename,
            "plate_text": f"{int(ordinal or 0)}/{int(total or 0)}" if total > 0 else "0/0",
            "box_text": str(int(len(chars))),
            "status_text": str(status_meta.get("canvas_text", "Nieocenione") or "Nieocenione"),
        }

    def _get_preview_legend_theme(self) -> dict:
        palette = getattr(self.app, "palette", {})
        panel = palette.get("panel", "#252526")
        panel_alt = palette.get("panel_alt", panel)
        field = palette.get("field", panel)
        border = palette.get("panel_border", palette.get("border", "#3c3c3c"))
        accent = palette.get("accent", "#0e639c")
        success = palette.get("success", "#2fbf71")
        warning = palette.get("warning", "#f59e0b")

        return {
            "canvas_bg": panel,
            "panel_fill": panel_alt,
            "panel_outline": border,
            "label_fill": palette.get("fg", "#f3f3f3"),
            "muted_fill": palette.get("muted_dim", palette.get("muted", "#8f98a3")),
            "entry_fill": blend_hex_colors(panel_alt, panel, 0.28),
            "entry_text": palette.get("fg", "#f3f3f3"),
            "section_fill": blend_hex_colors(panel_alt, panel, 0.18),
            "section_title": palette.get("fg", "#f3f3f3"),
            "section_muted": blend_hex_colors(palette.get("fg", "#f3f3f3"), panel_alt, 0.18),
            "token_fill": field,
            "token_text": palette.get("fg", "#f8fafc"),
            "badge_file_fill": palette.get("surface_info", blend_hex_colors(accent, panel_alt, 0.72)),
            "badge_file_outline": accent,
            "badge_image_fill": palette.get("surface_warning", blend_hex_colors(warning, panel_alt, 0.72)),
            "badge_image_outline": warning,
            "badge_plate_fill": palette.get("surface_success", blend_hex_colors(success, panel_alt, 0.72)),
            "badge_plate_outline": success,
        }

    def _measure_preview_legend_token(self, token_kind: str, token_text: str, font_obj) -> float:
        if token_kind == "mouse":
            return max(42.0, float(font_obj.measure(str(token_text))) + 32.0)
        return max(24.0, float(font_obj.measure(str(token_text))) + 12.0)

    def _draw_preview_legend_badge(self, canvas, x: float, y: float, text: str, *, fill: str, outline: str, text_fill: str):
        font_obj = self._get_preview_legend_font(10, "bold")
        text_id = canvas.create_text(
            x + 12,
            y + 9,
            text=str(text),
            fill=text_fill,
            anchor="nw",
            font=font_obj,
            tags=("preview_legend",)
        )
        bbox = canvas.bbox(text_id) or (x, y, x + 40, y + 18)
        rect_id = canvas.create_rectangle(
            bbox[0] - 8,
            bbox[1] - 5,
            bbox[2] + 8,
            bbox[3] + 5,
            fill=fill,
            outline=outline,
            width=1,
            tags=("preview_legend",)
        )
        canvas.tag_lower(rect_id, text_id)
        final_bbox = canvas.bbox(rect_id) or bbox
        return float(final_bbox[2] - final_bbox[0]), float(final_bbox[3] - final_bbox[1])

    def _draw_preview_legend_keycap(self, canvas, x: float, y: float, text: str, *, fill: str, outline: str, text_fill: str):
        font_obj = self._get_preview_legend_font(8, "bold")
        width = self._measure_preview_legend_token("key", text, font_obj)
        height = 21.0
        canvas.create_rectangle(
            x,
            y,
            x + width,
            y + height,
            fill=fill,
            outline=outline,
            width=1,
            tags=("preview_legend",)
        )
        canvas.create_line(
            x + 1,
            y + 1,
            x + width - 1,
            y + 1,
            fill="#ffffff",
            width=1,
            tags=("preview_legend",)
        )
        canvas.create_text(
            x + (width / 2.0),
            y + (height / 2.0) + 0.5,
            text=str(text),
            fill=text_fill,
            anchor="center",
            font=font_obj,
            tags=("preview_legend",)
        )
        return float(width), float(height)

    def _draw_preview_legend_mousecap(self, canvas, x: float, y: float, text: str, *, fill: str, outline: str, text_fill: str):
        font_obj = self._get_preview_legend_font(7, "bold")
        width = self._measure_preview_legend_token("mouse", text, font_obj)
        height = 24.0
        rect_id = canvas.create_rectangle(
            x,
            y,
            x + width,
            y + height,
            fill=fill,
            outline=outline,
            width=1,
            tags=("preview_legend",)
        )
        body_left = x + 7
        body_top = y + 3
        body_right = body_left + 16
        body_bottom = y + 21
        center_x = (body_left + body_right) / 2.0
        highlight_left = str(text).upper() == "LPM"
        highlight_right = str(text).upper() == "PPM"
        canvas.create_oval(
            body_left,
            body_top,
            body_right,
            body_bottom,
            fill="#f7f9fb",
            outline=outline,
            width=1,
            tags=("preview_legend",)
        )
        canvas.create_rectangle(
            body_left + 1,
            body_top + 1,
            center_x - 1,
            body_top + 8,
            fill=(outline if highlight_left else "#f7f9fb"),
            outline="",
            tags=("preview_legend",)
        )
        canvas.create_rectangle(
            center_x + 1,
            body_top + 1,
            body_right - 1,
            body_top + 8,
            fill=(outline if highlight_right else "#f7f9fb"),
            outline="",
            tags=("preview_legend",)
        )
        canvas.create_line(
            center_x,
            body_top + 1,
            center_x,
            body_top + 9,
            fill=outline,
            width=1,
            tags=("preview_legend",)
        )
        canvas.create_text(
            body_right + 8,
            y + (height / 2.0) + 0.5,
            text=str(text),
            fill=text_fill,
            anchor="w",
            font=font_obj,
            tags=("preview_legend",)
        )
        canvas.tag_lower(rect_id)
        return float(width), float(height)

    def _draw_preview_legend_compass_toggle(
        self,
        canvas,
        x: float,
        y: float,
        *,
        expanded: bool,
        theme: dict,
    ) -> tuple[float, float]:
        tags = ("preview_legend", "preview_legend_toggle")
        compact = not bool(expanded)
        size = 24.0 if compact else 38.0
        text_fill = str(theme.get("token_text", "#f3f3f3"))
        compass_photo = self._get_preview_legend_compass_photo(theme, size=int(size))
        if compass_photo is not None:
            canvas.create_image(
                x,
                y,
                image=compass_photo,
                anchor="nw",
                tags=tags,
            )
        else:
            canvas.create_oval(x, y, x + size, y + size, fill=theme.get("token_fill", "#3c3c3c"), outline=theme.get("badge_plate_outline", "#2fbf71"), width=1, tags=tags)
            canvas.create_text(x + (size / 2.0), y + (size / 2.0), text="◎", fill=text_fill, font=self._get_preview_legend_font(12, "bold"), tags=tags)
        if compact:
            return size, size
        state_text = "Zwiń skróty" if expanded else "Rozwiń skróty"
        title_x = x + size + 10.0
        canvas.create_text(
            title_x,
            y + 5.0,
            text="Skróty podglądu",
            anchor="nw",
            fill=theme.get("section_title", text_fill),
            font=self._get_preview_legend_font(8, "bold"),
            tags=tags,
        )
        canvas.create_text(
            title_x,
            y + 19.0,
            text=state_text,
            anchor="nw",
            fill=theme.get("section_muted", "#d8e2ee"),
            font=self._get_preview_legend_font(7, "normal"),
            tags=tags,
        )
        return 152.0, size

    def _draw_preview_legend_grab_handle(self, canvas, x: float, y: float, *, theme: dict) -> tuple[float, float]:
        handle_w = 18.0
        handle_h = 20.0
        fill = str(theme.get("entry_fill", "#3a3f46"))
        outline = str(theme.get("panel_outline", "#4b5563"))
        dot_fill = str(theme.get("section_muted", "#d7e1ec"))
        canvas.create_rectangle(
            x,
            y,
            x + handle_w,
            y + handle_h,
            fill=fill,
            outline=outline,
            width=1,
            tags=("preview_legend", "preview_legend_grab"),
        )
        center_x = x + (handle_w / 2.0)
        start_y = y + 5.0
        gap_y = 4.0
        gap_x = 4.0
        dot_r = 1.15
        for row_idx in range(3):
            for col_idx in (-1, 1):
                cx = center_x + (col_idx * gap_x / 2.0)
                cy = start_y + (row_idx * gap_y)
                canvas.create_oval(
                    cx - dot_r,
                    cy - dot_r,
                    cx + dot_r,
                    cy + dot_r,
                    fill=dot_fill,
                    outline=dot_fill,
                    tags=("preview_legend", "preview_legend_grab"),
                )
        self._preview_controls_legend_grab_bbox = (float(x), float(y), float(x + handle_w), float(y + handle_h))
        return handle_w, handle_h

    def _toggle_preview_controls_legend(self, event=None):
        return toggle_preview_controls_legend(self, event)

    def _is_preview_controls_legend_grab_hit(self, local_x: float, local_y: float) -> bool:
        bbox = getattr(self, "_preview_controls_legend_grab_bbox", None)
        if not (isinstance(bbox, tuple) and len(bbox) == 4):
            return False
        try:
            x1, y1, x2, y2 = [float(v) for v in bbox]
        except Exception:
            return False
        return x1 <= float(local_x) <= x2 and y1 <= float(local_y) <= y2

    def _clamp_preview_controls_legend_offsets(self, offset_x: float, offset_y: float, *, width: float | None = None, height: float | None = None) -> tuple[float, float]:
        return clamp_preview_controls_legend_offsets(self, offset_x, offset_y, width=width, height=height)

