        try:
            self.preview_box_mode_var.set(PREVIEW_BOX_MODE_LABELS["AUTO"])
        except Exception:
            pass
        self._on_preview_box_mode_change()

        active_pid = str(getattr(self, "_preview_active_pid", "") or "").strip()
