    def _is_manual_character_record(self, rec, data=None) -> bool:
        try:
            source_kind = str(self._get_character_source_kind(rec, data=data) or "").strip().lower()
        except Exception:
            source_kind = ""
        if source_kind in {"local_manual", "cvat_manual"}:
            return True

        try:
            source_tag = str(self._get_character_source_tag(rec, data=data) or "").strip().lower()
        except Exception:
            source_tag = ""
        if source_tag == "manual":
            return True

        try:
            method_name = str(rec.get("method", "") if isinstance(rec, dict) else getattr(rec, "method", "")).strip().lower()
        except Exception:
            method_name = ""
        return method_name in {"manual", "cvat_manual"}

    def _character_record_overlap_score(self, left, right) -> float:
        left_bbox = self._char_record_bbox(left)
        right_bbox = self._char_record_bbox(right)
        if not left_bbox or not right_bbox:
            return 0.0

        lx1, ly1, lx2, ly2 = left_bbox
        rx1, ry1, rx2, ry2 = right_bbox
        inter_x1 = max(float(lx1), float(rx1))
        inter_y1 = max(float(ly1), float(ry1))
        inter_x2 = min(float(lx2), float(rx2))
        inter_y2 = min(float(ly2), float(ry2))
        inter_w = max(0.0, inter_x2 - inter_x1)
        inter_h = max(0.0, inter_y2 - inter_y1)
        inter_area = inter_w * inter_h
        if inter_area <= 0.0:
            return 0.0

        left_area = max(1.0, (float(lx2) - float(lx1)) * (float(ly2) - float(ly1)))
        right_area = max(1.0, (float(rx2) - float(rx1)) * (float(ry2) - float(ry1)))
        union_area = max(1.0, left_area + right_area - inter_area)
        return float(inter_area / union_area)

    def _character_record_collides_with_manual(self, rec, manual_records) -> bool:
        bbox = self._char_record_bbox(rec)
        if not bbox:
            return False

        cx = (float(bbox[0]) + float(bbox[2])) / 2.0
        cy = (float(bbox[1]) + float(bbox[3])) / 2.0
        width = max(1.0, float(bbox[2]) - float(bbox[0]))
        height = max(1.0, float(bbox[3]) - float(bbox[1]))

        for manual_rec in list(manual_records or []):
            manual_bbox = self._char_record_bbox(manual_rec)
            if not manual_bbox:
                continue

            iou = self._character_record_overlap_score(rec, manual_rec)
            if iou >= 0.15:
                return True

            mx = (float(manual_bbox[0]) + float(manual_bbox[2])) / 2.0
            my = (float(manual_bbox[1]) + float(manual_bbox[3])) / 2.0
            mw = max(1.0, float(manual_bbox[2]) - float(manual_bbox[0]))
            mh = max(1.0, float(manual_bbox[3]) - float(manual_bbox[1]))

            center_dx = abs(cx - mx)
            center_dy = abs(cy - my)
            if center_dx <= max(width, mw) * 0.45 and center_dy <= max(height, mh) * 0.45:
                return True

        return False

    def _clone_base_record_with_candidate_bbox(self, base_rec, candidate_rec):
        candidate_bbox = self._char_record_bbox(candidate_rec)
        if not candidate_bbox:
            return copy.deepcopy(base_rec) if isinstance(base_rec, dict) else self._clone_character_detection(base_rec)

        candidate_confidence = self._char_record_confidence(candidate_rec)
        if isinstance(base_rec, dict):
            updated = copy.deepcopy(base_rec)
            updated["bbox"] = [float(v) for v in candidate_bbox[:4]]
            try:
                existing_confidence = float(updated.get("confidence", 0.0) or 0.0)
            except Exception:
                existing_confidence = 0.0
            updated["confidence"] = float(max(existing_confidence, candidate_confidence))
            return updated

        symbol, _ = self._char_record_to_symbol_and_x(base_rec)
        return CharacterDetection(
            character=str(symbol or ""),
            bbox=tuple(float(v) for v in candidate_bbox[:4]),
            confidence=float(max(self._char_record_confidence(base_rec), candidate_confidence)),
            method=str(getattr(base_rec, "method", "ocr") or "ocr"),
        )

    def _is_existing_plate_perfect(self, existing_chars, data=None) -> bool:
        ordered_existing = self._sort_character_records_by_x(list(existing_chars or []))
        if not ordered_existing:
            return False
        return str(self._derive_preview_status_from_data(data, ordered_existing) or "").strip().lower() == "perfect"

    def _preserve_existing_perfect_plate_during_detection(self, existing_chars, yolo_detections, data=None):
        ordered_existing = self._sort_character_records_by_x(list(existing_chars or []))
        if not ordered_existing:
            return [], None

        rebuilt, backend_details = self._apply_yolo_box_backend(
            ordered_existing,
            yolo_detections,
            preserve_base_record_metadata=True,
        )
        final_chars = rebuilt or ordered_existing

        fusion_strategy = str((data or {}).get("fusion_strategy", "") or "").strip() if isinstance(data, dict) else ""
        fusion_details = (data or {}).get("fusion_details", {}) if isinstance(data, dict) else {}
        serialized = self._serialize_character_records(
            final_chars,
            fusion_strategy=fusion_strategy,
            fusion_details=fusion_details if isinstance(fusion_details, dict) else None,
        )
        return serialized, backend_details

    def _merge_detected_characters_preserving_manual(self, existing_chars, detected_chars, data=None) -> tuple[list[dict], dict]:
        existing_ordered = self._sort_character_records_by_x(list(existing_chars or []))
        detected_ordered = self._sort_character_records_by_x(list(detected_chars or []))

        manual_records = [
            copy.deepcopy(rec)
            for rec in existing_ordered
            if isinstance(rec, dict) and self._is_manual_character_record(rec, data=data)
        ]
        if not manual_records:
            return detected_ordered, {
                "manual_preserved_count": 0,
                "auto_appended_count": int(len(detected_ordered)),
                "auto_skipped_due_manual": 0,
            }

        merged_records = list(manual_records)
        skipped_auto = 0
        appended_auto = 0

        for rec in detected_ordered:
            if not isinstance(rec, dict):
                continue
            if self._character_record_collides_with_manual(rec, manual_records):
                skipped_auto += 1
                continue
            merged_records.append(rec)
            appended_auto += 1

        return self._sort_character_records_by_x(merged_records), {
            "manual_preserved_count": int(len(manual_records)),
            "auto_appended_count": int(appended_auto),
            "auto_skipped_due_manual": int(skipped_auto),
        }

    def _get_perfect_strategy_bucket(self, data: dict) -> str:
        if not isinstance(data, dict):
            return "other_perfect"

        raw_strategy = str(data.get("fusion_strategy", "") or "").strip().lower()
        if raw_strategy in ("ocr_exact", "ocr_only", "ocr_fallback"):
            return "ocr_exact"
        if raw_strategy in ("yolo_exact", "yolo_only", "yolo_fallback"):
            return "yolo_exact"
        if raw_strategy == "ocr_yolo_rescue":
            return "ocr_yolo_rescue"
        if raw_strategy in (
            "yolo_box_ocr",
            "yolo_box_ocr_exact",
            "yolo_box_ocr_fallback",
            "yolo_box_ocr_no_gt",
            "both_combined",
            "both_combined_no_gt",
        ):
            return "yolo_box_ocr"

        return "other_perfect"

    def _empty_perfect_strategy_counts(self):
        return {key: 0 for key, _ in PERFECT_STRATEGY_BUCKETS}

    def _format_perfect_strategy_counts(self, counts: dict) -> str:
        safe_counts = counts if isinstance(counts, dict) else {}
        parts = [
            f"{label}: {int(safe_counts.get(key, 0))}"
            for key, label in PERFECT_STRATEGY_BUCKETS
        ]
        return "Tablice perfect wg strategii: " + " | ".join(parts)

    def _get_selected_gold_export_strategy_buckets(self):
        selected = set()
        if bool(getattr(self, "gold_include_ocr_exact_var", None).get() if hasattr(self, "gold_include_ocr_exact_var") else True):
            selected.add("ocr_exact")
        if bool(getattr(self, "gold_include_yolo_exact_var", None).get() if hasattr(self, "gold_include_yolo_exact_var") else True):
            selected.add("yolo_exact")
        if bool(getattr(self, "gold_include_ocr_yolo_rescue_var", None).get() if hasattr(self, "gold_include_ocr_yolo_rescue_var") else True):
            selected.add("ocr_yolo_rescue")
        if bool(getattr(self, "gold_include_yolo_box_ocr_var", None).get() if hasattr(self, "gold_include_yolo_box_ocr_var") else True):
            selected.add("yolo_box_ocr")
        if bool(getattr(self, "gold_include_other_perfect_var", None).get() if hasattr(self, "gold_include_other_perfect_var") else True):
            selected.add("other_perfect")
        return selected

    def _format_selected_gold_export_strategy_labels(self) -> str:
        selected = self._get_selected_gold_export_strategy_buckets()
        labels = [label for key, label in PERFECT_STRATEGY_BUCKETS if key in selected]
        return ", ".join(labels) if labels else "brak"

    def _get_selected_gold_export_source_buckets(self):
        selected = {"cvat_manual"}
        if bool(getattr(self, "gold_include_source_auto_var", None).get() if hasattr(self, "gold_include_source_auto_var") else True):
            selected.add("auto_preview")
        if bool(getattr(self, "gold_include_source_local_manual_var", None).get() if hasattr(self, "gold_include_source_local_manual_var") else True):
            selected.add("local_manual")
        return selected

    def _format_selected_gold_export_source_labels(self) -> str:
        selected = self._get_selected_gold_export_source_buckets()
        labels = [label for key, label in GOLD_SOURCE_BUCKETS if key in selected]
        return ", ".join(labels) if labels else "brak"

    def _count_exportable_characters_in_data(self, data: dict) -> int:
        if not isinstance(data, dict):
            return 0

        count = 0
        for rec in list(data.get("characters", []) or []):
            if self._is_exportable_character_record(rec):
                count += 1
        return count

    def _count_exportable_perfect_plates_in_metadata(self, metadata_map) -> int:
        count = 0
        for _pid, data in (metadata_map or {}).items():
            if not isinstance(data, dict):
                continue
            if str(data.get("status", "unknown") or "unknown").strip().lower() != "perfect":
                continue
            if self._count_exportable_characters_in_data(data) > 0:
                count += 1
        return int(count)

    def _matches_selected_gold_export_sources(self, data: dict, selected_sources=None) -> bool:
        selected = set(selected_sources or [])
        if not selected:
            return False
        bucket = self._get_plate_source_bucket(data)
        return bucket in selected

    def _build_contextual_gold_export_counts(self, *, selected_strategies=None, selected_sources=None):
        strategy_filter = set(selected_strategies or [])
        source_filter = set(selected_sources or [])
        use_strategy_filter = bool(strategy_filter)
        use_source_filter = bool(source_filter)

        strategy_counts = self._empty_perfect_strategy_counts()
        strategy_char_counts = self._empty_perfect_strategy_counts()
        source_counts = self._empty_gold_source_counts()
        source_char_counts = self._empty_gold_source_counts()

        for _pid, data in (self.preview_metadata or {}).items():
            if not isinstance(data, dict):
                continue
            if str(data.get("status", "unknown") or "unknown").strip().lower() != "perfect":
                continue

            strategy_bucket = self._get_perfect_strategy_bucket(data)
            source_bucket = self._get_plate_source_bucket(data)
            char_count = self._count_exportable_characters_in_data(data)

            if (not use_source_filter) or source_bucket in source_filter:
                if strategy_bucket in strategy_counts:
                    strategy_counts[strategy_bucket] += 1
                    strategy_char_counts[strategy_bucket] += char_count

            if (not use_strategy_filter) or strategy_bucket in strategy_filter:
                if source_bucket in source_counts:
                    source_counts[source_bucket] += 1
                    source_char_counts[source_bucket] += char_count

        return {
            "strategy_counts": strategy_counts,
            "strategy_char_counts": strategy_char_counts,
            "source_counts": source_counts,
            "source_char_counts": source_char_counts,
        }

    def _count_statuses_in_metadata_mapping(self, metadata_map):
        perfect = 0
        needs_fix = 0
        unknown = 0
        char_boxes = 0
        strategy_counts = self._empty_perfect_strategy_counts()
        strategy_char_counts = self._empty_perfect_strategy_counts()
        source_counts = self._empty_gold_source_counts()
        source_char_counts = self._empty_gold_source_counts()

        for _, data in (metadata_map or {}).items():
            if not isinstance(data, dict):
                unknown += 1
                continue

            try:
                char_boxes += len(list(data.get("characters", []) or []))
            except Exception:
                pass

            status = str(data.get("status", "unknown")).strip().lower()
            if status == "perfect":
                perfect += 1
                bucket = self._get_perfect_strategy_bucket(data)
                source_bucket = self._get_plate_source_bucket(data)
                strategy_counts[bucket] += 1
                strategy_char_counts[bucket] += self._count_exportable_characters_in_data(data)
                if source_bucket in source_counts:
                    source_counts[source_bucket] += 1
                    source_char_counts[source_bucket] += self._count_exportable_characters_in_data(data)
            elif status == "needs_fix":
                needs_fix += 1
            else:
                unknown += 1

        return {
            "perfect": perfect,
            "needs_fix": needs_fix,
            "unknown": unknown,
            "total": perfect + needs_fix + unknown,
            "char_boxes": int(char_boxes),
            "strategy_counts": strategy_counts,
            "strategy_char_counts": strategy_char_counts,
            "source_counts": source_counts,
            "source_char_counts": source_char_counts,
        }

    def _build_merged_gold_export_counts(self, *, selected_strategies=None, selected_sources=None):
        strategy_filter = set(selected_strategies or [])
        source_filter = set(selected_sources or [])
        use_strategy_filter = bool(strategy_filter)
        use_source_filter = bool(source_filter)

        strategy_counts = self._empty_perfect_strategy_counts()
        strategy_char_counts = self._empty_perfect_strategy_counts()
        source_counts = self._empty_gold_source_counts()
        source_char_counts = self._empty_gold_source_counts()
        selected_plate_count = 0
        selected_char_count = 0

        meta_candidates = self._get_gold_export_meta_candidates()

        seen = set()
        for meta in meta_candidates:
            try:
                with open(meta, "r", encoding="utf-8") as f:
                    metadata = json.load(f)
            except Exception:
                continue
            if not isinstance(metadata, dict):
                continue

            for pid, data in metadata.items():
                if not isinstance(data, dict):
                    continue
                if str(data.get("status", "unknown") or "unknown").strip().lower() != "perfect":
                    continue

                try:
                    self._ensure_plate_source_metadata(data, plate_id=str(pid or ""), meta_path=meta)
                except Exception:
                    pass

                unique_key = self._build_gold_export_plate_unique_key(data)
                if unique_key in seen:
                    continue
                seen.add(unique_key)

                strategy_bucket = self._get_perfect_strategy_bucket(data)
                source_bucket = self._get_plate_source_bucket(data, meta_path=meta)
                char_count = self._count_exportable_characters_in_data(data)
                strategy_match = (not use_strategy_filter) or (strategy_bucket in strategy_filter)
                source_match = (not use_source_filter) or (source_bucket in source_filter)

                if source_match and strategy_bucket in strategy_counts:
                    strategy_counts[strategy_bucket] += 1
                    strategy_char_counts[strategy_bucket] += char_count

                if strategy_match and source_bucket in source_counts:
                    source_counts[source_bucket] += 1
                    source_char_counts[source_bucket] += char_count

                if strategy_match and source_match:
                    selected_plate_count += 1
                    selected_char_count += char_count

        return {
            "strategy_counts": strategy_counts,
            "strategy_char_counts": strategy_char_counts,
            "source_counts": source_counts,
            "source_char_counts": source_char_counts,
            "selected_plate_count": int(selected_plate_count),
            "selected_char_count": int(selected_char_count),
        }

    def _build_campaign_aware_gold_export_counts(self, *, selected_strategies=None, selected_sources=None):
        try:
            in_campaign = bool(getattr(self, "_step3_linear_mode", False) and CAMPAIGN.get_active_project_name())
        except Exception:
            in_campaign = False

        if in_campaign:
            contextual = self._build_contextual_gold_export_counts(
                selected_strategies=selected_strategies,
                selected_sources=selected_sources,
            )
            strategy_counts = dict(contextual.get("strategy_counts", {}) or {})
            strategy_char_counts = dict(contextual.get("strategy_char_counts", {}) or {})
            source_counts = dict(contextual.get("source_counts", {}) or {})
            source_char_counts = dict(contextual.get("source_char_counts", {}) or {})
            selected_plate_count = int(sum(int(v or 0) for v in strategy_counts.values()))
            selected_char_count = int(sum(int(v or 0) for v in strategy_char_counts.values()))
            return {
                "strategy_counts": strategy_counts,
                "strategy_char_counts": strategy_char_counts,
                "source_counts": source_counts,
                "source_char_counts": source_char_counts,
                "selected_plate_count": int(selected_plate_count),
                "selected_char_count": int(selected_char_count),
            }

        return self._build_merged_gold_export_counts(
            selected_strategies=selected_strategies,
            selected_sources=selected_sources,
        )

    def _get_gold_export_meta_candidates(self) -> list[Path]:
        in_campaign = bool(getattr(self, "_step3_linear_mode", False) and CAMPAIGN.get_active_project_name())

        if not in_campaign:
            preview_dir_raw = self._get_preferred_step3_preview_dir(require_plates=True, allow_fallback=True)
            if not preview_dir_raw:
                return []
            try:
                preview_dir = Path(preview_dir_raw)
            except Exception:
                return []
            meta_path = preview_dir / "metadata.json"
            images_dir = preview_dir / "images"
            if meta_path.exists() and images_dir.exists():
                try:
                    self.preview_dir_var.set(str(preview_dir))
                    self._save_local_setting("char_preview_dir", str(preview_dir))
                except Exception:
                    pass
                return [meta_path]
            return []

        base_chars_dir = self._get_step3_chars_root_dir()
        meta_candidates: list[Path] = []
        try:
            for meta in base_chars_dir.rglob("metadata.json"):
                run_dir = meta.parent
                if (run_dir / "images").exists():
                    meta_candidates.append(meta)
        except Exception:
            meta_candidates = []

        try:
            meta_candidates.sort(key=lambda p: p.stat().st_mtime, reverse=True)
        except Exception:
            pass
        return meta_candidates

    def _char_record_bbox(self, rec):
        bbox = None

        if isinstance(rec, dict):
            bbox = rec.get("bbox")
        else:
            try:
                bbox = getattr(rec, "bbox", None)
            except Exception:
                bbox = None

        if not isinstance(bbox, (list, tuple)) or len(bbox) < 4:
            return None

        try:
            return tuple(float(v) for v in bbox[:4])
        except Exception:
            return None

    def _char_record_width(self, rec) -> float:
        bbox = self._char_record_bbox(rec)
        if not bbox:
            return 0.0
        return max(0.0, float(bbox[2]) - float(bbox[0]))

    def _char_record_height(self, rec) -> float:
        bbox = self._char_record_bbox(rec)
        if not bbox:
            return 0.0
        return max(0.0, float(bbox[3]) - float(bbox[1]))

    def _char_record_center_y(self, rec) -> float:
        bbox = self._char_record_bbox(rec)
        if not bbox:
            return 0.0
        return (float(bbox[1]) + float(bbox[3])) / 2.0

    def _build_char_record_geometry_stats(self, records):
        prepared = list(records or [])
        widths = [self._char_record_width(rec) for rec in prepared if self._char_record_width(rec) > 0.0]
        heights = [self._char_record_height(rec) for rec in prepared if self._char_record_height(rec) > 0.0]
        centers_y = [self._char_record_center_y(rec) for rec in prepared if self._char_record_bbox(rec)]

        median_width = float(sorted(widths)[len(widths) // 2]) if widths else 0.0
        median_height = float(sorted(heights)[len(heights) // 2]) if heights else 0.0
        median_center_y = float(sorted(centers_y)[len(centers_y) // 2]) if centers_y else 0.0
        return {
            "median_width": median_width,
            "median_height": median_height,
            "median_center_y": median_center_y,
            "count": int(len(prepared)),
        }

    def _char_record_confidence(self, rec) -> float:
        if isinstance(rec, dict):
            try:
                return float(rec.get("confidence", 0.0))
            except Exception:
                return 0.0

        try:
            return float(getattr(rec, "confidence", 0.0))
        except Exception:
            return 0.0

    def _clone_character_detection(self, rec, character=None, method=None):
        symbol, _ = self._char_record_to_symbol_and_x(rec)
        bbox = self._char_record_bbox(rec) or (0.0, 0.0, 1.0, 1.0)
        confidence = self._char_record_confidence(rec)

        return CharacterDetection(
            character=str(character if character is not None else symbol or ""),
            bbox=tuple(float(v) for v in bbox[:4]),
            confidence=float(confidence),
            method=str(method if method is not None else getattr(rec, "method", "ocr") if not isinstance(rec, dict) else rec.get("method", "ocr")),
        )

    def _levenshtein_distance(self, left: str, right: str) -> int:
        left = str(left or "")
        right = str(right or "")

        if left == right:
            return 0
        if not left:
            return len(right)
        if not right:
            return len(left)

        previous = list(range(len(right) + 1))
        for i, left_char in enumerate(left, start=1):
            current = [i]
            for j, right_char in enumerate(right, start=1):
                cost = 0 if left_char == right_char else 1
                current.append(
                    min(
                        previous[j] + 1,
                        current[j - 1] + 1,
                        previous[j - 1] + cost,
                    )
                )
            previous = current

        return previous[-1]

    def _best_text_distance(self, candidate_text: str, true_texts) -> int:
        normalized = [str(item or "").strip().upper() for item in (true_texts or []) if str(item or "").strip()]
        if not normalized:
            return 10 ** 9

        candidate = str(candidate_text or "").strip().upper()
        return min(self._levenshtein_distance(candidate, truth) for truth in normalized)

    def _fit_detection_count_to_truths(self, detections, true_texts):
        ordered = self._sort_character_records_by_x(list(detections or []))
        normalized_truths = [
            str(item or "").strip().upper()
            for item in (true_texts or [])
            if str(item or "").strip()
        ]
        if not ordered or not normalized_truths:
            return ordered, None

        detection_count = len(ordered)
        if detection_count <= 0:
            return ordered, None

        if any(len(truth) == detection_count for truth in normalized_truths):
            return ordered, None

        candidates = [truth for truth in normalized_truths if 0 < len(truth) <= detection_count]
        if not candidates:
            return ordered, None

        best_window = None
        best_details = None
        best_score = None

        for truth in candidates:
            expected_len = len(truth)
            for start_idx in range(0, detection_count - expected_len + 1):
                window = ordered[start_idx:start_idx + expected_len]
                candidate_text = self._characters_to_text(window)
                distance = self._levenshtein_distance(candidate_text, truth)
                avg_conf = (
                    sum(self._char_record_confidence(rec) for rec in window) / float(len(window))
                    if window else 0.0
                )
                dropped_left = int(start_idx)
                dropped_right = int(detection_count - (start_idx + expected_len))
                score = (distance, -avg_conf, dropped_left + dropped_right, dropped_left)
                if best_score is None or score < best_score:
                    best_score = score
                    best_window = window
                    best_details = {
                        "expected_text": truth,
                        "window_text": candidate_text,
                        "original_box_count": int(detection_count),
                        "trimmed_box_count": int(expected_len),
                        "trimmed_extra_boxes": int(detection_count - expected_len),
                        "trimmed_left_boxes": dropped_left,
                        "trimmed_right_boxes": dropped_right,
                        "distance": int(distance),
                    }

        if best_window is None or best_details is None:
            return ordered, None
        if int(best_details.get("trimmed_extra_boxes", 0) or 0) <= 0:
            return ordered, None
        return list(best_window), best_details

    def _apply_final_truth_count_guard(self, characters, true_texts, fusion_details: dict | None = None):
        ordered_chars = self._sort_character_records_by_x(list(characters or []))
        fitted_chars, trim_details = self._fit_detection_count_to_truths(ordered_chars, true_texts)
        if not isinstance(trim_details, dict) or not trim_details:
            return ordered_chars, fusion_details

        merged_details = dict(fusion_details or {})
        merged_details.update(trim_details)
        merged_details["gt_count_guard_applied"] = True
        merged_details["gt_count_guard_stage"] = "final_characters"
        return self._sort_character_records_by_x(list(fitted_chars or [])), merged_details

    def _pick_best_true_text(self, candidate_text: str, true_texts, same_length_only: bool = False) -> str:
        normalized = [str(item or "").strip().upper() for item in (true_texts or []) if str(item or "").strip()]
        if same_length_only:
            normalized = [item for item in normalized if len(item) == len(str(candidate_text or ""))]

        if not normalized:
            return ""

        candidate = str(candidate_text or "").strip().upper()
        return min(
            normalized,
            key=lambda item: (
                self._levenshtein_distance(candidate, item),
                abs(len(candidate) - len(item)),
                item,
            )
        )

    def _get_text_mismatch_positions(self, candidate_text: str, expected_text: str):
        candidate = str(candidate_text or "").strip().upper()
        expected = str(expected_text or "").strip().upper()

        if not candidate or not expected or len(candidate) != len(expected):
            return []

        return [idx for idx, (left, right) in enumerate(zip(candidate, expected)) if left != right]

    def _find_best_yolo_rescue_index(self, slot_index: int, expected_char: str, ocr_detections, yolo_detections, used_indices, min_index: int | None = None):
        if slot_index < 0 or slot_index >= len(ocr_detections):
            return None

        expected_char = str(expected_char or "").strip().upper()
        if not expected_char:
            return None

        _, slot_center_x = self._char_record_to_symbol_and_x(ocr_detections[slot_index], fallback_index=slot_index)
        ocr_width = max(1.0, self._char_record_width(ocr_detections[slot_index]))
        all_ocr_widths = [self._char_record_width(det) for det in ocr_detections if self._char_record_width(det) > 0.0]
        if all_ocr_widths:
            sorted_widths = sorted(all_ocr_widths)
            median_width = float(sorted_widths[len(sorted_widths) // 2])
        else:
            median_width = ocr_width

        allowed_gap = max(6.0, ocr_width * 0.85, median_width * 0.75)

        if slot_index < len(yolo_detections) and slot_index not in used_indices:
            aligned_det = yolo_detections[slot_index]
            aligned_char, aligned_center_x = self._char_record_to_symbol_and_x(aligned_det, fallback_index=slot_index)
            if (min_index is None or slot_index >= int(min_index)) and str(aligned_char or "").strip().upper() == expected_char:
                if abs(aligned_center_x - slot_center_x) <= allowed_gap * 1.35:
                    return slot_index

        best_index = None
        best_score = None

        for idx, det in enumerate(yolo_detections):
            if idx in used_indices:
                continue
            if min_index is not None and idx < int(min_index):
                continue

            det_char, det_center_x = self._char_record_to_symbol_and_x(det, fallback_index=idx)
            if str(det_char or "").strip().upper() != expected_char:
                continue

            center_gap = abs(float(det_center_x) - float(slot_center_x))
            if center_gap > allowed_gap * 1.35:
                continue

            score = (
                (center_gap / allowed_gap)
                + (0.12 * abs(idx - slot_index))
                - min(0.20, self._char_record_confidence(det) * 0.10)
            )

            if best_score is None or score < best_score:
                best_index = idx
                best_score = score

        return best_index

    def _apply_yolo_box_backend(self, base_detections, yolo_detections, *, preserve_base_record_metadata: bool = False):
        ordered_base = self._sort_character_records_by_x(list(base_detections or []))
        ordered_yolo = self._sort_character_records_by_x(list(yolo_detections or []))

        if not ordered_base or not ordered_yolo:
            return ordered_base, None

        expected_text = self._characters_to_text(ordered_base)
        if not expected_text:
            return ordered_base, None

        # W trybie hybrydowym OCR ma pilnować tekstu i kolejności slotów,
        # ale sama geometria powinna być oceniana względem przefiltrowanego YOLO.
        yolo_stats = self._build_char_record_geometry_stats(ordered_yolo)
        yolo_median_width = max(1.0, float(yolo_stats.get("median_width", 0.0) or 0.0))
        yolo_median_height = max(1.0, float(yolo_stats.get("median_height", 0.0) or 0.0))
        yolo_median_center_y = float(yolo_stats.get("median_center_y", 0.0) or 0.0)

        used_yolo_indices = set()
        replaced = [self._clone_character_detection(det) for det in ordered_base]
        replaced_positions = []
        last_yolo_index = -1

        for slot_index, det in enumerate(ordered_base):
            expected_char = expected_text[slot_index] if slot_index < len(expected_text) else ""
            rescue_index = self._find_best_yolo_rescue_index(
                slot_index,
                expected_char,
                ordered_base,
                ordered_yolo,
                used_yolo_indices,
                min_index=last_yolo_index + 1,
            )
            if rescue_index is None:
                continue

            candidate = ordered_yolo[rescue_index]
            candidate_bbox = self._char_record_bbox(candidate)
            if not candidate_bbox:
                continue

            candidate_width = max(1.0, self._char_record_width(candidate))
            candidate_height = max(1.0, self._char_record_height(candidate))
            candidate_center_y = (float(candidate_bbox[1]) + float(candidate_bbox[3])) / 2.0

            width_ratio = candidate_width / yolo_median_width
            height_ratio = candidate_height / yolo_median_height
            median_center_y_gap = abs(candidate_center_y - yolo_median_center_y) if yolo_median_center_y > 0.0 else 0.0
            allowed_center_y_gap = max(8.0, yolo_median_height * 0.42)

            if width_ratio < 0.28 or width_ratio > 2.45:
                continue
            if height_ratio < 0.55 or height_ratio > 1.95:
                continue
            if yolo_median_center_y > 0.0 and median_center_y_gap > allowed_center_y_gap:
                continue
            if self._char_record_confidence(candidate) < 0.18:
                continue

            if preserve_base_record_metadata:
                replaced[slot_index] = self._clone_base_record_with_candidate_bbox(det, candidate)
            else:
                replaced[slot_index] = self._clone_character_detection(
                    candidate,
                    character=expected_char,
                    method="yolo",
                )
            used_yolo_indices.add(rescue_index)
            replaced_positions.append(slot_index)
            last_yolo_index = rescue_index

        if not replaced_positions:
            return ordered_base, None

        replaced = self._sort_character_records_by_x(replaced)
        if self._characters_to_text(replaced) != expected_text:
            return ordered_base, None

        details = {
            "box_backend": "yolo",
            "box_backend_positions": list(replaced_positions),
            "box_backend_count": int(len(replaced_positions)),
            "box_backend_reference": "yolo_filtered",
            "box_backend_reference_count": int(yolo_stats.get("count", 0) or 0),
        }
        return replaced, details

    def _repair_ocr_with_yolo_boxes(self, ocr_detections, yolo_detections, true_texts, max_mismatch_count: int = 2):
        ordered_ocr = self._sort_character_records_by_x(list(ocr_detections or []))
        ordered_yolo = self._sort_character_records_by_x(list(yolo_detections or []))

        if not ordered_ocr or not ordered_yolo:
            return None, None

        max_mismatch_count = max(1, min(5, int(max_mismatch_count or 2)))

        ocr_text = self._characters_to_text(ordered_ocr)
        expected_text = self._pick_best_true_text(ocr_text, true_texts, same_length_only=True)
        if not expected_text:
            return None, None

        mismatch_positions = self._get_text_mismatch_positions(ocr_text, expected_text)
        if not mismatch_positions or len(mismatch_positions) > max_mismatch_count:
            return None, None

        repaired = [self._clone_character_detection(det) for det in ordered_ocr]
        used_yolo_indices = set()

        for slot_index in mismatch_positions:
            rescue_index = self._find_best_yolo_rescue_index(
                slot_index,
                expected_text[slot_index],
                ordered_ocr,
                ordered_yolo,
                used_yolo_indices,
            )
            if rescue_index is None:
                return None, None

            used_yolo_indices.add(rescue_index)
            repaired[slot_index] = self._clone_character_detection(
                ordered_yolo[rescue_index],
                character=expected_text[slot_index],
                method="yolo",
            )

        repaired = self._sort_character_records_by_x(repaired)
        repaired_text = self._characters_to_text(repaired)
        if repaired_text != expected_text:
            return None, None

        details = {
            "ocr_text": ocr_text,
            "yolo_text": self._characters_to_text(ordered_yolo),
            "expected_text": expected_text,
            "mismatch_positions": list(mismatch_positions),
            "max_mismatch_count": int(max_mismatch_count),
        }
        return repaired, details

    def _resolve_canonical_detections(self, method, combined_detections, ocr_detections, yolo_detections, true_texts, hybrid_rescue_max_chars: int = 2, prefer_yolo_box_positions: bool = False):
        ordered_combined = self._sort_character_records_by_x(list(combined_detections or []))
        ordered_ocr = self._sort_character_records_by_x(list(ocr_detections or []))
        ordered_yolo = self._sort_character_records_by_x(list(yolo_detections or []))
        normalized_truths = [
            str(item or "").strip().upper()
            for item in (true_texts or [])
            if str(item or "").strip()
        ]

        def apply_truth_count_guard(source_records, strategy_name: str, details: dict | None = None):
            fitted_records, trim_details = self._fit_detection_count_to_truths(source_records, normalized_truths)
            if not isinstance(trim_details, dict) or not trim_details:
                return source_records, strategy_name, details
            merged_details = dict(details or {})
            merged_details.update(trim_details)
            return fitted_records, strategy_name, merged_details

        if not ordered_combined and not ordered_ocr and not ordered_yolo:
            if normalized_truths:
                return [], "no_detection", {"distance": self._best_text_distance("", normalized_truths)}
            return [], "no_detection_no_gt", {"distance": 0}

        if method == DetectionMethod.OCR:
            return apply_truth_count_guard(ordered_ocr or ordered_combined, "ocr_only", None)

        if method == DetectionMethod.YOLO:
            return apply_truth_count_guard(ordered_yolo or ordered_combined, "yolo_only", None)

        if method == DetectionMethod.YOLO_OCR:
            combined_text = self._characters_to_text(ordered_combined)
            details = {
                "box_source": "yolo_nms",
                "box_count": int(len(ordered_combined)),
                "ocr_filled_count": int(sum(1 for rec in ordered_combined if self._preview_record_has_symbol(rec))),
            }

            if normalized_truths:
                if combined_text and combined_text in normalized_truths:
                    details.update({"final_text": combined_text})
                    return apply_truth_count_guard(ordered_combined, "yolo_box_ocr", details)
                details.update({"distance": self._best_text_distance(combined_text, normalized_truths)})
                return apply_truth_count_guard(ordered_combined, "yolo_box_ocr_fallback", details)

            return ordered_combined, "yolo_box_ocr_no_gt", details

        if normalized_truths:
            ocr_text = self._characters_to_text(ordered_ocr)
            yolo_text = self._characters_to_text(ordered_yolo)

            if ocr_text and ocr_text in normalized_truths:
                details = {"final_text": ocr_text}
                if prefer_yolo_box_positions:
                    rebuilt, backend_details = self._apply_yolo_box_backend(ordered_ocr, ordered_yolo)
                    if backend_details:
                        details.update(backend_details)
                        return apply_truth_count_guard(rebuilt, "ocr_exact", details)
                return apply_truth_count_guard(ordered_ocr, "ocr_exact", details)

            if yolo_text and yolo_text in normalized_truths:
                return apply_truth_count_guard(ordered_yolo, "yolo_exact", {"final_text": yolo_text})

            if int(hybrid_rescue_max_chars or 0) > 0:
                rescued, rescue_details = self._repair_ocr_with_yolo_boxes(
                    ordered_ocr,
                    ordered_yolo,
                    normalized_truths,
                    max_mismatch_count=hybrid_rescue_max_chars,
                )
                if rescued:
                    if prefer_yolo_box_positions:
                        rebuilt, backend_details = self._apply_yolo_box_backend(rescued, ordered_yolo)
                        if backend_details:
                            if not isinstance(rescue_details, dict):
                                rescue_details = {}
                            rescue_details.update(backend_details)
                            return apply_truth_count_guard(rebuilt, "ocr_yolo_rescue", rescue_details)
                    return apply_truth_count_guard(rescued, "ocr_yolo_rescue", rescue_details)

            best_source = ordered_ocr or ordered_yolo or ordered_combined
            best_strategy = "ocr_fallback" if ordered_ocr else ("yolo_fallback" if ordered_yolo else "both_combined")
            best_distance = self._best_text_distance(self._characters_to_text(best_source), normalized_truths)

            for candidate_source, candidate_strategy in (
                (ordered_yolo, "yolo_fallback"),
                (ordered_combined, "both_combined"),
            ):
                if not candidate_source:
                    continue

                candidate_distance = self._best_text_distance(self._characters_to_text(candidate_source), normalized_truths)
                if candidate_distance < best_distance:
                    best_source = candidate_source
                    best_strategy = candidate_strategy
                    best_distance = candidate_distance

            return apply_truth_count_guard(best_source, best_strategy, {"distance": best_distance})

        return ordered_combined, "both_combined_no_gt", None

    def _get_preview_box_mode_key(self) -> str:
        raw_value = str((getattr(self, "preview_box_mode_var", None).get() if hasattr(self, "preview_box_mode_var") else "AUTO") or "AUTO").strip()
        if not raw_value:
            return "AUTO"

        direct_key = raw_value.upper()
        if direct_key in PREVIEW_BOX_MODE_LABELS:
            return direct_key

        return PREVIEW_BOX_MODE_BY_LABEL.get(raw_value, "AUTO")

    def _normalize_detection_method_key(self, raw_value=None) -> str:
        value = str(raw_value or "").strip()
        if not value:
            return "OCR"

        upper_value = value.upper()
        if upper_value in DETECTION_METHOD_LABELS:
            return upper_value

        return DETECTION_METHOD_KEY_BY_LABEL.get(value, "OCR")

    def _get_detection_method_key(self) -> str:
        raw_value = getattr(self, "detection_method_var", None).get() if hasattr(self, "detection_method_var") else "OCR"
        return self._normalize_detection_method_key(raw_value)

    def _get_hybrid_rescue_max_chars(self) -> int:
        try:
            value = int(self.hybrid_rescue_max_chars_var.get())
        except Exception:
            value = 2
        return max(0, min(5, value))

    def _use_hybrid_yolo_box_backend(self) -> bool:
        try:
            return bool(self.hybrid_yolo_box_backend_var.get())
        except Exception:
            return True

    def _get_hybrid_detection_status_text(self) -> str:
        rescue_chars = self._get_hybrid_rescue_max_chars()
        backend_state = "ON" if self._use_hybrid_yolo_box_backend() else "OFF"
        rescue_text = "OFF" if rescue_chars <= 0 else f"YOLO rescue <= {rescue_chars}"
        return (
            f"odczyt: OCR | dopasowanie pozycji: YOLO | rescue: {rescue_text} | "
            f"końcowe ramki z YOLO: {backend_state}"
        )

    def _get_yolo_box_ocr_status_text(self) -> str:
        return "boxy: YOLO | odczyt cropów: OCR | końcowe ramki z YOLO"

    def _get_detection_pipeline_blocks(self, method_key: str | None = None) -> list[str]:
        resolved_method = self._normalize_detection_method_key(method_key or self._get_detection_method_key())
        if resolved_method == "YOLO":
            return ["yolo_box", "yolo_symbol"]
        if resolved_method == "BOTH":
            blocks = ["ocr_symbol", "yolo_box"]
            if self._get_hybrid_rescue_max_chars() > 0:
                blocks.append("yolo_symbol")
            return blocks
        if resolved_method == "YOLO_OCR":
            return ["yolo_box", "ocr_symbol"]
        return ["ocr_symbol"]

    def _compile_detection_pipeline_blocks(self, blocks=None) -> dict:
        prepared = [
            str(block or "").strip().lower().replace("-", "_")
            for block in (blocks or [])
            if str(block or "").strip()
        ]
        valid_patterns = {
            ("ocr_symbol",): ("OCR", False),
            ("yolo_box", "yolo_symbol"): ("YOLO", False),
            ("ocr_symbol", "yolo_box"): ("BOTH", False),
            ("ocr_symbol", "yolo_box", "yolo_symbol"): ("BOTH", True),
            ("yolo_box", "ocr_symbol"): ("YOLO_OCR", False),
        }
        compiled = valid_patterns.get(tuple(prepared))
        if compiled is None:
            return {
                "valid": False,
                "blocks": prepared,
                "method_key": None,
                "rescue_enabled": False,
                "requires_yolo": any(block.startswith("yolo") for block in prepared),
                "status_text": (
                    "Ten łańcuch nie jest jeszcze wspierany. "
                    "Dozwolone układy: O | YB->YS | O->YB | O->YB->YS | YB->O."
                ),
            }

        method_key, rescue_enabled = compiled
        label = DETECTION_METHOD_CARD_META.get(method_key, {}).get("title", method_key)
        status_text = f"Builder złoży ten pipeline jako tryb: {label}"
        if method_key == "BOTH":
            status_text += " z rescue" if rescue_enabled else " bez rescue"
        return {
            "valid": True,
            "blocks": prepared,
            "method_key": method_key,
            "rescue_enabled": bool(rescue_enabled),
            "requires_yolo": method_key in {"YOLO", "BOTH", "YOLO_OCR"},
            "status_text": status_text,
        }

    def _apply_detection_pipeline_blocks(self, blocks, *, save: bool = True, prompt_for_yolo_model: bool = True) -> bool:
        compiled = self._compile_detection_pipeline_blocks(blocks)
        if not bool(compiled.get("valid")):
            return False

        method_key = str(compiled.get("method_key") or "OCR")
        requires_yolo = bool(compiled.get("requires_yolo"))
        if requires_yolo and not self._has_configured_yolo_detection_model():
            if prompt_for_yolo_model:
                selected_model = str(self._pick_yolo_model() or "").strip()
                if not selected_model or not self._has_configured_yolo_detection_model():
                    messagebox.showinfo(
                        "Brak modelu YOLO",
                        "Ten pipeline wymaga modelu YOLO znaków. Wskaż poprawny plik .pt, aby go zatwierdzić.",
                    )
                    return False
            else:
                return False

        if method_key == "BOTH":
            rescue_enabled = bool(compiled.get("rescue_enabled"))
            current_rescue = self._get_hybrid_rescue_max_chars()
            target_rescue = current_rescue if current_rescue > 0 else 2
            try:
                self.hybrid_rescue_max_chars_var.set(target_rescue if rescue_enabled else 0)
            except Exception:
                pass

        self._set_detection_method_key(method_key, save=save)
        self._refresh_detection_workflow_info_label()
        return True

    def _get_detection_workflow_text(self, method_key: str | None = None) -> str:
        resolved_method = self._normalize_detection_method_key(method_key or self._get_detection_method_key())
        if resolved_method == "YOLO":
            return "Pipeline: YOLO wykrywa znaki i klasy."
        if resolved_method == "BOTH":
            rescue_chars = self._get_hybrid_rescue_max_chars()
            rescue_text = f"rescue max {rescue_chars}" if rescue_chars > 0 else "rescue wyłączone"
            return f"Pipeline: OCR czyta, YOLO dopasowuje; {rescue_text}."
        if resolved_method == "YOLO_OCR":
            return "Pipeline: YOLO boxy, OCR odczyt cropów."
        return "Pipeline: OCR czyta i segmentuje znaki."

    def _refresh_detection_workflow_info_label(self):
        label = getattr(self, "detect_workflow_info_lbl", None)
        if label is None:
            return
        try:
            label.configure(text=self._get_detection_workflow_text())
        except Exception:
            pass
        try:
            self._refresh_detection_active_model_label()
        except Exception:
            pass

    def _get_detection_active_model_status(self) -> tuple[str, str]:
        method_key = self._get_detection_method_key()
        uses_yolo = method_key in ("YOLO", "BOTH", "YOLO_OCR")
        model_path = str(self._get_effective_yolo_model_path() or "").strip()
        path_locked = bool(getattr(self, "_step3_linear_mode", False))

        if model_path and Path(model_path).exists():
            model_name = Path(model_path).name
            version, size = self._infer_yolo_arch_from_model_path(model_path)
            if version and size:
                model_name = f"{model_name} (YOLOv{version}{size})"

            source_suffix = " z projektu" if path_locked else ""
            if uses_yolo:
                return f"Aktywny model YOLO: {model_name}{source_suffix}", "neutral"
            return f"Model YOLO gotowy: {model_name}{source_suffix} | w tym trybie nie jest używany", "muted"

        if uses_yolo:
            return "Aktywny model YOLO: brak wybranego modelu", "warning"
        if path_locked:
            return "Aktywny model YOLO: sterowany przez projekt i nieużywany w trybie OCR", "muted"
        return "Aktywny model YOLO: nieużywany w trybie OCR", "muted"

    def _refresh_detection_active_model_label(self):
        label = getattr(self, "detect_active_model_lbl", None)
        if label is None:
            return
        text, tone = self._get_detection_active_model_status()
        self._set_themed_label_state(label, text=text, tone=tone)

    def _get_preview_box_mode_label(self, key=None) -> str:
        resolved_key = (key or self._get_preview_box_mode_key() or "AUTO").upper().strip()
        return PREVIEW_BOX_MODE_LABELS.get(resolved_key, PREVIEW_BOX_MODE_LABELS["AUTO"])

    @staticmethod
    def _normalize_preview_sort_mode_key(mode_key: str | None) -> str:
        normalized = str(mode_key or "DEFAULT").strip().upper() or "DEFAULT"
        legacy_aliases = {
            "PERFECT": "OK",
            "MANUAL": "M",
        }
        normalized = legacy_aliases.get(normalized, normalized)
        return normalized if normalized in PREVIEW_SORT_LABELS else "DEFAULT"

    def _get_preview_sort_mode_key(self) -> str:
        raw_value = (getattr(self, "preview_sort_mode_var", None).get() if hasattr(self, "preview_sort_mode_var") else "DEFAULT")
        return self._normalize_preview_sort_mode_key(raw_value)

    def _get_preview_sort_source_count(self, mode_key: str, data: dict | None = None) -> int:
        normalized_key = str(mode_key or "").strip().upper()
        source_data = data if isinstance(data, dict) else {}
        chars = list(source_data.get("characters", []) or []) if isinstance(source_data, dict) else []
        if not chars:
            return 0

        counts = self._count_character_sources(chars, data=source_data)
        if normalized_key == "YOLO":
            return int(counts.get("yolo", 0)) + int(counts.get("yolo_box_ocr", 0))
        if normalized_key == "OCR":
            return int(counts.get("ocr", 0))
        if normalized_key == "M":
            return int(counts.get("manual", 0))
        return 0

    def _get_preview_sort_priority(self, pid: str, data: dict, original_index: int):
        mode_key = self._get_preview_sort_mode_key()
        status = str((data or {}).get("status", "unknown")).strip().lower()
        strategy_bucket = self._get_perfect_strategy_bucket(data)
        total_boxes = len(list((data or {}).get("characters", []) or [])) if isinstance(data, dict) else 0

        if mode_key == "DEFAULT":
            return (0, int(original_index))

        if mode_key == "OK":
            if status == "perfect":
                return (0, -int(total_boxes), int(original_index))
            if status == "needs_fix":
                return (1, -int(total_boxes), int(original_index))
            return (2, -int(total_boxes), int(original_index))

        preferred_bucket = {
            "YOLO": {"yolo_exact", "yolo_box_ocr"},
            "OCR": {"ocr_exact"},
            "M": {"other_perfect"},
        }.get(mode_key)

        if preferred_bucket:
            source_count = self._get_preview_sort_source_count(mode_key, data=data)
            return (
                -int(source_count),
                -int(total_boxes),
                0 if (status == "perfect" and strategy_bucket in preferred_bucket) else 1,
                0 if status == "perfect" else (1 if status == "needs_fix" else 2),
                int(original_index),
            )

        return (0, int(original_index))

    def _get_sorted_preview_plate_ids(self, ordered_pids):
        base_order = list(ordered_pids or [])
        mode_key = self._get_preview_sort_mode_key()
        if mode_key == "DEFAULT":
            return base_order

        indexed = list(enumerate(base_order))
        indexed.sort(
            key=lambda item: self._get_preview_sort_priority(
                item[1],
                self.preview_metadata.get(item[1], {}),
                item[0],
            )
        )
        return [pid for _, pid in indexed]

    def _set_preview_sort_hover(self, mode_key: str, hovered: bool):
        normalized_key = str(mode_key or "").strip().upper()
        if hovered:
            self._preview_sort_hover_key = normalized_key
        elif self._preview_sort_hover_key == normalized_key:
            self._preview_sort_hover_key = None
        self._apply_preview_sort_bar_style()

    def _get_readable_text_color(self, background: str, preferred: str = None) -> str:
        def _normalize_hex(color_value):
            raw = str(color_value or "").strip()
            if not raw.startswith("#"):
                return None
            hex_part = raw[1:]
            if len(hex_part) == 3:
                hex_part = "".join(ch * 2 for ch in hex_part)
            if len(hex_part) != 6:
                return None
            try:
                return tuple(int(hex_part[i:i + 2], 16) for i in (0, 2, 4))
            except Exception:
                return None

        def _relative_luminance(rgb):
            channels = []
            for channel in rgb:
                normalized = channel / 255.0
                if normalized <= 0.03928:
                    channels.append(normalized / 12.92)
                else:
                    channels.append(((normalized + 0.055) / 1.055) ** 2.4)
            return (0.2126 * channels[0]) + (0.7152 * channels[1]) + (0.0722 * channels[2])

        def _contrast_ratio(color_a, color_b):
            lum_a = _relative_luminance(color_a)
            lum_b = _relative_luminance(color_b)
            lighter = max(lum_a, lum_b)
            darker = min(lum_a, lum_b)
            return (lighter + 0.05) / (darker + 0.05)

        bg_rgb = _normalize_hex(background)
        if bg_rgb is None:
            return preferred or "#ffffff"

        preferred_rgb = _normalize_hex(preferred)
        if preferred_rgb is not None and _contrast_ratio(bg_rgb, preferred_rgb) >= 4.5:
            return preferred

        dark_text = "#111111"
        light_text = "#ffffff"
        dark_rgb = _normalize_hex(dark_text)
        light_rgb = _normalize_hex(light_text)
        if dark_rgb is None or light_rgb is None:
            return preferred or light_text

        dark_ratio = _contrast_ratio(bg_rgb, dark_rgb)
        light_ratio = _contrast_ratio(bg_rgb, light_rgb)
        return dark_text if dark_ratio >= light_ratio else light_text

    def _apply_preview_sort_bar_style(self):
        palette = getattr(self.app, "palette", {})
        frame = getattr(self, "preview_sort_bar", None)
        label = getattr(self, "preview_sort_title_lbl", None)
        host = getattr(self, "preview_list_host", None)
        listbox = getattr(self, "plates_listbox", None)
        shell_bg = palette.get("panel_alt", palette.get("panel", "#252526"))
        list_bg = palette.get("input_bg", palette.get("panel", "#1f1f1f"))
        border = palette.get("border", "#3c3c3c")
        hover_bg = palette.get("button_hover", palette.get("surface_info", "#34373b"))
        active_bg = palette.get("surface_info", hover_bg)

        if host is not None:
            try:
                host.configure(bg=shell_bg)
            except Exception:
                pass
        if listbox is not None:
            try:
                select_bg, select_fg = self.app.get_list_selection_colors()
                listbox.configure(
                    bg=list_bg,
                    fg=palette.get("fg", "#f3f3f3"),
                    selectbackground=select_bg,
                    selectforeground=select_fg,
                    highlightthickness=1,
                    highlightbackground=border,
                    highlightcolor=border,
                    relief=tk.FLAT,
                    bd=0,
                )
            except Exception:
                pass
        if frame is not None:
            try:
                frame.configure(
                    bg=shell_bg,
                    highlightbackground=shell_bg,
                    highlightcolor=shell_bg,
                    padx=0,
                    pady=0,
                )
            except Exception:
                pass
        if label is not None:
            try:
                label.configure(
                    text="Sortowanie listy:",
                    bg=shell_bg,
                    fg=palette.get("muted", "#a0a0a0"),
                    font=("Segoe UI", 8, "bold"),
                )
            except Exception:
                pass
        buttons_frame = getattr(self, "preview_sort_buttons_frame", None)
        if buttons_frame is not None:
            try:
                buttons_frame.configure(bg=shell_bg)
            except Exception:
                pass
            for child in buttons_frame.winfo_children():
                if isinstance(child, tk.Frame):
                    try:
                        child.configure(bg=shell_bg)
                    except Exception:
                        pass

        active_key = self._get_preview_sort_mode_key()
        hover_key = str(getattr(self, "_preview_sort_hover_key", "") or "").strip().upper()
        for mode_key, button in getattr(self, "preview_sort_buttons", {}).items():
            if button is None:
                continue
            is_active = mode_key == active_key
            is_hovered = mode_key == hover_key
            tone_key = PREVIEW_SORT_COLOR_KEYS.get(mode_key, "muted")
            accent = palette.get(tone_key, palette.get("accent", "#4aa3ff"))
            base_mix = 0.80 if mode_key == "DEFAULT" else 0.72
            bg = blend_hex_colors(accent, shell_bg, base_mix)
            fg = palette.get("fg", "#f3f3f3")
            relief = tk.FLAT
            border_width = 0

            if is_active:
                bg = blend_hex_colors(accent, shell_bg, 0.42)
            elif is_hovered:
                bg = blend_hex_colors(accent, shell_bg, 0.56)

            resolved_fg = self._get_readable_text_color(bg, preferred=fg)
            active_bg_value = blend_hex_colors(accent, shell_bg, 0.48)
            active_fg = self._get_readable_text_color(active_bg_value, preferred=resolved_fg)

            try:
                button.configure(
                    text=str(PREVIEW_SORT_LABELS.get(mode_key, mode_key) or mode_key),
                    bg=bg,
                    fg=resolved_fg,
                    activebackground=active_bg_value,
                    activeforeground=active_fg,
                    relief=relief,
                    bd=border_width,
                    highlightbackground=shell_bg,
                    highlightcolor=shell_bg,
                    highlightthickness=0,
                    disabledforeground=resolved_fg,
                    font=("Segoe UI", 8, "bold" if is_active else "normal"),
                )
            except Exception:
                pass

    def _on_preview_sort_mode_change(self, mode_key: str = None):
        normalized_key = self._normalize_preview_sort_mode_key(
            mode_key or self._get_preview_sort_mode_key()
        )

        try:
            if self.preview_sort_mode_var.get() != normalized_key:
                self.preview_sort_mode_var.set(normalized_key)
        except Exception:
            pass

        try:
            self._save_local_setting("char_preview_sort_mode", normalized_key)
        except Exception:
            pass

        self._apply_preview_sort_bar_style()

        if hasattr(self, "plates_listbox"):
            self._rebuild_preview_listbox(preserve_selection=True)
            try:
                self._on_preview_select(None)
            except Exception:
                pass

    def _get_preview_box_variants(self, data: dict) -> dict:
        if not isinstance(data, dict):
            data = {}
        canonical_chars = self._sort_character_records_by_x(data.get("characters", []))
        yolo_filtered = self._sort_character_records_by_x(data.get("yolo_detections", []))
        yolo_nms = self._sort_character_records_by_x(data.get("yolo_nms_detections", []))
        yolo_raw = self._sort_character_records_by_x(data.get("yolo_raw_detections", []))

        if not yolo_filtered:
            yolo_from_canonical = [
                rec for rec in canonical_chars
                if isinstance(rec, dict) and str(rec.get("method", "")).strip().lower() == "yolo"
            ]
            yolo_filtered = self._sort_character_records_by_x(yolo_from_canonical)

        return {
            "FINAL": canonical_chars,
            "YOLO_FILTERED": yolo_filtered,
            "YOLO_NMS": yolo_nms,
            "YOLO_RAW": yolo_raw,
        }

    def _get_preview_box_records(self, data: dict):
        variants = self._get_preview_box_variants(data)
        method_name = self._get_detection_method_key()
        mode_key = self._get_preview_box_mode_key()

        if mode_key == "AUTO":
            final_records = list(variants.get("FINAL", []) or [])
            if final_records:
                return final_records, "FINAL"
            if method_name == "YOLO":
                for candidate_key in ("YOLO_FILTERED", "YOLO_NMS", "YOLO_RAW"):
                    candidate_records = variants.get(candidate_key, [])
                    if candidate_records:
                        return candidate_records, candidate_key
            for candidate_key in ("YOLO_FILTERED", "YOLO_NMS", "YOLO_RAW"):
                candidate_records = variants.get(candidate_key, [])
                if candidate_records:
                    return candidate_records, candidate_key
            return final_records, "FINAL"

        return variants.get(mode_key, []), mode_key

