    def _sync_preview_intro_wraplength(self, event=None):
        try:
            width = int(getattr(event, "width", 0) or getattr(self, "preview_tools", None).winfo_width() or 0)
        except Exception:
            width = 0
        wraplength = max(240, width - 24) if width > 0 else 780
        for widget_name in ("preview_intro_lbl", "preview_shortcuts_lbl"):
            widget = getattr(self, widget_name, None)
            if widget is None:
                continue
            try:
                widget.configure(wraplength=wraplength)
            except Exception:
                pass

