    def _get_yolo_runtime_settings(self):
        conf = float(self.yolo_conf_var.get())
        iou = float(self.yolo_iou_var.get())
        overlap = float(self.yolo_overlap_var.get())
        seq_center_y = float(self.yolo_seq_center_y_var.get())
        seq_min_h = float(self.yolo_seq_min_h_ratio_var.get())
        seq_max_h = float(self.yolo_seq_max_h_ratio_var.get())
        seq_max_w = float(self.yolo_seq_max_w_ratio_var.get())
        seq_soft_overlap = float(self.yolo_seq_soft_overlap_var.get())
        seq_hard_overlap = float(self.yolo_seq_hard_overlap_var.get())

        if not (0.0 <= conf <= 1.0):
            raise ValueError("Próg confidence YOLO musi być w zakresie 0.00-1.00.")
        if not (0.01 <= iou <= 0.99):
            raise ValueError("Próg NMS IoU musi być w zakresie 0.01-0.99.")
        if not (0.0 <= overlap <= 1.0):
            raise ValueError("Próg nakładania boxów musi być w zakresie 0.00-1.00.")
        if not (0.10 <= seq_center_y <= 1.50):
            raise ValueError("Tolerancja osi Y dla filtra sekwencji musi być w zakresie 0.10-1.50.")
        if not (0.20 <= seq_min_h <= 1.00):
            raise ValueError("Minimalna zgodność wysokości znaku musi być w zakresie 0.20-1.00.")
        if not (1.00 <= seq_max_h <= 3.50):
            raise ValueError("Maksymalna wysokość znaku względem mediany musi być w zakresie 1.00-3.50.")
        if seq_min_h >= seq_max_h:
            raise ValueError("Minimalna zgodność wysokości musi być mniejsza od maksymalnej wysokości względem mediany.")
        if not (1.00 <= seq_max_w <= 4.50):
            raise ValueError("Maksymalna szerokość znaku względem mediany musi być w zakresie 1.00-4.50.")
        if not (0.0 <= seq_soft_overlap <= 1.0):
            raise ValueError("Miękki próg konfliktu nakładania musi być w zakresie 0.00-1.00.")
        if not (0.0 <= seq_hard_overlap <= 1.0):
            raise ValueError("Twardy próg konfliktu nakładania musi być w zakresie 0.00-1.00.")
        if seq_soft_overlap > seq_hard_overlap:
            raise ValueError("Miękki próg konfliktu nie może być większy od twardego progu konfliktu.")

        return {
            "conf": conf,
            "iou": iou,
            "overlap": overlap,
            "agnostic_nms": bool(self.yolo_agnostic_nms_var.get()),
            "seq_center_y": seq_center_y,
            "seq_min_h": seq_min_h,
            "seq_max_h": seq_max_h,
            "seq_max_w": seq_max_w,
            "seq_soft_overlap": seq_soft_overlap,
            "seq_hard_overlap": seq_hard_overlap,
        }


    def _characters_to_text(self, chars) -> str:
        if chars is None:
            return ""

        if isinstance(chars, str):
            return chars

        if not isinstance(chars, list):
            return str(chars)

        prepared = []
        for i, rec in enumerate(self._sort_character_records_by_x(chars)):
            symbol, x_key = self._char_record_to_symbol_and_x(rec, fallback_index=i)
            if symbol:
                prepared.append((x_key, symbol))

        prepared.sort(key=lambda item: item[0])
        return "".join(symbol for _, symbol in prepared)


    def _get_plate_listbox_ordinal(self, plate_id: str | None = None) -> int | None:
        pid = str(plate_id or "").strip()
        if not pid:
            return None

        current_order = list(getattr(self, "_listbox_pid_by_index", []) or [])
        if pid in current_order:
            return int(current_order.index(pid)) + 1

        metadata = getattr(self, "preview_metadata", {})
        if not isinstance(metadata, dict) or pid not in metadata:
            return None

        candidate_ids = list(getattr(self, "preview_plate_ids", []) or [])
        candidate_ids = [item for item in candidate_ids if item in metadata]
        if not candidate_ids:
            candidate_ids = list(metadata.keys())

        try:
            sorted_ids = self._get_sorted_preview_plate_ids(candidate_ids)
        except Exception:
            sorted_ids = list(candidate_ids)

        return (int(sorted_ids.index(pid)) + 1) if pid in sorted_ids else None

    def _format_preview_record_source_label(self, data: dict | None = None) -> tuple[str, str]:
        if not isinstance(data, dict):
            return "Źródło rekordu: brak zaznaczonej tablicy", "muted"

        bucket = self._get_plate_source_bucket(data, meta_path=self._loaded_meta_path)
        source_label = GOLD_SOURCE_LABELS.get(bucket, "Nieznane źródło")
        tone = "muted"
        if bucket in {"local_manual", "cvat_manual"}:
            tone = "success"
        elif bucket == "auto_preview":
            tone = "info"
        return f"Źródło rekordu: {source_label}", tone

    def _update_preview_record_source_label(self, data: dict | None = None):
        text, tone = self._format_preview_record_source_label(data)
        self._set_preview_record_source_info(text, tone)

    def _refresh_preview_import_focus_ui(self):
        frame = getattr(self, "preview_import_focus_frame", None)
        button = getattr(self, "preview_import_focus_btn", None)
        hint = getattr(self, "preview_import_focus_hint_lbl", None)

        known_ids = [str(pid or "").strip() for pid in list(getattr(self, "_preview_import_focus_plate_ids", []) or []) if str(pid or "").strip()]
        matching_ids = [pid for pid in known_ids if pid in getattr(self, "preview_metadata", {})]
        known_count = len(matching_ids)
        active = bool(getattr(self, "_preview_import_focus_active", False) and matching_ids)

        if frame is not None:
            try:
                if known_count:
                    if not str(frame.winfo_manager()):
                        frame.grid(row=3, column=0, columnspan=2, sticky="ew", pady=(0, 6))
                elif str(frame.winfo_manager()):
                    frame.grid_remove()
            except Exception:
                pass

        if button is not None:
            try:
                button.configure(
                    state=(tk.NORMAL if known_count else tk.DISABLED),
                    text=("Pokaż wszystkie tablice" if active else f"Pokaż tylko zaimportowane ({known_count})"),
                )
            except Exception:
                pass

        if hint is not None and known_count:
            if active:
                self._set_inline_status_label_state(
                    hint,
                    text=f"Widok zawężony do ostatniego importu CVAT: {known_count} tablic.",
                    tone="success",
                    emphasis=False,
                )
            else:
                self._set_inline_status_label_state(
                    hint,
                    text=f"Ostatni import CVAT zaktualizował {known_count} tablic. Użyj filtra, aby szybko je sprawdzić.",
                    tone="muted",
                    emphasis=False,
                )

    def _set_preview_import_focus(self, plate_ids, *, import_batch_id: str = "", activate: bool = False):
        unique_ids = []
        seen = set()
        for pid in list(plate_ids or []):
            normalized = str(pid or "").strip()
            if not normalized or normalized in seen:
                continue
            seen.add(normalized)
            unique_ids.append(normalized)

        self._preview_import_focus_plate_ids = unique_ids
        self._preview_import_focus_batch_id = str(import_batch_id or "").strip()
        self._preview_import_focus_active = bool(unique_ids) and bool(activate)
        self._refresh_preview_import_focus_ui()
        if hasattr(self, "plates_listbox"):
            self._rebuild_preview_listbox(preserve_selection=False)

    def _toggle_preview_import_focus(self):
        if not list(getattr(self, "_preview_import_focus_plate_ids", []) or []):
            return
        self._preview_import_focus_active = not bool(getattr(self, "_preview_import_focus_active", False))
        self._refresh_preview_import_focus_ui()
        if hasattr(self, "plates_listbox"):
            self._rebuild_preview_listbox(preserve_selection=False)

    def _format_plate_listbox_label(self, plate_id: str, data: dict) -> str:
        status = str(data.get("status", "unknown")).strip().lower()
        chars_txt = self._characters_to_text(data.get("characters", []))
        ordinal = self._get_plate_listbox_ordinal(plate_id)

        if status == "perfect":
            icon = "🟢"
        elif status == "needs_fix":
            icon = "🔴"
        else:
            icon = "⚪"

        prefix = f"{ordinal}. " if ordinal is not None else ""
        flags = []
        if status == "perfect":
            flags.append("OK")
        flags.extend(self._get_plate_listbox_source_flags(data))
        flag_prefix = f"{'|'.join(flags)} " if flags else ""

        label = f"{prefix}{flag_prefix}{icon} {plate_id}"
        if chars_txt:
            label += f" [{chars_txt}]"
        return label
    
    def _get_plate_row_foreground(self, status: str) -> str:
        status = str(status or "unknown").strip().lower()
        palette = getattr(self.app, "palette", {})

        if status == "perfect":
            return palette.get("success", "#27ae60")
        if status == "needs_fix":
            return palette.get("error", "#c0392b")
        return palette.get("muted_dim", "#444444")


    def _apply_plate_listbox_row_style(self, row_index: int, status: str):
        try:
            fg = self._get_plate_row_foreground(status)
            _select_bg, select_fg = self.app.get_list_selection_colors()
            self.plates_listbox.itemconfig(
                row_index,
                foreground=fg,
                selectforeground=select_fg
            )
        except Exception as e:
            logger.debug(f"Nie udało się ustawić stylu wiersza listy [{row_index}]: {e}")

    def _update_preview_info_label(self):
        try:
            counts = self._count_preview_statuses()
            self._preview_status_counts_snapshot = dict(counts)
            self._set_preview_info(f"Wczytano tablic: {counts['total']}", "neutral")
            self._set_preview_counts_info(
                perfect=counts["perfect"],
                needs_fix=counts["needs_fix"],
                unknown=counts["unknown"],
                char_boxes=counts.get("char_boxes", 0),
            )
            self._set_plates_legend_info(counts)
            self._update_preview_repair_progress_ui(counts)
            self._set_preview_fusion_info(
                self._format_perfect_strategy_counts(counts.get("strategy_counts", {})),
                "muted"
            )
            self._refresh_gold_export_filter_labels()
            self._refresh_gold_export_source_labels()
            self._refresh_gold_export_scope_label()
        except Exception as e:
            logger.debug(f"Nie udało się odświeżyć preview_info_lbl: {e}")

    def _update_preview_box_info_label(
        self,
        plate_id=None,
        mode_key=None,
        shown_count=None,
        yolo_raw_count=None,
        yolo_nms_count=None,
        yolo_filtered_count=None,
    ):
        if not plate_id:
            self._set_preview_box_info("Źródło końcowych ramek: brak zaznaczonej tablicy", "muted")
            return

        label = self._get_preview_box_mode_label(mode_key)
        details = [f"{plate_id}", f"ramki: {label}"]
        data = self.preview_metadata.get(str(plate_id), {}) if plate_id else {}
        status_meta = self._get_preview_status_presentation(data=data, plate_id=plate_id)
        status = str(status_meta.get("status", "unknown") or "unknown").strip().lower()
        details.append(str(status_meta.get("info_text", "status: nieoceniona")))

        if shown_count is not None:
            details.append(f"pokazano: {int(shown_count)}")

        yolo_parts = []
        if yolo_raw_count is not None:
            yolo_parts.append(f"raw={int(yolo_raw_count)}")
        if yolo_nms_count is not None:
            yolo_parts.append(f"nms={int(yolo_nms_count)}")
        if yolo_filtered_count is not None:
            yolo_parts.append(f"filtr={int(yolo_filtered_count)}")
        if yolo_parts:
            details.append("YOLO: " + ", ".join(yolo_parts))

        if bool(getattr(self, "_preview_char_add_mode", False)):
            details.append("korekta: nowy box")
        elif bool(getattr(self, "_preview_char_edit_mode", False)):
            details.append("korekta: edycja")

        severity = str(status_meta.get("severity", "muted") or "muted").strip().lower()
        if severity == "success":
            tone = "success"
        elif severity == "error":
            tone = "error"
        elif severity == "warning" or status == "needs_fix":
            tone = "warning"
        else:
            tone = "info" if shown_count else "warning"
        self._set_preview_box_info(" | ".join(details), tone)

    def _on_preview_box_mode_change(self, event=None):
        try:
            self._save_local_setting("char_preview_box_mode", self._get_preview_box_mode_key())
        except Exception:
            pass
        if self._get_preview_box_mode_key() != "FINAL" and (
            bool(getattr(self, "_preview_char_edit_mode", False))
            or bool(getattr(self, "_preview_char_add_mode", False))
        ):
            self._preview_char_edit_mode = False
            self._preview_char_add_mode = False
            self._preview_char_add_modifier_down = False
            self._preview_char_drag_state = None
            self._preview_char_add_state = None
        try:
            self._refresh_preview_mode_overlay_visibility()
        except Exception:
            pass
        self._refresh_preview_editor_toolbar()
        self._on_preview_select(None)

    def _rebuild_preview_listbox(self, preserve_selection: bool = True):
        selected_pid = None

        if preserve_selection:
            try:
                sel = self.plates_listbox.curselection()
                if sel:
                    idx = sel[0]
                    if 0 <= idx < len(self._listbox_pid_by_index):
                        selected_pid = self._listbox_pid_by_index[idx]
            except Exception:
                selected_pid = None

        current_order = [pid for pid in self._preview_base_plate_ids if pid in self.preview_metadata]
        appended = [pid for pid in self.preview_metadata.keys() if pid not in current_order]
        self._preview_base_plate_ids = current_order + appended
        visible_plate_ids = list(self._preview_base_plate_ids)
        if bool(getattr(self, "_preview_import_focus_active", False)):
            imported_set = {
                str(pid or "").strip()
                for pid in list(getattr(self, "_preview_import_focus_plate_ids", []) or [])
                if str(pid or "").strip()
            }
            visible_plate_ids = [pid for pid in visible_plate_ids if pid in imported_set]

        self.preview_plate_ids = list(visible_plate_ids)
        self._listbox_pid_by_index = self._get_sorted_preview_plate_ids(self.preview_plate_ids)
        self._refresh_preview_import_focus_ui()

        self._reloading_preview = True
        try:
            self.plates_listbox.delete(0, tk.END)
            for idx, pid in enumerate(self._listbox_pid_by_index):
                data = self.preview_metadata.get(pid, {})
                status = str(data.get("status", "unknown")).strip().lower()
                label = self._format_plate_listbox_label(pid, data)

                self.plates_listbox.insert(tk.END, label)
                self._apply_plate_listbox_row_style(idx, status)

            restore_idx = None
            if selected_pid and selected_pid in self._listbox_pid_by_index:
                restore_idx = self._listbox_pid_by_index.index(selected_pid)
            elif self._listbox_pid_by_index:
                restore_idx = 0

            if restore_idx is not None:
                self._clear_listbox_selection_fast(self.plates_listbox)
                self.plates_listbox.selection_set(restore_idx)
                self.plates_listbox.activate(restore_idx)
                self.plates_listbox.see(restore_idx)
                try:
                    self.frame.after_idle(
                        lambda: self.plates_listbox.event_generate("<<ListboxSelect>>")
                    )
                except Exception:
                    pass
            else:
                self._update_preview_record_source_label(None)

            self._update_preview_info_label()

            try:
                self.plates_listbox.update_idletasks()
            except Exception:
                pass
            try:
                self.frame.update_idletasks()
            except Exception:
                pass

        finally:
            self._reloading_preview = False

    def _clear_project_bound_session_values(self, clear_ui: bool = False):
        """
        Usuwa z local_session ścieżki, które w trybie kampanii są sterowane przez Wizard.
        """
        project_bound_keys = (
            "char_annotation_run_dir",
            "char_xml_path",
            "char_images_dir",
            "char_preview_dir",
            "char_yolo_model",
            "char_pz3_dataset_source_mode",
            "char_pz3_existing_dataset",
        )

        for key in project_bound_keys:
            self.local_session.pop(key, None)

        try:
            with open(self.session_file, "w", encoding="utf-8") as f:
                json.dump(self.local_session, f, indent=4, ensure_ascii=False)
        except Exception:
            pass

        if clear_ui:
            try:
                self.annotation_run_dir_var.set("")
            except Exception:
                pass
            try:
                self.xml_path_var.set("")
            except Exception:
                pass
            try:
                self.images_dir_var.set("")
            except Exception:
                pass
            try:
                self._set_preview_dir_runtime_value("", persist_registry=False)
            except Exception:
                pass
            try:
                self.yolo_model_path_var.set("")
            except Exception:
                pass
            try:
                self.pz3_dataset_source_mode_var.set("perfect")
            except Exception:
                pass
            try:
                self.pz3_existing_dataset_var.set("")
            except Exception:
                pass


    def _apply_preview_metadata_update(self, new_meta: dict, preserve_selection: bool = True):
        self.preview_metadata = self._recalculate_preview_statuses_in_metadata(new_meta)
        current_order = [pid for pid in self._preview_base_plate_ids if pid in self.preview_metadata]
        appended = [pid for pid in self.preview_metadata.keys() if pid not in current_order]
        self._preview_base_plate_ids = current_order + appended
        self.preview_plate_ids = list(self._preview_base_plate_ids)
        self._rebuild_preview_listbox(preserve_selection=preserve_selection)

        try:
            self._on_preview_select(None)
        except Exception:
            pass


    def _refresh_plate_rows_in_place(self):
        """
        Odświeża TYLKO tekst istniejących wierszy listy tablic,
        bez przebudowy całego runu i bez resetowania selekcji.
        """
        try:
            self._reloading_preview = True

            # fallback: jeśli mapowanie indeks->pid nie istnieje, zbuduj je z preview_plate_ids
            if not getattr(self, "_listbox_pid_by_index", None):
                self._listbox_pid_by_index = list(self.preview_plate_ids)

            row_count = self.plates_listbox.size()
            pid_count = len(self._listbox_pid_by_index)
            limit = min(row_count, pid_count)

            for idx in range(limit):
                plate_id = self._listbox_pid_by_index[idx]
                data = self.preview_metadata.get(plate_id, {})
                status = str(data.get("status", "unknown")).strip().lower()
                label = self._format_plate_listbox_label(plate_id, data)

                try:
                    self.plates_listbox.delete(idx)
                    self.plates_listbox.insert(idx, label)
                    self._apply_plate_listbox_row_style(idx, status)
                except Exception:
                    pass

            # jeśli z jakiegoś powodu lista w UI była krótsza, dopełnij brakujące rekordy
            if pid_count > row_count:
                for idx in range(row_count, pid_count):
                    plate_id = self._listbox_pid_by_index[idx]
                    data = self.preview_metadata.get(plate_id, {})
                    status = str(data.get("status", "unknown")).strip().lower()
                    label = self._format_plate_listbox_label(plate_id, data)

                    try:
                        self.plates_listbox.insert(tk.END, label)
                        self._apply_plate_listbox_row_style(idx, status)
                    except Exception:
                        pass

            self._update_preview_info_label()

        finally:
            self._reloading_preview = False

    def _refresh_plates_listbox(self, preserve_selection: bool = True):
        """
        Wrapper kompatybilności.
        Kanoniczny pełny rebuild listy tablic wykonuje _rebuild_preview_listbox().
        """
        self._rebuild_preview_listbox(preserve_selection=preserve_selection)

    def _set_detection_process_log_visibility(self, visible: bool):
        self._detection_log_visible = bool(visible)
        try:
            self.detection_log_frame.grid_remove()
        except Exception:
            pass

        if self._detection_log_visible:
            try:
                if hasattr(self.app, "show_global_terminal"):
                    self.app.show_global_terminal()
            except Exception:
                pass

        try:
            self.btn_toggle_detection_log.config(text="Terminal")
        except Exception:
            pass
        return

        try:
            if self._detection_log_visible:
                self.detection_log_frame.grid()
            else:
                self.detection_log_frame.grid_remove()
        except Exception:
            pass

        try:
            self.btn_toggle_detection_log.config(
                text="Ukryj terminal" if self._detection_log_visible else "Pokaz terminal"
            )
        except Exception:
            pass

    def _toggle_detection_process_log(self):
        try:
            if hasattr(self.app, "toggle_global_terminal"):
                self.app.toggle_global_terminal()
                return
        except Exception:
            pass
        self._set_detection_process_log_visibility(
            not getattr(self, "_detection_log_visible", False)
        )



