    def _sync_detect_right_scrollregion(self, event=None):
        if not hasattr(self, "detect_right_canvas") or self.detect_right_canvas is None:
            return

        try:
            self.detect_right_canvas.configure(scrollregion=self.detect_right_canvas.bbox("all"))
        except Exception:
            pass

        self._apply_preview_mode_overlay_style()
        self._refresh_detect_mode_cards()
        self._refresh_detection_advanced_sections()

    def _sync_extract_left_scrollregion(self, event=None):
        if not hasattr(self, "extract_left_canvas") or self.extract_left_canvas is None:
            return

        try:
            self.extract_left_canvas.configure(scrollregion=self.extract_left_canvas.bbox("all"))
        except Exception:
            pass

    def _sync_extract_left_canvas_width(self, event=None):
        if not hasattr(self, "extract_left_canvas") or self.extract_left_canvas is None:
            return

        try:
            width = max(50, int(self.extract_left_canvas.winfo_width()))
            inset = max(0, int(getattr(self, "_extract_content_inset", 0)))
            max_width = max(320, int(getattr(self, "_extract_content_max_width", width)))
            target_width = max(50, min(max_width, width - (2 * inset)))
            self.extract_left_canvas.coords(self.extract_left_content_window, inset, 0)
            self.extract_left_canvas.itemconfigure(self.extract_left_content_window, width=target_width)
        except Exception:
            pass

    def _sync_detect_right_canvas_width(self, event=None):
        if not hasattr(self, "detect_right_canvas") or self.detect_right_canvas is None:
            return

        try:
            width = max(50, int(self.detect_right_canvas.winfo_width()))
            self.detect_right_canvas.itemconfigure(self.detect_right_content_window, width=width)
        except Exception:
            pass

        self._schedule_detect_right_adaptive_wrap_refresh()

    def _refresh_detect_right_adaptive_wraps(self):
        try:
            self._detect_right_wrap_after_id = None
        except Exception:
            pass

        content = getattr(self, "detect_right_content", None)
        if content is None:
            return

        try:
            self.app._refresh_adaptive_wraps(content)
        except Exception:
            pass

    def _schedule_detect_right_adaptive_wrap_refresh(self):
        content = getattr(self, "detect_right_content", None)
        if content is None:
            return

        pending = getattr(self, "_detect_right_wrap_after_id", None)
        if pending is not None:
            return

        try:
            self._detect_right_wrap_after_id = content.after_idle(self._refresh_detect_right_adaptive_wraps)
        except Exception:
            try:
                self._detect_right_wrap_after_id = None
            except Exception:
                pass

    def _sync_cvat_export_scrollregion(self, event=None):
        if not hasattr(self, "cvat_export_canvas") or self.cvat_export_canvas is None:
            return

        try:
            self.cvat_export_canvas.configure(scrollregion=self.cvat_export_canvas.bbox("all"))
        except Exception:
            pass

    def _sync_cvat_export_canvas_width(self, event=None):
        if not hasattr(self, "cvat_export_canvas") or self.cvat_export_canvas is None:
            return

        try:
            inset = max(0, int(getattr(self, "_pz3_content_inset", 0)))
            max_width = max(320, int(getattr(self, "_pz3_content_max_width", 780)))
            available_width = max(50, int(self.cvat_export_canvas.winfo_width()) - (2 * inset))
            width = min(available_width, max_width)
            self.cvat_export_canvas.coords(self.cvat_export_content_window, inset, 0)
            self.cvat_export_canvas.itemconfigure(self.cvat_export_content_window, width=width)
        except Exception:
            pass

        try:
            self.app._refresh_adaptive_wraps(self.cvat_export_content)
        except Exception:
            pass

    def _widget_contains_point(self, widget, x_root: int, y_root: int) -> bool:
        if widget is None:
            return False
        try:
            wx = int(widget.winfo_rootx())
            wy = int(widget.winfo_rooty())
            return wx <= x_root < (wx + int(widget.winfo_width())) and wy <= y_root < (wy + int(widget.winfo_height()))
        except Exception:
            return False

    def _mousewheel_units(self, event) -> int:
        return self._inertial_scroll.mousewheel_units(event)

    def _on_plates_listbox_mousewheel(self, event):
        listbox = getattr(self, "plates_listbox", None)
        if listbox is None:
            return None
        units = self._inertial_scroll.mousewheel_units(event)
        if units == 0 or not self._inertial_scroll.listbox_can_scroll(listbox, units):
            return None
        self._inertial_scroll.queue_listbox_by_units(
            listbox,
            units,
            magnitude=self._inertial_scroll.mousewheel_magnitude(event),
        )
        return "break"

    def _detect_right_canvas_overflows(self) -> bool:
        canvas = getattr(self, "detect_right_canvas", None)
        if canvas is None:
            return False

        try:
            bbox = canvas.bbox("all")
            if not bbox:
                return False
            content_height = int(bbox[3]) - int(bbox[1])
            viewport_height = int(canvas.winfo_height())
            return content_height > viewport_height + 1
        except Exception:
            return False

    def _on_detect_right_global_mousewheel(self, event):
        try:
            if callable(getattr(self.app, "handle_help_panel_scroll_override", None)):
                result = self.app.handle_help_panel_scroll_override(event)
                if result == "break":
                    return "break"
        except Exception:
            pass

        if self._inertial_scroll.scroll_canvas_if_targeted(
            getattr(self, "detect_right_canvas", None),
            event,
            pointer_widget=self.frame,
            overflow_checker=self._detect_right_canvas_overflows,
        ):
            return "break"
        return None

    def _cvat_export_canvas_overflows(self) -> bool:
        canvas = getattr(self, "cvat_export_canvas", None)
        if canvas is None:
            return False

        try:
            bbox = canvas.bbox("all")
            if not bbox:
                return False
            content_height = int(bbox[3]) - int(bbox[1])
            viewport_height = int(canvas.winfo_height())
            return content_height > viewport_height + 1
        except Exception:
            return False

    def _extract_left_canvas_overflows(self) -> bool:
        canvas = getattr(self, "extract_left_canvas", None)
        if canvas is None:
            return False

        try:
            bbox = canvas.bbox("all")
            if not bbox:
                return False
            content_height = int(bbox[3]) - int(bbox[1])
            viewport_height = int(canvas.winfo_height())
            return content_height > viewport_height + 1
        except Exception:
            return False

    def _on_cvat_export_global_mousewheel(self, event):
        try:
            if callable(getattr(self.app, "handle_help_panel_scroll_override", None)):
                result = self.app.handle_help_panel_scroll_override(event)
                if result == "break":
                    return "break"
        except Exception:
            pass

        self._suppress_selection_hover_during_scroll()
        if self._inertial_scroll.scroll_canvas_if_targeted(
            getattr(self, "cvat_export_canvas", None),
            event,
            pointer_widget=self.frame,
            overflow_checker=self._cvat_export_canvas_overflows,
        ):
            return "break"
        return None

    def _suppress_selection_hover_during_scroll(self, duration_ms: int = 320) -> None:
        self._selection_hover_suppressed = True
        after_id = getattr(self, "_selection_hover_suppress_after_id", None)
        if after_id:
            try:
                self.frame.after_cancel(after_id)
            except Exception:
                pass

        def _clear_hover_suppression():
            self._selection_hover_suppressed = False
            self._selection_hover_suppress_after_id = None

        try:
            self._selection_hover_suppress_after_id = self.frame.after(int(duration_ms), _clear_hover_suppression)
        except Exception:
            self._selection_hover_suppressed = False
            self._selection_hover_suppress_after_id = None

    def _restore_scroll_canvas_focus(self, canvas):
        if canvas is None:
            return
        try:
            canvas.focus_set()
        except Exception:
            pass

    def _redirect_child_mousewheel_to_canvas(self, event, canvas, overflow_checker=None):
        try:
            if callable(getattr(self.app, "handle_help_panel_scroll_override", None)):
                result = self.app.handle_help_panel_scroll_override(event)
                if result == "break":
                    return "break"
        except Exception:
            pass

        if self._inertial_scroll.redirect_child_mousewheel_to_canvas(
            event,
            canvas,
            pointer_widget=self.frame,
            overflow_checker=overflow_checker,
        ):
            self._restore_scroll_canvas_focus(canvas)
            return "break"

        self._restore_scroll_canvas_focus(canvas)
        return "break"

    def _redirect_pz3_child_mousewheel_to_canvas(self, event):
        try:
            if callable(getattr(self.app, "handle_help_panel_scroll_override", None)):
                result = self.app.handle_help_panel_scroll_override(event)
                if result == "break":
                    return "break"
        except Exception:
            pass

        canvas = getattr(self, "cvat_export_canvas", None)
        self._suppress_selection_hover_during_scroll()
        if self._inertial_scroll.redirect_child_mousewheel_to_canvas(
            event,
            canvas,
            pointer_widget=self.frame,
            overflow_checker=self._cvat_export_canvas_overflows,
        ):
            self._restore_scroll_canvas_focus(canvas)
            return "break"
        self._restore_scroll_canvas_focus(canvas)
        return "break"

    def _bind_scroll_canvas_children(self, root, canvas, overflow_checker=None):
        if root is None or canvas is None:
            return

        release_focus_classes = {
            "TButton",
            "Button",
            "TCheckbutton",
            "Checkbutton",
            "TRadiobutton",
            "Radiobutton",
            "TScale",
            "Scale",
            "TCombobox",
            "Spinbox",
        }

        def _walk(widget):
            def _handle_mousewheel(event, c=canvas, oc=overflow_checker):
                if c is getattr(self, "cvat_export_canvas", None):
                    return self._redirect_pz3_child_mousewheel_to_canvas(event)
                return self._redirect_child_mousewheel_to_canvas(event, c, oc)

            try:
                widget.bind(
                    "<MouseWheel>",
                    _handle_mousewheel,
                    add="+"
                )
                widget.bind(
                    "<Button-4>",
                    _handle_mousewheel,
                    add="+"
                )
                widget.bind(
                    "<Button-5>",
                    _handle_mousewheel,
                    add="+"
                )
            except Exception:
                pass

            try:
                class_name = str(widget.winfo_class())
            except Exception:
                class_name = ""

            if class_name in release_focus_classes:
                try:
                    widget.configure(takefocus=0)
                except Exception:
                    pass
                try:
                    widget.bind("<ButtonRelease-1>", lambda _e, c=canvas: self._restore_scroll_canvas_focus(c), add="+")
                except Exception:
                    pass
                if class_name == "TCombobox":
                    try:
                        widget.bind("<<ComboboxSelected>>", lambda _e, c=canvas: self._restore_scroll_canvas_focus(c), add="+")
                    except Exception:
                        pass

            for child in widget.winfo_children():
                _walk(child)

        _walk(root)

    def _panel_style_name(self, tone: str = "neutral", emphasis: bool = False) -> str:
        tone_key = str(tone or "").strip().lower()
        if emphasis:
            return {
                "neutral": "PanelStatusNeutral.TLabel",
                "info": "PanelStatusInfo.TLabel",
                "success": "PanelStatusSuccess.TLabel",
                "warning": "PanelStatusWarning.TLabel",
                "error": "PanelStatusError.TLabel",
                "muted": "PanelStatusNeutral.TLabel",
            }.get(tone_key, "PanelStatusNeutral.TLabel")

        return {
            "neutral": "PanelMuted.TLabel",
            "muted": "PanelMuted.TLabel",
            "info": "PanelInfo.TLabel",
            "success": "PanelSuccess.TLabel",
            "warning": "PanelStatusWarning.TLabel",
            "error": "PanelError.TLabel",
        }.get(tone_key, "PanelMuted.TLabel")

    def _set_themed_label_state(self, widget, text: str | None = None, tone: str = "neutral", emphasis: bool = False):
        if widget is None:
            return

        config_kwargs = {"style": self._panel_style_name(tone=tone, emphasis=emphasis)}
        if text is not None:
            config_kwargs["text"] = text

        widget.config(**config_kwargs)

    def _mark_inline_status_contrast_boost(self, widget):
        if widget is None or not isinstance(widget, tk.Label):
            return

        try:
            widget._inline_status_contrast_boost = True
        except Exception:
            return

        try:
            self._set_inline_status_label_state(
                widget,
                text=widget.cget("text"),
                tone=getattr(widget, "_inline_status_tone", "muted"),
                emphasis=bool(getattr(widget, "_inline_status_emphasis", False)),
            )
        except Exception:
            pass

    def _set_inline_status_label_state(self, widget, text: str | None = None, tone: str = "neutral", emphasis: bool = False) -> bool:
        if widget is None or not isinstance(widget, tk.Label):
            return False

        palette = getattr(self.app, "palette", {})
        bg = palette.get("bg", "#1f1f1f")
        bg_override = str(getattr(widget, "_inline_status_bg", "") or "").strip()
        if bg_override:
            bg = bg_override
        try:
            parent = widget.nametowidget(widget.winfo_parent())
        except Exception:
            parent = None

        if not bg_override:
            for candidate in (parent, widget):
                if candidate is None:
                    continue
                try:
                    bg_candidate = candidate.cget("bg")
                    if bg_candidate:
                        bg = bg_candidate
                        break
                except Exception:
                    pass
                try:
                    bg_candidate = candidate.cget("background")
                    if bg_candidate:
                        bg = bg_candidate
                        break
                except Exception:
                    pass
                try:
                    style_name = str(candidate.cget("style") or "").strip()
                    if style_name:
                        bg_candidate = self.app.style.lookup(style_name, "background")
                        if bg_candidate:
                            bg = bg_candidate
                            break
                except Exception:
                    pass
                try:
                    style_name = candidate.winfo_class()
                    bg_candidate = ttk.Style().lookup(style_name, "background")
                    if bg_candidate:
                        bg = bg_candidate
                        break
                except Exception:
                    pass

        tone_key = str(tone or "").strip().lower()
        fg = {
            "default": palette.get("fg", "#f3f3f3"),
            "neutral": palette.get("muted", "#9a9a9a"),
            "muted": palette.get("muted", "#9a9a9a"),
            "info": palette.get("info", palette.get("accent", "#4aa3ff")),
            "success": palette.get("success", "#2ecc71"),
            "warning": palette.get("warning", "#f39c12"),
            "error": palette.get("error", "#e74c3c"),
        }.get(tone_key, palette.get("muted", "#9a9a9a"))

        if tone_key in {"neutral", "muted"} and bool(getattr(widget, "_inline_status_contrast_boost", False)):
            is_light_background = self._get_readable_text_color(bg, preferred="#111111") == "#111111"
            preferred_fg = blend_hex_colors(
                palette.get("fg", "#f3f3f3"),
                bg,
                0.10 if is_light_background else 0.28,
            )
            fg = self._get_readable_text_color(bg, preferred=preferred_fg)

        custom_font = getattr(widget, "_inline_status_font", None)
        config_kwargs = {
            "bg": bg,
            "fg": fg,
            "font": custom_font or (("Segoe UI", 10, "bold") if emphasis else ("Segoe UI", 9)),
        }
        if text is not None:
            config_kwargs["text"] = text

        widget._inline_status_tone = tone_key
        widget._inline_status_emphasis = bool(emphasis)
        widget.config(**config_kwargs)
        return True

    def _set_extraction_status(self, text: str, tone: str = "neutral"):
        label = getattr(self, "ext_status", None)
        if not self._set_inline_status_label_state(label, text=text, tone=tone, emphasis=True):
            self._set_themed_label_state(label, text=text, tone=tone, emphasis=True)
        try:
            if bool(getattr(self, "_campaign_detect_splash_visible", False)):
                title = str(getattr(self, "_campaign_detect_splash_title_text", "") or "").strip()
                tone_key = str(tone or "neutral").strip().lower()
                if tone_key == "error":
                    title = "Nie udało się przygotować tablic dla Z3"
                elif tone_key == "success":
                    title = "Tablice gotowe do pracy nad znakami"
                elif not title:
                    title = "Przygotowuję wycięte tablice dla Z3"

                progress_value = None
                if tone_key != "error":
                    try:
                        progress_value = float(getattr(self, "ext_progress", None).cget("value") or 0.0)
                    except Exception:
                        progress_value = getattr(self, "_campaign_detect_splash_progress_value", None)

                self._show_campaign_detect_splash(
                    title=title,
                    body=str(text or "").strip(),
                    tone=tone_key,
                    progress=progress_value,
                    show_progress=(tone_key != "error"),
                    show_return=(tone_key == "error"),
                )
        except Exception:
            pass

    def _refresh_continue_source_summary(self):
        if not hasattr(self, "extract_continue_xml_value_lbl"):
            return

        xml_raw = str(self.xml_path_var.get() if hasattr(self, "xml_path_var") else "").strip()
        images_raw = str(self.images_dir_var.get() if hasattr(self, "images_dir_var") else "").strip()
        has_source = bool(xml_raw or images_raw)
        xml_text = xml_raw or "Po użyciu runu Z2 pojawi się ścieżka annotations.xml."
        images_text = images_raw or "Po użyciu runu Z2 pojawi się katalog obrazów źródłowych."
        tone = "success" if bool(getattr(self, "_extract_last_source_binding_result", {}).get("ok")) else ("muted" if has_source else "warning")

        for label, text in (
            (getattr(self, "extract_continue_xml_value_lbl", None), xml_text),
            (getattr(self, "extract_continue_images_value_lbl", None), images_text),
        ):
            if label is None:
                continue
            try:
                self._set_inline_status_label_state(label, text=text, tone=tone, emphasis=False)
            except Exception:
                pass

    def _format_extract_source_datetime(self, path_like) -> str:
        raw = str(path_like or "").strip()
        if not raw:
            return "Brak przejętego runu"
        try:
            import datetime as _datetime

            path = Path(raw)
            if not path.exists():
                return "Nie znaleziono katalogu runu"
            stamp = path.stat().st_ctime
            return _datetime.datetime.fromtimestamp(stamp).strftime("%Y-%m-%d %H:%M")
        except Exception:
            return "Nie udało się odczytać daty"

    def _format_extract_source_folder_name(self, path_like, fallback: str = "Brak danych") -> str:
        raw = str(path_like or "").strip()
        if not raw:
            return fallback
        try:
            path = Path(raw)
            name = path.name or raw
            parent = path.parent.name
            return f"{parent}/{name}" if parent else name
        except Exception:
            return raw

    def _build_continue_extract_summary_rows(self, output_text: str) -> list[tuple[str, str, str]]:
        binding = dict(getattr(self, "_extract_last_source_binding_result", {}) or {})
        run_raw = str(self.annotation_run_dir_var.get() if hasattr(self, "annotation_run_dir_var") else "").strip()
        images_raw = str(self.images_dir_var.get() if hasattr(self, "images_dir_var") else "").strip()

        try:
            run_name = Path(run_raw).name if run_raw else ""
        except Exception:
            run_name = run_raw
        run_text = run_name or "Nie przejęto runu z Z2"

        matched = int(binding.get("matched", 0) or 0)
        total = int(binding.get("total", 0) or binding.get("xml_images_total", 0) or 0)
        if total > 0 and matched > 0:
            images_count = f"zgodne zdjęcia: {matched}; obrazy w XML: {total}"
        elif total > 0:
            images_count = f"{total} zdjęć w XML"
        else:
            images_count = "Brak potwierdzonej liczby zdjęć"

        plate_count = int(binding.get("plate_count", 0) or 0)
        plates_text = f"{plate_count} tablic do wycięcia" if plate_count > 0 else "Brak potwierdzonych tablic do wycięcia"

        return [
            ("Run anotacji", run_text, "Źródło przejęte z Z2"),
            ("Data utworzenia", self._format_extract_source_datetime(run_raw), "Data katalogu runu"),
            (
                "Katalog zdjęć",
                self._format_extract_source_folder_name(images_raw, "Brak skorelowanego katalogu zdjęć"),
                "Obrazy zgodne z XML",
            ),
            ("Liczba zdjęć", images_count, "Pula sprawdzona względem XML"),
            ("Liczba anotacji", plates_text, "Tablice do przygotowania w PZ2"),
            ("Wynik", output_text, "Docelowa paczka PZ2"),
        ]

    def _set_extract_start_summary_rows(self, rows: list[tuple[str, ...]]) -> None:
        row_widgets = list(getattr(self, "_extract_start_summary_rows", []) or [])
        if not row_widgets:
            return

        header_widgets = list(getattr(self, "_extract_start_summary_header_widgets", []) or [])
        for header_widget, header_text in zip(header_widgets, ("Pozycja", "Wartość", "Znaczenie")):
            try:
                header_widget.grid()
                header_widget.configure(text=header_text)
            except Exception:
                pass

        for index, widgets in enumerate(row_widgets):
            title_lbl = widgets[0] if len(widgets) > 0 else None
            value_lbl = widgets[1] if len(widgets) > 1 else None
            note_lbl = widgets[2] if len(widgets) > 2 else None
            visible = index < len(rows)
            row_values = tuple(rows[index]) if visible else ("", "", "")
            title_text = row_values[0] if len(row_values) > 0 else ""
            value_text = row_values[1] if len(row_values) > 1 else ""
            note_text = row_values[2] if len(row_values) > 2 else ""
            for widget in (title_lbl, value_lbl, note_lbl):
                if widget is None:
                    continue
                try:
                    if visible:
                        widget.grid()
                    else:
                        widget.grid_remove()
                except Exception:
                    pass
            try:
                title_lbl.configure(text=str(title_text or ""))
            except Exception:
                pass
            try:
                value_lbl.configure(text=str(value_text or ""))
            except Exception:
                pass
            try:
                note_lbl.configure(text=str(note_text or ""))
            except Exception:
                pass

    def _format_extract_start_path(self, value: str, fallback: str) -> str:
        raw = str(value or "").strip()
        if not raw:
            return fallback
        try:
            path = Path(raw)
            name = path.name or raw
            parent = path.parent.name
            return f"{parent}/{name}" if parent else name
        except Exception:
            return raw

    def _refresh_extract_start_card_style(self):
        card = getattr(self, "extract_start_action_card", None)
        inner = getattr(self, "extract_start_action_inner", None)
        if card is None or inner is None:
            return

        palette = getattr(self.app, "palette", {})
        panel = palette.get("panel", "#252526")
        panel_alt = palette.get("panel_alt", "#2d2d30")
        success = palette.get("success", "#2ecc71")
        source_ready = bool(getattr(self, "_extract_last_source_binding_result", {}).get("ok"))
        try:
            preview_ready = bool(self._is_extract_preview_ready())
        except Exception:
            preview_ready = False
        accent = success if (source_ready or preview_ready) else palette.get("warning", "#f39c12")
        border = blend_hex_colors(accent, palette.get("panel_border", palette.get("border", "#3c3c3c")), 0.34)
        card_bg = blend_hex_colors(palette.get("surface_success", panel_alt), panel, 0.72)
        action_bg = blend_hex_colors(palette.get("surface_info", panel_alt), card_bg, 0.62)
        fg = palette.get("fg", "#f3f3f3")
        muted = self._get_readable_text_color(card_bg, preferred=palette.get("muted", "#9a9a9a"))
        badge_fg = self._get_readable_text_color(accent, preferred="#ffffff")

        for widget, bg in (
            (card, border),
            (inner, card_bg),
            (getattr(self, "extract_start_header_row", None), card_bg),
            (getattr(self, "extract_start_actions_panel", None), action_bg),
            (getattr(self, "extract_start_actions_row", None), action_bg),
        ):
            if widget is None:
                continue
            try:
                widget.configure(bg=bg)
            except Exception:
                pass

        summary_frame = getattr(self, "extract_start_summary_frame", None)
        if summary_frame is not None:
            try:
                summary_frame.configure(
                    bg=border,
                    highlightbackground=border,
                    highlightcolor=border,
                )
            except Exception:
                pass

        for row_index, row in enumerate(getattr(self, "_extract_start_summary_rows", []) or []):
            row_bg = card_bg if row_index % 2 == 0 else blend_hex_colors(panel_alt, card_bg, 0.24)
            for widget in row:
                if widget is None:
                    continue
                try:
                    widget.configure(bg=row_bg)
                except Exception:
                    pass
            try:
                row[0].configure(fg=muted, font=("Segoe UI", 8, "bold"))
                row[1].configure(fg=fg, font=("Segoe UI", 9, "bold"))
                if len(row) > 2 and row[2] is not None:
                    row[2].configure(fg=muted, font=("Segoe UI", 8))
            except Exception:
                pass

        for header in list(getattr(self, "_extract_start_summary_header_widgets", []) or []):
            if header is None:
                continue
            try:
                header.configure(
                    bg=blend_hex_colors(panel_alt, card_bg, 0.36),
                    fg=muted,
                    font=("Segoe UI", 8, "bold"),
                )
            except Exception:
                pass

        for label_name, color, font in (
            ("extract_start_ready_badge_lbl", badge_fg, ("Segoe UI", 8, "bold")),
            ("extract_start_action_title_lbl", fg, ("Segoe UI Semibold", 11)),
            ("extract_start_action_desc_lbl", muted, ("Segoe UI", 9)),
            ("extract_start_xml_title_lbl", muted, ("Segoe UI", 8, "bold")),
            ("extract_start_images_title_lbl", muted, ("Segoe UI", 8, "bold")),
            ("extract_start_plates_title_lbl", muted, ("Segoe UI", 8, "bold")),
            ("extract_start_output_title_lbl", muted, ("Segoe UI", 8, "bold")),
            ("extract_start_xml_value_lbl", fg, ("Segoe UI", 9, "bold")),
            ("extract_start_images_value_lbl", fg, ("Segoe UI", 9, "bold")),
            ("extract_start_plates_value_lbl", fg, ("Segoe UI", 9, "bold")),
            ("extract_start_output_value_lbl", fg, ("Segoe UI", 9, "bold")),
            ("extract_start_action_note_lbl", muted, ("Segoe UI", 8)),
        ):
            label = getattr(self, label_name, None)
            if label is None:
                continue
            try:
                label.configure(
                    bg=accent if label_name == "extract_start_ready_badge_lbl" else card_bg,
                    fg=color,
                    font=font,
                )
            except Exception:
                pass

        note = getattr(self, "extract_start_action_note_lbl", None)
        if note is not None:
            try:
                note.configure(bg=action_bg)
            except Exception:
                pass

        status = getattr(self, "ext_status", None)
        if status is not None:
            try:
                status._inline_status_bg = action_bg
                self._set_inline_status_label_state(
                    status,
                    text=status.cget("text"),
                    tone=getattr(status, "_inline_status_tone", "neutral"),
                    emphasis=True,
                )
            except Exception:
                pass

        progress = getattr(self, "ext_progress", None)
        if isinstance(progress, SlimProgressBar):
            try:
                progress.configure(
                    bg=action_bg,
                    trough_color=blend_hex_colors(panel_alt, action_bg, 0.34),
                    fill_color=success,
                )
            except Exception:
                pass

    def _extract_source_manifest_path(self, preview_dir: Path | str | None = None) -> Path | None:
        preview_dir_raw = str(
            preview_dir
            if preview_dir is not None
            else (self.preview_dir_var.get() if hasattr(self, "preview_dir_var") else "")
            or ""
        ).strip()
        if not preview_dir_raw:
            return None
        try:
            return Path(preview_dir_raw) / "extract_manifest.json"
        except Exception:
            return None

    def _current_extract_source_payload(self) -> dict:
        def _path_text(var_name: str) -> str:
            try:
                raw = str(getattr(self, var_name).get() or "").strip()
            except Exception:
                raw = ""
            if not raw:
                return ""
            try:
                return str(Path(raw).resolve())
            except Exception:
                try:
                    return str(Path(raw))
                except Exception:
                    return raw

        return {
            "annotation_run_dir": _path_text("annotation_run_dir_var"),
            "xml_path": _path_text("xml_path_var"),
            "images_dir": _path_text("images_dir_var"),
        }

    def _preview_matches_current_extract_source(self, preview_dir=None) -> bool:
        manifest_path = self._extract_source_manifest_path(preview_dir)
        if manifest_path is None or not manifest_path.exists():
            return True
        try:
            manifest = PROJECT_CACHE.load_json(manifest_path, default={})
        except Exception:
            manifest = {}
        if not isinstance(manifest, dict):
            return True

        source = manifest.get("source") if isinstance(manifest.get("source"), dict) else {}
        current = self._current_extract_source_payload()
        for key in ("xml_path", "images_dir", "annotation_run_dir"):
            saved_value = str(source.get(key) or "").strip()
            current_value = str(current.get(key) or "").strip()
            if not saved_value or not current_value:
                continue
            if not self._paths_equivalent(saved_value, current_value):
                return False
        return True

    def _write_extract_source_manifest(self, run_dir: Path, *, plate_count: int) -> None:
        try:
            payload = {
                "kind": "pz1_plate_extraction",
                "status": "completed",
                "plate_count": int(plate_count or 0),
                "source": self._current_extract_source_payload(),
            }
            self._atomic_write_json(Path(run_dir) / "extract_manifest.json", payload)
        except Exception as exc:
            logger.debug(f"Nie udało się zapisać manifestu wycinania PZ1: {exc}")

    def _is_extract_preview_ready(self, preview_dir=None) -> bool:
        preview_dir_raw = str(
            preview_dir
            if preview_dir is not None
            else (self.preview_dir_var.get() if hasattr(self, "preview_dir_var") else "")
            or ""
        ).strip()
        if not preview_dir_raw:
            return False
        try:
            return bool(
                self._is_usable_step3_preview_dir(preview_dir_raw, require_plates=True)
                and self._preview_matches_current_extract_source(preview_dir_raw)
            )
        except Exception:
            return False

    def _get_extract_preview_ready_count(self, preview_dir=None) -> int:
        preview_dir_raw = str(
            preview_dir
            if preview_dir is not None
            else (self.preview_dir_var.get() if hasattr(self, "preview_dir_var") else "")
            or ""
        ).strip()
        if not preview_dir_raw:
            return 0
        try:
            return int(self._get_preview_dir_plate_count(preview_dir_raw) or 0)
        except Exception:
            return 0

    def _refresh_extract_action_state(self) -> None:
        btn = getattr(self, "btn_extract", None)
        if btn is None:
            return

        source_ready = bool(getattr(self, "_extract_last_source_binding_result", {}).get("ok"))
        preview_ready = self._is_extract_preview_ready()
        if bool(getattr(self, "is_processing", False)):
            text = "Wycinanie w toku"
            state = tk.DISABLED
        elif preview_ready:
            text = "Tablice wycięte"
            state = tk.DISABLED
        else:
            text = "Wytnij tablice do PZ2"
            state = tk.NORMAL if source_ready else tk.DISABLED

        try:
            btn.config(text=text, state=state)
        except Exception:
            pass
        try:
            self._refresh_extract_continue_action_visibility()
        except Exception:
            pass

    def _refresh_extract_continue_action_visibility(self) -> None:
        route = self._get_extract_entry_mode() if hasattr(self, "_get_extract_entry_mode") else ""
        continue_mode = bool(route == "continue")

        cancel_btn = getattr(self, "btn_cancel_continue_extract", None)
        if cancel_btn is not None:
            try:
                if continue_mode:
                    if not str(cancel_btn.winfo_manager()):
                        cancel_btn.pack(side=tk.LEFT, padx=(8, 0))
                elif str(cancel_btn.winfo_manager()):
                    cancel_btn.pack_forget()
            except Exception:
                pass

        stop_btn = getattr(self, "btn_ext_stop", None)
        if stop_btn is not None:
            try:
                if continue_mode:
                    if str(stop_btn.winfo_manager()):
                        stop_btn.pack_forget()
                elif not str(stop_btn.winfo_manager()):
                    stop_btn.pack(side=tk.LEFT, padx=(8, 0))
            except Exception:
                pass

    def _cancel_continue_extract_flow(self):
        try:
            reset_extract_source_inputs(self)
        except Exception:
            pass
        try:
            self.extract_entry_mode_var.set("")
        except Exception:
            pass
        self._extract_workflow_step = "entry"
        try:
            self._persist_step3_extract_state()
        except Exception:
            pass
        self._refresh_extract_workflow_ui()

    def _refresh_extract_start_summary(self):
        if not hasattr(self, "extract_start_xml_value_lbl"):
            return

        xml_path = self._format_extract_start_path(
            self.xml_path_var.get() if hasattr(self, "xml_path_var") else "",
            "Najpierw potwierdź annotations.xml",
        )
        images_dir = self._format_extract_start_path(
            self.images_dir_var.get() if hasattr(self, "images_dir_var") else "",
            "Najpierw potwierdź folder obrazów",
        )
        preview_ready = self._is_extract_preview_ready()
        try:
            output_root = self._get_step3_chars_root_dir(ensure_exists=False)
            preview_value = self._format_extract_start_path(str(self.preview_dir_var.get() or ""), "")
            if preview_value and preview_ready:
                output_text = f"Preview: {preview_value}"
            elif preview_value:
                output_text = f"Nowy run w {self._format_extract_start_path(str(output_root), 'katalogu PZ1')}"
            else:
                output_text = f"Nowy run w {self._format_extract_start_path(str(output_root), 'katalogu PZ1')}"
        except Exception:
            output_text = "Nowy run cropów tablic"

        cut_plan = self._format_extract_cut_plan()
        plates_text = cut_plan.replace("Plan wycinania: ", "", 1) if cut_plan else "Najpierw potwierdź źródła"
        source_ready = bool(getattr(self, "_extract_last_source_binding_result", {}).get("ok"))
        ready_count = self._get_extract_preview_ready_count()
        if preview_ready:
            badge_text = "PZ2 GOTOWE"
            action_note = (
                f"Wycinanie zostało już wykonane poprawnie. Aktywna paczka PZ2 zawiera {ready_count} tablic. "
                "Przejdź do PZ2 albo zmień źródła, jeśli chcesz świadomie przygotować inną paczkę."
            )
        else:
            badge_text = "ŹRÓDŁA OK" if source_ready else "SPRAWDŹ ŹRÓDŁA"
            action_note = (
                "PZ1 wytnie cropy tablic z potwierdzonych ramek/polygonów i przygotuje paczkę do PZ2."
                if source_ready
                else "Wróć do źródeł i potwierdź zgodność XML z katalogiem obrazów, zanim uruchomisz wycinanie."
            )

        route = self._get_extract_entry_mode() if hasattr(self, "_get_extract_entry_mode") else ""
        if route == "continue":
            if preview_ready:
                action_note = "Paczka PZ2 jest już gotowa dla tego runu. Dalsza praca odbywa się w PZ2."
            elif source_ready:
                action_note = "Jeśli tabela pokazuje właściwy run, uruchom akcję. Jeśli nie, wybierz „Zrezygnuj i wróć”."
            else:
                action_note = (
                    "Nie udało się przejąć kompletnego źródła z Z2. Wróć do wyboru i użyj trybu ręcznego, "
                    "jeśli chcesz wskazać annotations.xml oraz katalog obrazów samodzielnie."
                )
            rows = self._build_continue_extract_summary_rows(output_text)
            self._set_extract_start_summary_rows(rows)
            title_text = "Wytnij tablice z przejętego runu Z2"
            desc_text = (
                "Poniżej widzisz źródło przejęte z Z2. To ono zostanie użyte w tej operacji."
            )
        else:
            self._set_extract_start_summary_rows(
                [
                    ("XML", xml_path),
                    ("Obrazy", images_dir),
                    ("Tablice", plates_text),
                    ("Wynik", output_text),
                ]
            )
            title_text = "Gotowe do przygotowania paczki tablic"
            desc_text = (
                "Ten krok tworzy preview run: cropy tablic wycięte z obrazów na podstawie potwierdzonego XML. "
                "To wejście dla PZ2."
            )

        for name, text in (
            ("extract_start_ready_badge_lbl", badge_text),
            ("extract_start_action_note_lbl", action_note),
            ("extract_start_action_title_lbl", title_text),
            ("extract_start_action_desc_lbl", desc_text),
        ):
            label = getattr(self, name, None)
            if label is None:
                continue
            try:
                label.configure(text=text)
            except Exception:
                pass

        self._refresh_extract_continue_action_visibility()
        self._refresh_extract_start_card_style()
        self._refresh_extract_action_state()

    def _show_campaign_detect_splash(
        self,
        *,
        title: str,
        body: str = "",
        tone: str = "info",
        progress: float | None = None,
        show_progress: bool = True,
        show_return: bool = False,
    ):
        overlay = getattr(self, "campaign_detect_splash_overlay", None)
        title_lbl = getattr(self, "campaign_detect_splash_title_lbl", None)
        body_lbl = getattr(self, "campaign_detect_splash_body_lbl", None)
        progressbar = getattr(self, "campaign_detect_splash_progress", None)
        return_btn = getattr(self, "campaign_detect_splash_return_btn", None)
        card = getattr(self, "campaign_detect_splash_card", None)
        host = getattr(self, "detect_content_frame", None)
        if overlay is None or title_lbl is None or body_lbl is None or progressbar is None or card is None or host is None:
            return

        palette = getattr(self.app, "palette", {})
        panel_bg = palette.get("panel", "#252526")
        fg = palette.get("fg", "#f3f3f3")
        muted = palette.get("muted", "#c7c7c7")
        tone_key = str(tone or "info").strip().lower()
        if tone_key == "error":
            accent = palette.get("error", "#e74c3c")
        elif tone_key == "success":
            accent = palette.get("success", "#2ecc71")
        else:
            accent = palette.get("accent", "#4f8de3")

        overlay_bg = blend_hex_colors(panel_bg, "#000000", 0.24)
        card_bg = blend_hex_colors(panel_bg, accent, 0.10)
        border_color = blend_hex_colors(accent, palette.get("panel_border", palette.get("border", "#3c3c3c")), 0.48)

        try:
            overlay.configure(bg=overlay_bg, highlightbackground=overlay_bg, highlightcolor=overlay_bg)
        except Exception:
            pass
        try:
            card.configure(bg=card_bg, highlightbackground=border_color, highlightcolor=border_color)
        except Exception:
            pass
        try:
            title_lbl.configure(text=str(title or "").strip(), bg=card_bg, fg=accent)
        except Exception:
            pass
        try:
            body_lbl.configure(text=str(body or "").strip(), bg=card_bg, fg=fg)
        except Exception:
            pass
        try:
            if hasattr(self.app, "ensure_adaptive_wrap"):
                self.app.ensure_adaptive_wrap(body_lbl, container=card, padding=44, min_wrap=240)
        except Exception:
            pass

        try:
            if show_progress:
                if progress is not None:
                    progressbar.configure(mode="determinate", maximum=100.0, value=max(0.0, min(100.0, float(progress))))
                    self._campaign_detect_splash_progress_value = max(0.0, min(100.0, float(progress)))
                if not str(progressbar.winfo_manager()):
                    progressbar.grid(row=2, column=0, sticky="ew", pady=(14, 0))
            elif str(progressbar.winfo_manager()):
                progressbar.grid_remove()
        except Exception:
            pass

        try:
            if return_btn is not None:
                if show_return:
                    if not str(return_btn.winfo_manager()):
                        return_btn.grid(row=3, column=0, sticky="w", pady=(14, 0))
                elif str(return_btn.winfo_manager()):
                    return_btn.grid_remove()
        except Exception:
            pass

        try:
            overlay.place(in_=host, relx=0.0, rely=0.0, relwidth=1.0, relheight=1.0)
            overlay.lift()
        except Exception:
            pass

        self._campaign_detect_splash_visible = True
        self._campaign_detect_splash_title_text = str(title or "").strip()
        try:
            self._refresh_campaign_step3_navigation_visibility()
        except Exception:
            pass

    def _hide_campaign_detect_splash(self):
        overlay = getattr(self, "campaign_detect_splash_overlay", None)
        if overlay is None:
            return
        try:
            overlay.place_forget()
        except Exception:
            pass
        self._campaign_detect_splash_visible = False
        self._campaign_detect_splash_title_text = ""
        try:
            self._refresh_campaign_step3_navigation_visibility()
        except Exception:
            pass

    def _set_source_binding_status(self, text: str, tone: str = "warning"):
        frame = getattr(self, "source_binding_status_frame", None)
        title_label = getattr(self, "source_binding_status_title_lbl", None)
        label = getattr(self, "source_binding_status_lbl", None)
        if frame is None or label is None:
            return

        has_text = bool(str(text or "").strip())
        tone_key = str(tone or "").strip().lower()
        palette = getattr(self.app, "palette", {})
        base_bg = palette.get("panel_alt", palette.get("panel", "#252526"))
        default_fg = palette.get("fg", "#f3f3f3")
        self._source_binding_status_tone = tone_key

        if tone_key == "error":
            border_color = palette.get("error", "#e74c3c")
            frame_bg = blend_hex_colors(border_color, base_bg, 0.84)
            title_fg = border_color
            text_fg = default_fg
        else:
            border_color = palette.get("success", "#2ecc71")
            frame_bg = palette.get("surface_success", blend_hex_colors(border_color, base_bg, 0.84))
            title_fg = border_color
            text_fg = default_fg

        try:
            if has_text:
                if not str(frame.winfo_manager()):
                    frame.pack(fill=tk.X, pady=(0, 10))
            else:
                if str(frame.winfo_manager()):
                    frame.pack_forget()
        except Exception:
            pass

        try:
            frame.configure(bg=frame_bg, highlightbackground=border_color, highlightcolor=border_color)
        except Exception:
            pass
        try:
            if title_label is not None:
                title_label.configure(bg=frame_bg, fg=title_fg)
        except Exception:
            pass
        try:
            label.configure(
                text=text,
                bg=frame_bg,
                fg=text_fg,
                font=("Segoe UI", 9),
            )
        except Exception:
            if not self._set_inline_status_label_state(label, text=text, tone=tone, emphasis=False):
                self._set_themed_label_state(label, text=text, tone=tone, emphasis=False)

    def _set_test_status(self, text: str, tone: str = "neutral"):
        label = getattr(self, "test_status_lbl", None)
        fixed_tone = "neutral"
        if not self._set_inline_status_label_state(label, text=text, tone=fixed_tone, emphasis=False):
            self._set_themed_label_state(label, text=text, tone=fixed_tone, emphasis=False)

    def _get_detection_method_status_label(self) -> str:
        method_key = str(self._get_detection_method_key() or "OCR").strip().upper()
        if method_key == "YOLO":
            return "YOLO"
        if method_key == "BOTH":
            return "Hybryda OCR+YOLO"
        if method_key == "YOLO_OCR":
            return "YOLO boxy + OCR"
        return "OCR"

    def _compose_detection_method_status(self, detail: str | None = None) -> str:
        base = f"Tryb pracy: {self._get_detection_method_status_label()}"
        detail_text = str(detail or "").strip()
        if not detail_text:
            return base
        return f"{base} | {detail_text}"

    def _set_test_progress_counter(
        self,
        current: int | None = None,
        total: int | None = None,
        perfect_count: int | None = None,
    ):
        label = getattr(self, "test_progress_count_lbl", None)
        if label is None:
            return

        if current is None or total is None or total <= 0:
            self._set_test_progress_detail("")
            return
        current = max(0, min(int(current), int(total)))
        perfect_value = max(0, min(int(perfect_count or 0), current))
        text = f"OK {perfect_value} | {current}/{int(total)}"
        tone = "muted" if current < int(total) else "success"

        if not self._set_inline_status_label_state(label, text=text, tone=tone, emphasis=True):
            self._set_themed_label_state(label, text=text, tone=tone, emphasis=True)

    def _set_test_progress_detail(
        self,
        text: str | None = None,
        tone: str = "muted",
        emphasis: bool = True,
    ):
        label = getattr(self, "test_progress_count_lbl", None)
        if label is None:
            return

        detail_text = str(text or "").strip()
        if not self._set_inline_status_label_state(label, text=detail_text, tone=tone, emphasis=emphasis):
            self._set_themed_label_state(label, text=detail_text, tone=tone, emphasis=emphasis)

    def _set_test_ranking_progress_detail(
        self,
        processed_presets: int,
        total_presets: int,
        sample_count: int = 0,
        demo_mode: bool = False,
        finished: bool = False,
    ):
        total_value = max(0, int(total_presets or 0))
        processed_value = max(0, min(int(processed_presets or 0), total_value if total_value > 0 else int(processed_presets or 0)))
        sample_value = max(0, int(sample_count or 0))

        if total_value <= 0 and sample_value <= 0:
            self._set_test_progress_detail("")
            return

        sample_text = f"Demo: {sample_value} próbki" if demo_mode else f"Próbki: {sample_value}"
        if total_value > 0:
            detail_text = f"{sample_text} | Presety {processed_value}/{total_value}"
        else:
            detail_text = sample_text

        detail_tone = "success" if finished or (total_value > 0 and processed_value >= total_value) else "muted"
        self._set_test_progress_detail(detail_text, tone=detail_tone, emphasis=True)

    def _update_detection_progress_ui(self, current: int, total: int, perfect_count: int = 0, session_token=None):
        if session_token is not None and session_token != self._project_reset_token:
            return

        pct = ((max(0, int(current)) / max(1, int(total))) * 100.0) if total else 0.0

        try:
            self.test_progress.config(value=pct)
        except Exception:
            pass

        self._set_test_progress_counter(current, total, perfect_count=perfect_count)
        self._set_test_status(self._compose_detection_method_status("detekcja w toku"), "warning")

