    def _allocate_split_counts(self, total_entries: int, ratios: dict[str, float] | None = None) -> dict[str, int]:
        ordered_ratios = list((ratios or {}).items())
        if not ordered_ratios:
            ordered_ratios = [("train", 1.0), ("val", 0.0), ("test", 0.0)]

        total_entries = max(0, int(total_entries or 0))
        normalized_ratios: list[tuple[str, float]] = []
        ratio_sum = 0.0
        for split_name, raw_ratio in ordered_ratios:
            ratio_value = max(0.0, float(raw_ratio or 0.0))
            normalized_ratios.append((str(split_name), ratio_value))
            ratio_sum += ratio_value

        if ratio_sum <= 0.0:
            normalized_ratios = [(name, 1.0 if idx == 0 else 0.0) for idx, (name, _value) in enumerate(normalized_ratios)]
            ratio_sum = 1.0

        counts = {name: 0 for name, _value in normalized_ratios}
        if total_entries <= 0:
            return counts

        weighted_rows: list[tuple[str, int, float, int]] = []
        assigned = 0
        for idx, (split_name, ratio_value) in enumerate(normalized_ratios):
            raw_target = float(total_entries) * (ratio_value / ratio_sum)
            base_count = int(raw_target)
            fractional = raw_target - float(base_count)
            counts[split_name] = base_count
            assigned += base_count
            weighted_rows.append((split_name, idx, fractional, ratio_value))

        remaining = max(0, total_entries - assigned)
        if remaining > 0:
            weighted_rows.sort(
                key=lambda item: (
                    item[2],   # większa reszta ułamkowa
                    item[3],   # przy remisie wyższy docelowy udział
                    -item[1],  # stabilny fallback zgodny z kolejnością splitów
                ),
                reverse=True,
            )
            row_count = len(weighted_rows)
            for offset in range(remaining):
                split_name = weighted_rows[offset % row_count][0]
                counts[split_name] = int(counts.get(split_name, 0) or 0) + 1

        return {key: max(0, int(value or 0)) for key, value in counts.items()}

    def _build_split_entries(self, entries: list, ratios: dict[str, float], shuffle_seed: int = 42) -> tuple[dict[str, list], dict[str, int]]:
        ratios = dict(ratios or {})
        split_names = list(ratios.keys()) or ["train", "val", "test"]
        working_entries = list(entries or [])
        random.Random(int(shuffle_seed)).shuffle(working_entries)

        counts = self._allocate_split_counts(len(working_entries), ratios)
        split_entries = {name: [] for name in split_names}

        start_idx = 0
        for split_name in split_names:
            take_count = max(0, int(counts.get(split_name, 0) or 0))
            split_entries[split_name] = working_entries[start_idx:start_idx + take_count]
            start_idx += take_count

        return split_entries, {name: int(len(split_entries.get(name, [])) or 0) for name in split_names}

    def _get_preview_repair_progress_snapshot(self, counts: dict | None = None) -> dict:
        counts = dict(counts or self._count_preview_statuses() or {})
        perfect = max(0, int(counts.get("perfect", 0) or 0))
        needs_fix = max(0, int(counts.get("needs_fix", 0) or 0))
        unknown = max(0, int(counts.get("unknown", 0) or 0))
        total = max(0, int(counts.get("total", 0) or 0))
        progress_value = (float(perfect) / float(total) * 100.0) if total > 0 else 0.0

        train_count = 0
        val_count = 0
        test_count = 0
        train_pct = 0.0
        val_pct = 0.0
        test_pct = 0.0
        split_ready = bool(perfect > 0)
        min_required_perfect = 1
        missing_for_split = max(0, int(min_required_perfect) - int(perfect or 0))

        if total <= 0:
            tone = "muted"
            summary = "Cel datasetu: czekam na paczkę tablic."
            details = "Wczytaj paczkę i zacznij poprawiać znaki, aby ocenić gotowość datasetu."
        elif not split_ready:
            tone = "error"
            summary = f"Gotowe perfect: {perfect}/{total} tablic."
            details = (
                "Brakuje jeszcze co najmniej jednej tablicy perfect do utworzenia źródłowego datasetu znaków. "
                "Split i wariant treningowy przygotujesz później w Z4."
            )
        else:
            ready_target = (
                "Paczka jest gotowa do E4."
                if getattr(self, "_step3_linear_mode", False) and CAMPAIGN.get_active_project_name()
                else "Paczka jest gotowa do eksportu źródłowego datasetu."
            )
            ratio = (float(perfect) / float(total)) if total > 0 else 0.0
            if ratio < 0.6:
                tone = "warning"
                details = (
                    "Możesz już utworzyć źródłowy dataset znaków, ale warto oznaczyć perfect "
                    "na większej liczbie tablic przed przejściem do Z4."
                )
            else:
                tone = "success"
                details = (
                    f"{ready_target} Wariant treningowy i split train / val / test przygotujesz w Z4."
                )
            summary = f"Gotowe perfect: {perfect}/{total} tablic."

        return {
            "perfect": perfect,
            "needs_fix": needs_fix,
            "unknown": unknown,
            "total": total,
            "progress_value": max(0.0, min(100.0, progress_value)),
            "tone": tone,
            "summary": summary,
            "details": details,
            "train_count": train_count,
            "val_count": val_count,
            "test_count": test_count,
            "train_pct": float(train_pct),
            "val_pct": float(val_pct),
            "test_pct": float(test_pct),
            "split_ready": split_ready,
            "min_required_perfect": int(min_required_perfect),
            "missing_for_split": int(missing_for_split),
        }

    def _update_preview_repair_progress_ui(self, counts: dict | None = None):
        snapshot = self._get_preview_repair_progress_snapshot(counts)
        palette = getattr(self.app, "palette", {})
        panel_bg = palette.get("panel", "#252526")
        trough = palette.get("border", "#4b4b4b")
        tone = str(snapshot.get("tone", "muted") or "muted").strip().lower()

        fill_map = {
            "success": palette.get("success", "#2ecc71"),
            "warning": palette.get("warning", "#f0b44c"),
            "error": palette.get("error", "#e74c3c"),
            "info": palette.get("info", palette.get("accent", "#4aa3ff")),
            "muted": palette.get("muted", "#9aa0a6"),
            "neutral": palette.get("accent", "#4aa3ff"),
        }
        fill = fill_map.get(tone, palette.get("accent", "#4aa3ff"))

        title = getattr(self, "preview_repair_progress_title_lbl", None)
        if title is not None:
            try:
                title.configure(
                    text=str(snapshot.get("summary") or "Postęp poprawek"),
                    bg=panel_bg,
                    fg=palette.get("fg", "#f3f3f3"),
                )
            except Exception:
                pass

        progress = getattr(self, "preview_repair_progress", None)
        if isinstance(progress, SlimProgressBar):
            try:
                progress.configure(
                    maximum=100.0,
                    value=float(snapshot.get("progress_value", 0.0) or 0.0),
                    bg=panel_bg,
                    background=panel_bg,
                    trough_color=trough,
                    fill_color=fill,
                )
            except Exception:
                pass

        detail = str(snapshot.get("details") or "").strip()
        self._set_preview_repair_progress_status(detail, tone=tone)

