    def _get_campaign_char_model_path(self) -> str:
        """
        Zwraca ścieżkę do modelu znaków przypiętego do aktywnego projektu.
        """
        try:
            model_path = CAMPAIGN.get_global_model("char")
            if model_path and Path(model_path).exists():
                return str(Path(model_path))
        except Exception:
            pass
        return ""


    def _get_effective_yolo_model_path(self) -> str:
        """
        Zwraca rzeczywistą ścieżkę modelu YOLO używaną do detekcji.
        W trybie kampanii źródłem prawdy jest projekt, nie local session.
        """
        if getattr(self, "_step3_linear_mode", False):
            return self._get_campaign_char_model_path()

        raw = (self.yolo_model_path_var.get() or "").strip()
        if raw and raw != "Brak modelu znaków w projekcie" and Path(raw).exists():
            return raw
        return ""


    def _sync_yolo_model_binding(self):
        """
        Ustawia zawartość pola ścieżki modelu YOLO zgodnie z aktualnym trybem.
        """
        if getattr(self, "_step3_linear_mode", False):
            project_model = self._get_campaign_char_model_path()
            if project_model:
                self.yolo_model_path_var.set(project_model)
            else:
                self.yolo_model_path_var.set("Brak modelu znaków w projekcie")
        else:
            if (self.yolo_model_path_var.get() or "").strip() == "Brak modelu znaków w projekcie":
                self.yolo_model_path_var.set("")

    def _infer_yolo_arch_from_model_path(self, model_path: str):
        """
        Próbuje odczytać wydanie i rozmiar YOLO z nazwy pliku, np.:
        - yolo11s.pt
        - best_yolo26m.pt
        - chars_yolo8n_last.pt
        """
        raw = (model_path or "").strip().lower()
        if not raw:
            return None, None

        name = Path(raw).name.lower()

        import re
        match = re.search(r"yolo(8|11|26)([nsmlx])", name)
        if not match:
            return None, None

        version = match.group(1)
        size = match.group(2)
        return version, size
    def _set_widget_state(self, widget, state: str):
        if widget is None:
            return
        try:
            widget.config(state=state)
        except Exception as e:
            logger.debug(f"Nie udało się ustawić stanu widgetu: {e}")

    def _update_step3_source_path_lock(self):
        """
        Źródła w PZ1 maja być kontrolowane swiadomie przez użytkownika.
        Nie blokujemy już recznego wyboru XML/paczki obrazów ani jawnego
        pobierania źródła z Z2. Readonly zostawiamy jedynie pole runu.
        """
        for attr_name in ("xml_path_entry", "images_dir_entry"):
            widget = getattr(self, attr_name, None)
            if widget is None:
                continue
            try:
                widget.config(state="normal")
            except Exception as e:
                logger.debug(f"Nie udało się ustawić stanu {attr_name}: {e}")

        for attr_name in (
            "xml_path_browse_btn",
            "images_dir_browse_btn",
            "annotation_run_browse_btn",
            "extract_use_z2_source_btn",
        ):
            widget = getattr(self, attr_name, None)
            if widget is None:
                continue
            try:
                widget.config(state="normal")
            except Exception as e:
                logger.debug(f"Nie udało się ustawić stanu {attr_name}: {e}")

        annotation_run_entry = getattr(self, "annotation_run_dir_entry", None)
        if annotation_run_entry is not None:
            try:
                annotation_run_entry.config(state="readonly")
            except Exception as e:
                logger.debug(f"Nie udało się ustawić stanu annotation_run_dir_entry: {e}")

    def _bind_source_path_watchers(self):
        if getattr(self, "_source_binding_watchers_bound", False):
            return

        self._source_binding_watchers_bound = True
        for var in (self.xml_path_var, self.images_dir_var):
            try:
                var.trace_add("write", self._on_source_path_var_changed)
            except Exception as e:
                logger.debug(f"Nie udało się podpiąć watcherów źródeł Z3/PZ1: {e}")

    def _on_source_path_var_changed(self, *_args):
        if getattr(self, "_source_binding_sync_in_progress", False):
            return
        self._schedule_source_binding_refresh()

    def _schedule_source_binding_refresh(self, delay_ms: int = 150):
        if not hasattr(self, "frame") or self.frame is None:
            return

        pending = getattr(self, "_source_binding_after_id", None)
        if pending:
            try:
                self.frame.after_cancel(pending)
            except Exception:
                pass

        self._source_binding_after_id = self.frame.after(delay_ms, self._refresh_source_binding_status)

    def _normalize_xml_image_relpath(self, raw_name: str) -> str:
        raw = str(raw_name or "").strip().replace("\\", "/")
        while raw.startswith("./"):
            raw = raw[2:]

        parts = [part for part in PurePosixPath(raw).parts if part not in ("", ".")]
        return "/".join(parts)

    def _xml_relpath_to_path(self, rel_path: str) -> Path:
        parts = [part for part in PurePosixPath(rel_path).parts if part not in ("", ".")]
        return Path(*parts) if parts else Path()

    def _read_xml_image_names(self, xml_path: Path) -> list[str]:
        tree = ET.parse(xml_path)
        names = []

        for image_el in tree.getroot().findall(".//image"):
            normalized = self._normalize_xml_image_relpath(image_el.get("name") or "")
            if normalized:
                names.append(normalized)

        return list(dict.fromkeys(names))

    def _count_xml_plate_cut_targets(self, xml_path: Path) -> dict:
        tree = ET.parse(xml_path)
        image_elements = {
            str(image_el.get("name") or ""): image_el
            for image_el in tree.getroot().findall(".//image")
            if str(image_el.get("name") or "").strip()
        }
        plate_count = 0
        images_with_plates = 0

        for image_el in image_elements.values():
            image_plate_count = 0
            for poly in image_el.findall(".//polygon[@label='plate']"):
                try:
                    points = [
                        tuple(map(float, raw_point.split(",")))
                        for raw_point in str(poly.get("points") or "").split(";")
                        if raw_point.strip()
                    ]
                except Exception:
                    continue
                if len(points) >= 4:
                    image_plate_count += 1

            if image_plate_count > 0:
                images_with_plates += 1
                plate_count += image_plate_count

        return {
            "plate_count": int(plate_count),
            "images_with_plates": int(images_with_plates),
            "xml_images_total": int(len(image_elements)),
        }

    def _format_extract_cut_plan(self, payload: dict | None = None) -> str:
        data = dict(payload or getattr(self, "_extract_last_source_binding_result", {}) or {})
        xml_images_total = int(data.get("xml_images_total") or data.get("total") or 0)
        if xml_images_total <= 0 and not data.get("plate_count"):
            return ""

        plate_count = int(data.get("plate_count") or 0)
        images_with_plates = int(data.get("images_with_plates") or 0)
        if plate_count <= 0:
            return (
                f"Plan wycinania: 0 tablic. XML obejmuje {xml_images_total} obrazów, "
                "ale nie zawiera poprawnych polygonów plate do wycięcia."
            )
        return (
            f"Plan wycinania: {plate_count} cropów tablic z {images_with_plates} obrazów. "
            f"XML obejmuje łącznie {xml_images_total} obrazów."
        )

    def _append_extract_cut_plan(self, message: str, payload: dict | None = None) -> str:
        plan = self._format_extract_cut_plan(payload)
        if not plan:
            return str(message or "")
        base = str(message or "").strip()
        if plan in base:
            return base
        return f"{base}\n\n{plan}" if base else plan

    def _evaluate_images_dir_for_xml(self, images_dir: Path, xml_image_names: list[str]) -> dict:
        matched = 0
        missing = []

        for rel_name in xml_image_names:
            candidate = images_dir / self._xml_relpath_to_path(rel_name)
            if candidate.exists() and candidate.is_file():
                matched += 1
            else:
                missing.append(rel_name)

        return {
            "images_dir": images_dir,
            "total": len(xml_image_names),
            "matched": matched,
            "missing_count": len(missing),
            "missing": missing,
        }

    def _summarize_missing_xml_images(self, missing: list[str], limit: int = 3) -> str:
        if not missing:
            return ""

        preview = ", ".join(missing[:limit])
        if len(missing) > limit:
            preview += ", ..."
        return f"Brakuje {len(missing)} plików z XML, np. {preview}."

    def _is_path_within(self, path: Path, root: Path) -> bool:
        try:
            path.resolve().relative_to(root.resolve())
            return True
        except Exception:
            return False

    def _get_preferred_source_roots(self) -> list[Path]:
        roots = []

        try:
            campaign_raw = CAMPAIGN.get_dir("raw")
            if campaign_raw:
                roots.append(Path(campaign_raw))
        except Exception:
            pass

        try:
            roots.append(Path(CONFIG.DIR_1_RAW))
        except Exception:
            pass

        unique = []
        seen = set()
        for root in roots:
            try:
                resolved = str(root.resolve())
            except Exception:
                resolved = str(root)
            if resolved in seen:
                continue
            seen.add(resolved)
            if root.exists() and root.is_dir():
                unique.append(root)

        return unique

    def _is_recommended_images_dir(self, images_dir: Path) -> bool:
        for root in self._get_preferred_source_roots():
            if self._is_path_within(images_dir, root):
                return True
        return False

    def _derive_candidate_root_for_match(self, found_file: Path, xml_rel_name: str) -> Path | None:
        parts = [part for part in PurePosixPath(xml_rel_name).parts if part not in ("", ".")]
        if not parts:
            return None

        ascend_levels = len(parts) - 1
        parents = found_file.parents
        if ascend_levels >= len(parents):
            return None

        candidate_root = parents[ascend_levels]
        try:
            candidate_target = (candidate_root / self._xml_relpath_to_path(xml_rel_name)).resolve()
            if candidate_target != found_file.resolve():
                return None
        except Exception:
            return None

        return candidate_root

    def _find_matching_images_dir_for_xml(self, xml_image_names: list[str]) -> dict | None:
        if not xml_image_names:
            return None

        search_roots = self._get_preferred_source_roots()
        if not search_roots:
            return None

        sample_names = xml_image_names[: min(24, len(xml_image_names))]
        sample_by_basename = {}
        for rel_name in sample_names:
            sample_by_basename.setdefault(PurePosixPath(rel_name).name, []).append(rel_name)

        candidate_hits = {}

        for search_root in search_roots:
            try:
                for file_path in search_root.rglob("*"):
                    if not file_path.is_file():
                        continue

                    candidate_rel_names = sample_by_basename.get(file_path.name)
                    if not candidate_rel_names:
                        continue

                    for rel_name in candidate_rel_names:
                        candidate_root = self._derive_candidate_root_for_match(file_path, rel_name)
                        if candidate_root is None:
                            continue

                        try:
                            key = str(candidate_root.resolve())
                        except Exception:
                            key = str(candidate_root)

                        entry = candidate_hits.setdefault(
                            key,
                            {
                                "images_dir": candidate_root,
                                "sample_hits": set(),
                            },
                        )
                        entry["sample_hits"].add(rel_name)
            except Exception as e:
                logger.debug(f"Nie udało się przeskanować {search_root} podczas auto-odnajdywania paczki obrazów: {e}")

        if not candidate_hits:
            return None

        ranked_candidates = sorted(
            candidate_hits.values(),
            key=lambda item: (len(item["sample_hits"]), -len(str(item["images_dir"]))),
            reverse=True,
        )

        best_match = None
        best_score = None

        for candidate in ranked_candidates[:8]:
            stats = self._evaluate_images_dir_for_xml(candidate["images_dir"], xml_image_names)
            stats["sample_hits"] = len(candidate["sample_hits"])
            score = (stats["matched"], -stats["missing_count"], stats["sample_hits"])

            if best_match is None or score > best_score:
                best_match = stats
                best_score = score

        return best_match

    def _refresh_source_binding_status(self, allow_autofind: bool = True) -> dict:
        self._source_binding_after_id = None

        def _finish(payload: dict) -> dict:
            self._extract_last_source_binding_result = dict(payload or {})
            try:
                self._refresh_extract_workflow_ui()
            except Exception:
                pass
            return payload

        xml_raw = (self.xml_path_var.get() or "").strip()
        images_raw = (self.images_dir_var.get() or "").strip()
        base_note = "Plik annotations.xml i katalog obrazów są nierozerwalnie powiązane."

        result = {
            "ok": False,
            "tone": "warning",
            "message": "",
            "matched": 0,
            "total": 0,
            "missing_count": 0,
            "plate_count": 0,
            "images_with_plates": 0,
            "xml_images_total": 0,
        }

        if not xml_raw:
            result["message"] = (
                f"{base_note} Wskaż annotations.xml, a system spróbuje odnaleźć właściwy katalog w "
                "Workspace/1_raw_images/."
            )
            self._set_source_binding_status(result["message"], result["tone"])
            return _finish(result)

        xml_path = Path(xml_raw)
        if not xml_path.exists():
            result["tone"] = "error"
            result["message"] = (
                f"Nie znaleziono pliku annotations.xml. {base_note} Wskaż poprawny XML wygenerowany dla tego samego katalogu obrazów."
            )
            self._set_source_binding_status(result["message"], result["tone"])
            return _finish(result)

        try:
            xml_image_names = self._read_xml_image_names(xml_path)
        except Exception as e:
            result["tone"] = "error"
            result["message"] = f"Nie mogę odczytać annotations.xml: {e}"
            self._set_source_binding_status(result["message"], result["tone"])
            return _finish(result)

        if not xml_image_names:
            result["tone"] = "error"
            result["message"] = (
                "Ten plik XML nie zawiera listy obrazów, więc nie da się powiązać go z katalogiem źródłowym."
            )
            self._set_source_binding_status(result["message"], result["tone"])
            return _finish(result)

        try:
            result.update(self._count_xml_plate_cut_targets(xml_path))
        except Exception as e:
            result["tone"] = "error"
            result["message"] = f"Nie mogę policzyć tablic do wycięcia w annotations.xml: {e}"
            self._set_source_binding_status(result["message"], result["tone"])
            return _finish(result)

        if int(result.get("plate_count") or 0) <= 0:
            result["tone"] = "error"
            result["message"] = self._append_extract_cut_plan(
                "XML został odczytany, ale PZ1 nie znalazł w nim poprawnych polygonów tablic. "
                "Wycinanie utworzyłoby pustą paczkę, więc najpierw popraw lub wybierz właściwy annotations.xml.",
                result,
            )
            self._set_source_binding_status(result["message"], result["tone"])
            return _finish(result)

        current_images_dir = Path(images_raw) if images_raw else None
        current_stats = None

        if current_images_dir and current_images_dir.exists() and current_images_dir.is_dir():
            current_stats = self._evaluate_images_dir_for_xml(current_images_dir, xml_image_names)
        elif current_images_dir:
            result["tone"] = "error"
            result["message"] = (
                f"Nie znaleziono wskazanego katalogu obrazów: {current_images_dir}. {base_note}"
            )

        best_candidate = None
        need_autofind = allow_autofind and (
            current_stats is None or current_stats["matched"] < current_stats["total"]
        )

        if need_autofind:
            best_candidate = self._find_matching_images_dir_for_xml(xml_image_names)
            if best_candidate and best_candidate["matched"] == best_candidate["total"]:
                candidate_dir = Path(best_candidate["images_dir"])
                same_as_current = False
                if current_images_dir:
                    try:
                        same_as_current = candidate_dir.resolve() == current_images_dir.resolve()
                    except Exception:
                        same_as_current = candidate_dir == current_images_dir

                if not same_as_current:
                    self._source_binding_sync_in_progress = True
                    try:
                        self.images_dir_var.set(str(candidate_dir))
                    finally:
                        self._source_binding_sync_in_progress = False
                    try:
                        self._force_save_all()
                    except Exception:
                        pass

                current_images_dir = candidate_dir
                current_stats = best_candidate
                result["auto_found"] = True

        if current_stats and current_stats["matched"] == current_stats["total"]:
            recommended = self._is_recommended_images_dir(Path(current_stats["images_dir"]))
            result.update(
                {
                    "ok": True,
                    "tone": "success",
                    "matched": current_stats["matched"],
                    "total": current_stats["total"],
                    "missing_count": 0,
                }
            )

            if result.get("auto_found"):
                result["message"] = (
                    f"Powiązanie potwierdzone. Auto-odnaleziono katalog obrazów: "
                    f"{current_stats['matched']}/{current_stats['total']} plików z XML w "
                    f"{current_stats['images_dir']}."
                )
            elif recommended:
                result["message"] = (
                    f"Powiązanie potwierdzone: {current_stats['matched']}/{current_stats['total']} plików z XML "
                    f"znaleziono w tej paczce obrazów."
                )
            else:
                result["message"] = (
                    f"Powiązanie XML-katalog jest poprawne ({current_stats['matched']}/{current_stats['total']}), "
                    f"ale źródła są poza Workspace/1_raw_images/. To działa w trybie swobodnym, lecz nie jest zalecane."
                )

            result["message"] = self._append_extract_cut_plan(result["message"], result)
            self._set_source_binding_status(result["message"], result["tone"])
            return _finish(result)

        if current_stats:
            missing_hint = self._summarize_missing_xml_images(current_stats["missing"])
            result.update(
                {
                    "matched": current_stats["matched"],
                    "total": current_stats["total"],
                    "missing_count": current_stats["missing_count"],
                    "tone": "error",
                }
            )
            result["message"] = (
                f"Wybrany katalog obrazów nie pasuje do tego XML: znaleziono "
                f"{current_stats['matched']}/{current_stats['total']} wymaganych plików. {missing_hint}"
            ).strip()

            if best_candidate and best_candidate["matched"] > current_stats["matched"]:
                result["message"] += (
                    f" Najlepszy kandydat w Workspace/1_raw_images/ daje "
                    f"{best_candidate['matched']}/{best_candidate['total']} dopasowań."
                )

            result["message"] = self._append_extract_cut_plan(result["message"], result)
            self._set_source_binding_status(result["message"], result["tone"])
            return _finish(result)

        if best_candidate and best_candidate["matched"] > 0:
            result.update(
                {
                    "matched": best_candidate["matched"],
                    "total": best_candidate["total"],
                    "missing_count": best_candidate["missing_count"],
                    "tone": "warning",
                    "message": (
                        f"Nie udało się jednoznacznie potwierdzić katalogu obrazów. Najlepszy kandydat w "
                        f"Workspace/1_raw_images/ zawiera {best_candidate['matched']}/{best_candidate['total']} plików z XML."
                    ),
                }
            )
            result["message"] = self._append_extract_cut_plan(result["message"], result)
        elif not images_raw:
            result["message"] = self._append_extract_cut_plan(
                (
                    f"{base_note} Wskaż katalog obrazów, na których wykonano anotacje. "
                    "Jeśli leży w Workspace/1_raw_images/, system odnajdzie ją automatycznie."
                ),
                result,
            )

        result["message"] = self._append_extract_cut_plan(result["message"], result)
        self._set_source_binding_status(result["message"], result["tone"])
        return _finish(result)

    def _count_preview_statuses(self):
        return self._count_statuses_in_metadata_mapping(self.preview_metadata)

    def _get_step3_chars_root_dir(self, ensure_exists: bool = False) -> Path:
        """
        Zwraca katalog bazowy paczek tablic znakowych dla Z3.
        Po wyjściu z kampanii _campaign_chars_dir może istnieć, ale mieć wartość None,
        wiec zawsze wracamy bezpiecznie do katalogu free mode.
        """
        try:
            in_campaign_context = bool(getattr(self, "_step3_linear_mode", False) and CAMPAIGN.get_active_project_name())
        except Exception:
            in_campaign_context = False

        chars_root = getattr(self, "_campaign_chars_dir", None) if in_campaign_context else None
        if not chars_root and in_campaign_context:
            try:
                campaign_chars_root = CAMPAIGN.get_dir("chars")
                if campaign_chars_root is not None:
                    chars_root = campaign_chars_root
            except Exception:
                chars_root = None
        chars_root = chars_root or CONFIG.DIR_3_CHARS
        root = Path(chars_root).absolute()
        if ensure_exists:
            root.mkdir(parents=True, exist_ok=True)
        return root

    def _get_step3_datasets_root_dir(self, ensure_exists: bool = False) -> Path:
        """
        Zwraca katalog bazowy datasetow znaków dla Z3 z bezpiecznym fallbackiem
        do trybu swobodnego po opuszczeniu projektu.
        """
        try:
            in_campaign_context = bool(getattr(self, "_step3_linear_mode", False) and CAMPAIGN.get_active_project_name())
        except Exception:
            in_campaign_context = False

        datasets_root = getattr(self, "_campaign_datasets_dir", None) if in_campaign_context else None
        if not datasets_root and in_campaign_context:
            try:
                campaign_datasets_root = CAMPAIGN.get_dir("datasets")
                if campaign_datasets_root is not None:
                    datasets_root = campaign_datasets_root
            except Exception:
                datasets_root = None
        datasets_root = datasets_root or CONFIG.get_datasets_dir("char")
        root = Path(datasets_root).absolute()
        if ensure_exists:
            root.mkdir(parents=True, exist_ok=True)
        return root

    def _get_step3_char_classification_datasets_root_dir(self, ensure_exists: bool = False) -> Path:
        """
        Katalog dla datasetow OCR/klasyfikacji znakow.
        Trzymamy go osobno od YOLO Detect, żeby Z4/PZ1/PZ2 nie mieszało wejść treningowych.
        """
        try:
            in_campaign_context = bool(getattr(self, "_step3_linear_mode", False) and CAMPAIGN.get_active_project_name())
        except Exception:
            in_campaign_context = False

        datasets_root = getattr(self, "_campaign_datasets_dir", None) if in_campaign_context else None
        if not datasets_root and in_campaign_context:
            try:
                campaign_datasets_root = CAMPAIGN.get_dir("datasets")
                if campaign_datasets_root is not None:
                    datasets_root = campaign_datasets_root
            except Exception:
                datasets_root = None

        if datasets_root:
            root = Path(datasets_root).absolute() / CONFIG.get_char_classification_datasets_dir().name
        else:
            root = CONFIG.get_char_classification_datasets_dir().absolute()

        if ensure_exists:
            root.mkdir(parents=True, exist_ok=True)
        return root

    def _get_step3_summary_dir(self) -> Path:
        """
        Katalog, w którym zapisujemy podsumowanie kroku 3.
        Priorytet:
        1. aktywny run preview
        2. projektowy chars dir
        3. fallback do DIR_3_CHARS
        """
        preview_dir = Path(self.preview_dir_var.get().strip()) if self.preview_dir_var.get().strip() else None
        if preview_dir and preview_dir.exists():
            return preview_dir

        campaign_chars_dir = getattr(self, "_campaign_chars_dir", None)
        if campaign_chars_dir:
            p = Path(campaign_chars_dir)
            p.mkdir(parents=True, exist_ok=True)
            return p

        fallback = Path(CONFIG.DIR_3_CHARS).absolute()
        fallback.mkdir(parents=True, exist_ok=True)
        return fallback
    
    def _is_valid_step3_training_dataset_dir(self, dataset_dir: Path | None) -> bool:
        """
        Sprawdza, czy katalog wygląda jak realny dataset treningowy znaków
        gotowy do użycia w etapie 4.
        """
        if dataset_dir is None:
            return False

        try:
            if not dataset_dir.exists() or not dataset_dir.is_dir():
                return False

            data_yaml = dataset_dir / "data.yaml"
            images_dir = dataset_dir / "images"
            labels_dir = dataset_dir / "labels"

            if not data_yaml.exists():
                return False

            if not images_dir.exists() or not images_dir.is_dir():
                return False

            if not labels_dir.exists() or not labels_dir.is_dir():
                return False

            return True
        except Exception:
            return False

    def _get_preferred_step3_training_dataset_dir(self) -> Path | None:
        """
        Zwraca najlepszy dostępny dataset znaków dla finału kroku 3.

        Priorytet:
        1. char_merged_pool
        2. najnowszy poprawny dataset z katalogu projektowych datasetów
        """
        merged_dir = self._get_char_merged_pool_dir()
        if self._is_valid_step3_training_dataset_dir(merged_dir):
            return merged_dir

        campaign_datasets_dir = getattr(self, "_campaign_datasets_dir", None)
        if not campaign_datasets_dir:
            return None

        ds_root = Path(campaign_datasets_dir)
        if not ds_root.exists() or not ds_root.is_dir():
            return None

        try:
            candidates = [
                p for p in ds_root.iterdir()
                if p.is_dir() and self._is_valid_step3_training_dataset_dir(p)
            ]
            if not candidates:
                return None

            candidates.sort(key=lambda p: p.stat().st_mtime, reverse=True)
            return candidates[0]
        except Exception:
            return None


    def _build_step3_export_summary(
        self,
        gold_dataset_path: str | None = None,
        review_pack_path: str | None = None,
        retry_pack_path: str | None = None,
        note: str = ""
    ):
        counts = self._count_preview_statuses()
        exportable_char_count = int(
            sum(int(v or 0) for v in dict(counts.get("strategy_char_counts", {}) or {}).values())
        )
        exportable_plate_count = self._count_exportable_perfect_plates_in_metadata(self.preview_metadata)

        gold_exists = bool(gold_dataset_path and Path(gold_dataset_path).exists())
        review_exists = bool(review_pack_path and Path(review_pack_path).exists())
        retry_exists = bool(retry_pack_path and Path(retry_pack_path).exists())

        return {
            "gold_dataset_created": gold_exists,
            "gold_dataset_path": str(gold_dataset_path or ""),
            "review_pack_created": review_exists,
            "review_pack_path": str(review_pack_path or ""),
            "retry_pack_created": retry_exists,
            "retry_pack_path": str(retry_pack_path or ""),
            "perfect_count": counts["perfect"],
            "needs_fix_count": counts["needs_fix"],
            "unknown_count": counts["unknown"],
            "total_count": counts["total"],
            "exportable_plate_count": int(exportable_plate_count),
            "exportable_char_count": int(exportable_char_count),
            "perfect_strategy_counts": counts.get("strategy_counts", self._empty_perfect_strategy_counts()),
            "perfect_strategy_char_counts": counts.get("strategy_char_counts", self._empty_perfect_strategy_counts()),
            "selected_gold_export_strategies": sorted(self._get_selected_gold_export_strategy_buckets()),
            "note": note,
        }


    def _write_step3_export_summary(self, summary: dict) -> Path:
        summary_dir = self._get_step3_summary_dir()
        summary_path = summary_dir / "export_summary.json"
        self._atomic_write_json(summary_path, summary)
        return summary_path

    def _read_step3_export_summary(self) -> dict:
        summary_path = self._get_step3_summary_dir() / "export_summary.json"
        try:
            if summary_path.exists():
                loaded = json.loads(summary_path.read_text(encoding="utf-8"))
                if isinstance(loaded, dict) and loaded:
                    return loaded
        except Exception:
            pass

        try:
            if bool(getattr(self, "_step3_linear_mode", False) and CAMPAIGN.get_active_project_name()):
                return {}
        except Exception:
            return {}

        try:
            campaign_chars_dir = getattr(self, "_campaign_chars_dir", None)
            if campaign_chars_dir:
                chars_root = Path(campaign_chars_dir)
            else:
                chars_root = self._get_step3_chars_root_dir(ensure_exists=False)
        except Exception:
            chars_root = None

        if chars_root is None or not Path(chars_root).exists():
            return {}

        try:
            candidates = sorted(
                Path(chars_root).rglob("export_summary.json"),
                key=lambda path: path.stat().st_mtime,
                reverse=True,
            )
        except Exception:
            return {}

        for candidate in candidates:
            try:
                loaded = json.loads(candidate.read_text(encoding="utf-8"))
            except Exception:
                continue
            if not isinstance(loaded, dict) or not loaded:
                continue
            if bool(loaded.get("gold_dataset_created")) and bool(loaded.get("gold_dataset_valid", True)):
                return loaded
        return {}

    def _inspect_yolo_dataset_label_objects(self, dataset_dir: Path | None) -> dict:
        result = {"label_files": 0, "label_files_with_objects": 0, "objects": 0}
        if dataset_dir is None:
            return result
        try:
            labels_root = Path(dataset_dir) / "labels"
            if not labels_root.exists() or not labels_root.is_dir():
                return result
            for label_path in labels_root.rglob("*.txt"):
                if not label_path.is_file():
                    continue
                result["label_files"] += 1
                try:
                    lines = [
                        line.strip()
                        for line in label_path.read_text(encoding="utf-8").splitlines()
                        if line.strip() and not line.strip().startswith("#")
                    ]
                except Exception:
                    lines = []
                if lines:
                    result["label_files_with_objects"] += 1
                    result["objects"] += len(lines)
        except Exception:
            return result
        return {key: int(value or 0) for key, value in result.items()}

    def _get_campaign_step3_annotation_readiness(self) -> dict:
        result = {
            "ok": False,
            "reason": "missing_char_boxes",
            "message": (
                "E3 nie jest jeszcze gotowe do zatwierdzenia. W PZ2 oznacz boxy znaków na tablicach, "
                "uzupełnij ich znaki i dopiero wtedy oznacz tablice jako perfect oraz wykonaj eksport w PZ3."
            ),
            "exportable_plate_count": 0,
            "exportable_char_count": 0,
            "perfect_count": 0,
        }

        try:
            selected_strategies = self._get_selected_gold_export_strategy_buckets()
            selected_sources = self._get_selected_gold_export_source_buckets()
            counts = self._build_campaign_aware_gold_export_counts(
                selected_strategies=selected_strategies,
                selected_sources=selected_sources,
            )
            exportable_chars = int(counts.get("selected_char_count", 0) or 0)
            selected_plates = int(counts.get("selected_plate_count", 0) or 0)
        except Exception:
            exportable_chars = 0
            selected_plates = 0

        try:
            perfect_count = int(self._count_preview_statuses().get("perfect", 0) or 0)
        except Exception:
            perfect_count = 0

        result.update(
            exportable_plate_count=int(selected_plates),
            exportable_char_count=int(exportable_chars),
            perfect_count=int(perfect_count),
        )
        if exportable_chars <= 0:
            if perfect_count > 0 or selected_plates > 0:
                result["message"] = (
                    "E3 ma tablice oznaczone jako perfect, ale nie widzę w nich poprawnych boxów znaków. "
                    "W PZ2 popraw lub dodaj ramki znaków na tablicach, zapisz je i ponownie wykonaj eksport w PZ3."
                )
            return result

        result.update(
            ok=True,
            reason="",
            message="",
            exportable_plate_count=int(selected_plates),
            exportable_char_count=int(exportable_chars),
        )
        return result


    def _return_step3_result_to_wizard(self, summary: dict):
        """
        Jeden kontrakt zwrotny do wizarda:
        - jeśli istnieje gold dataset -> etap 3 jest gotowy do zatwierdzenia
        - jeśli nie -> needs_rework
        """
        gold_ok = bool(summary.get("gold_dataset_created")) and bool(summary.get("gold_dataset_valid", True))

        if gold_ok:
            CAMPAIGN.set_current_step(3)
            CAMPAIGN.set_step3_ready()
            status_msg = (
                "Etap 3 przygotował poprawny dataset znaków. "
                "Wróć do wizarda i zatwierdź E3, aby odblokować etap 4."
            )
            status_kind = "success"
        else:
            CAMPAIGN.set_current_step(3)
            CAMPAIGN.set_step3_needs_rework()
            status_msg = (
                "Etap 3 nie utworzył datasetu treningowego. "
                "Wracasz do wizarda w trybie poprawy."
            )
            status_kind = "warning"

        try:
            campaign_tab = self.app.tabs.get("campaign")
            if campaign_tab:
                try:
                    campaign_tab.request_wizard_stage_focus(step_num=3)
                except Exception:
                    pass
                campaign_tab._rebuild_roadmap_ui()
                campaign_tab._refresh_dashboard()
        except Exception as e:
            logger.debug(f"Nie udało się odświeżyć Wizarda po etapie 3: {e}")

        try:
            self.app.open_controlled_tab("campaign")
            self.app.update_campaign_tab_access()
        except Exception as e:
            logger.debug(f"Nie udało się wrócić do Wizarda po etapie 3: {e}")

        try:
            self.app.update_status(status_msg, status_kind)
        except Exception:
            pass


    def _finalize_step3_from_existing_outputs(self):
        """
        Miękki finał kroku 3:
        - nie tworzy datasetu sam,
        - tylko ocenia to, co już istnieje po eksporcie z zakładki 3
        - zapisuje export_summary.json
        - zwraca wynik do wizarda
        """
        counts = self._count_preview_statuses()

        gold_dataset_path = ""
        review_pack_path = ""

        summary_override = self._read_step3_export_summary()
        if (
            getattr(self, "_step3_linear_mode", False)
            and CAMPAIGN.get_active_project_name()
            and isinstance(summary_override, dict)
            and summary_override
            and (
                summary_override.get("gold_dataset_created") is False
                or summary_override.get("gold_dataset_valid") is False
            )
        ):
            self._return_step3_result_to_wizard(summary_override)
            return

        campaign_readiness = None
        try:
            if getattr(self, "_step3_linear_mode", False) and CAMPAIGN.get_active_project_name():
                campaign_readiness = self._get_campaign_step3_training_readiness()
        except Exception:
            campaign_readiness = None

        preferred_dataset_dir = None
        if isinstance(campaign_readiness, dict):
            ready_dataset = str(campaign_readiness.get("ready_dataset", "") or "").strip()
            if bool(campaign_readiness.get("ok")) and ready_dataset:
                preferred_dataset_dir = Path(ready_dataset)
        else:
            preferred_dataset_dir = self._get_preferred_step3_training_dataset_dir()

        if preferred_dataset_dir is not None:
            gold_dataset_path = str(preferred_dataset_dir)

        campaign_chars_dir = getattr(self, "_campaign_chars_dir", None)
        if campaign_chars_dir:
            chars_root = Path(campaign_chars_dir)
            review_dir = chars_root / "review"
            if review_dir.exists():
                review_pack_path = str(review_dir)

        summary = self._build_step3_export_summary(
            gold_dataset_path=gold_dataset_path,
            review_pack_path=review_pack_path,
            retry_pack_path="",
            note="Finalizacja kroku 3 na podstawie najlepszego dostępnego datasetu znaków projektu (merged preferowany, fallback do istniejącego datasetu)."
        )

        if isinstance(campaign_readiness, dict):
            summary["gold_dataset_valid"] = bool(campaign_readiness.get("ok"))
            summary["gold_dataset_validation_message"] = str(campaign_readiness.get("message", "") or "").strip()

        self._write_step3_export_summary(summary)
        self._return_step3_result_to_wizard(summary)

