    def _get_preferred_step3_training_dataset_dir(self) -> Path | None:
        """
        Zwraca najlepszy dostępny dataset znaków dla finiszu kroku 3.

        Priorytet:
        1. char_merged_pool
        2. najnowszy poprawny dataset z katalogu projektowych datasetów
        """
        merged_dir = self._get_char_merged_pool_dir()
        if self._is_valid_step3_training_dataset_dir(merged_dir):
            return merged_dir

        campaign_datasets_dir = getattr(self, "_campaign_datasets_dir", None)
        if not campaign_datasets_dir:
            return None

        ds_root = Path(campaign_datasets_dir)
        if not ds_root.exists() or not ds_root.is_dir():
            return None

        try:
            candidates = [
                p for p in ds_root.iterdir()
                if p.is_dir() and self._is_valid_step3_training_dataset_dir(p)
            ]
            if not candidates:
                return None

            candidates.sort(key=lambda p: p.stat().st_mtime, reverse=True)
            return candidates[0]
        except Exception:
            return None

    def _inspect_pz3_dataset_source_dir(self, dataset_dir: Path | None) -> dict:
        result = {
            "ok": False,
            "path": "",
            "message": "",
            "total_pairs": 0,
            "flat_pairs": 0,
            "split_pairs": {"train": 0, "val": 0, "test": 0},
            "validation": None,
            "validation_message": "",
            "validation_stats": {},
        }

        if dataset_dir is None:
            result["message"] = "Wskaż gotowy dataset YOLO, aby wznowić split bez wracania do PZ2."
            return result

        try:
            dataset_dir = Path(dataset_dir)
        except Exception:
            result["message"] = "Ścieżka datasetu jest niepoprawna."
            return result

        result["path"] = str(dataset_dir)

        if not dataset_dir.exists():
            result["message"] = "Wskazany folder datasetu nie istnieje."
            return result

        if not dataset_dir.is_dir():
            result["message"] = "Wskazana ścieżka nie jest katalogiem."
            return result

        data_yaml = dataset_dir / "data.yaml"
        images_root = dataset_dir / "images"
        labels_root = dataset_dir / "labels"

        if not data_yaml.exists():
            result["message"] = "Brak pliku data.yaml w wskazanym folderze."
            return result

        if not images_root.exists() or not images_root.is_dir():
            result["message"] = "Brak katalogu images/ w wskazanym datasiecie."
            return result

        if not labels_root.exists() or not labels_root.is_dir():
            result["message"] = "Brak katalogu labels/ w wskazanym datasiecie."
            return result

        try:
            validation_ok, validation_msg, validation_stats = validate_yolo_dataset(dataset_dir)
        except Exception as exc:
            validation_ok, validation_msg, validation_stats = False, str(exc), {}

        result["validation"] = bool(validation_ok)
        result["validation_message"] = str(validation_msg or "")
        result["validation_stats"] = validation_stats if isinstance(validation_stats, dict) else {}

        total_pairs = 0
        split_pairs = {"train": 0, "val": 0, "test": 0}
        flat_pairs = 0

        for split_name in ("train", "val", "test", ""):
            img_dir = images_root / split_name if split_name else images_root
            lbl_dir = labels_root / split_name if split_name else labels_root
            if not img_dir.exists() or not img_dir.is_dir() or not lbl_dir.exists() or not lbl_dir.is_dir():
                continue

            pair_count = 0
            try:
                for img_path in img_dir.iterdir():
                    if not img_path.is_file() or img_path.suffix.lower() not in CONFIG.IMAGE_EXTENSIONS:
                        continue
                    lbl_path = lbl_dir / f"{img_path.stem}.txt"
                    if lbl_path.exists() and lbl_path.is_file():
                        pair_count += 1
            except Exception:
                continue

            if split_name:
                split_pairs[split_name] = pair_count
            else:
                flat_pairs = pair_count
            total_pairs += pair_count

        result["total_pairs"] = int(total_pairs)
        result["flat_pairs"] = int(flat_pairs)
        result["split_pairs"] = {key: int(value) for key, value in split_pairs.items()}

        if total_pairs <= 0:
            result["message"] = (
                "Nie znaleziono żadnej pary obraz + etykieta. "
                "Obsługiwane są układy images/labels oraz images/{train,val,test}."
            )
            return result

        flat_note = f"flat={flat_pairs}" if flat_pairs > 0 else ""
        split_note = ", ".join(f"{name}={split_pairs.get(name, 0)}" for name in ("train", "val", "test"))
        summary_parts = [part for part in (flat_note, split_note) if part]
        validation_note = "Walidacja YOLO pełna: OK." if validation_ok else f"Walidacja YOLO pełna: {validation_msg or 'pominięta'}."
        result["message"] = (
            f"Dataset gotowy do pracy: {total_pairs} par obraz + etykieta"
            + (f" ({'; '.join(summary_parts)})" if summary_parts else "")
            + f" {validation_note}"
        )
        result["ok"] = True
        return result

    def _pick_pz3_existing_dataset_dir(self):
        initial = str((self.pz3_existing_dataset_var.get() or "").strip())
        if not initial:
            preferred = self._get_preferred_step3_training_dataset_dir()
            if preferred is not None:
                initial = str(preferred)
        if not initial:
            initial = str(self._get_step3_datasets_root_dir())

        selected = filedialog.askdirectory(
            initialdir=str(initial),
            title="Wybierz gotowy dataset YOLO znaków"
        )
        if selected:
            self.pz3_existing_dataset_var.set(str(selected))
            try:
                self._force_save_all()
            except Exception:
                pass

    def _use_preferred_pz3_dataset_dir(self):
        preferred = self._get_preferred_step3_training_dataset_dir()
        if preferred is None:
            messagebox.showwarning(
                "Brak datasetu",
                "Nie znaleziono jeszcze gotowego datasetu znaków w katalogach projektu."
            )
            return

        self.pz3_existing_dataset_var.set(str(preferred))
        try:
            self._force_save_all()
        except Exception:
            pass

    def _get_project_review_dir(self) -> Path | None:
        """
        Projektowy katalog review dla eksportów CVAT z kroku 3.
        """
        campaign_chars_dir = getattr(self, "_campaign_chars_dir", None)
        if not campaign_chars_dir:
            return None

        root = Path(campaign_chars_dir)
        root.mkdir(parents=True, exist_ok=True)

        review_dir = root / "review"
        review_dir.mkdir(parents=True, exist_ok=True)
        return review_dir
    def _store_current_preview_in_manual_char_pool(self, metadata: dict):
        """
        Zapisuje aktualnie poprawioną paczkę preview do manual_char_pool,
        aby mogła później zasilić trening modelu znaków.
        """
        manual_pool_dir = self._get_char_manual_pool_dir()
        if manual_pool_dir is None:
            raise RuntimeError("Brak katalogu manual_char_pool dla aktywnego projektu.")

        preview_dir = Path((self.preview_dir_var.get() or "").strip())
        if not preview_dir.exists() or not preview_dir.is_dir():
            raise RuntimeError("Brak poprawnego katalogu preview do zapisania w manual_char_pool.")

        preview_name = preview_dir.name if preview_dir.name else "manual_import"
        target_dir = manual_pool_dir / preview_name
        target_images_dir = target_dir / "images"

        target_dir.mkdir(parents=True, exist_ok=True)
        target_images_dir.mkdir(parents=True, exist_ok=True)

        # zapis metadata
        target_meta = target_dir / "metadata.json"
        self._atomic_write_json(target_meta, metadata)

        # kopiowanie obrazów źródłowych preview
        source_images_dir = preview_dir / "images"
        if source_images_dir.exists() and source_images_dir.is_dir():
            for img_file in source_images_dir.iterdir():
                if not img_file.is_file():
                    continue
                dst = target_images_dir / img_file.name
                shutil.copy2(img_file, dst)

        return target_dir
    def _has_char_manual_imports(self) -> bool:
        pool_dir = self._get_char_manual_pool_dir()
        if pool_dir is None or not pool_dir.exists():
            return False

        try:
            return any(p.exists() for p in pool_dir.iterdir())
        except Exception:
            return False


    def _has_char_gold_exports(self) -> bool:
        pool_dir = self._get_char_gold_pool_dir()
        if pool_dir is None or not pool_dir.exists():
            return False

        try:
            return any(p.exists() for p in pool_dir.iterdir())
        except Exception:
            return False
    def _get_campaign_step3_training_readiness(self) -> dict:
        default_result = {
            "ok": False,
            "reason": "missing_char_dataset",
            "message": "Aby zakończyć etap 3, przygotuj poprawny dataset znaków z niepustym train i val.",
            "ready_dataset": "",
            "dataset_hint": "",
            "train_images": 0,
            "val_images": 0,
            "test_images": 0,
            "exportable_plate_count": 0,
            "exportable_char_count": 0,
            "validation_message": "",
        }

        try:
            in_campaign = bool(getattr(self, "_step3_linear_mode", False) and CAMPAIGN.get_active_project_name())
            if not in_campaign:
                preferred = self._get_preferred_step3_training_dataset_dir()
                if preferred is not None:
                    default_result.update(ok=True, reason="", ready_dataset=str(preferred))
                return default_result
        except Exception:
            return default_result

        annotation_readiness = self._get_campaign_step3_annotation_readiness()
        default_result.update(
            exportable_plate_count=int(annotation_readiness.get("exportable_plate_count", 0) or 0),
            exportable_char_count=int(annotation_readiness.get("exportable_char_count", 0) or 0),
        )
        if not bool(annotation_readiness.get("ok")):
            default_result.update(
                reason=str(annotation_readiness.get("reason") or "missing_char_boxes"),
                message=str(annotation_readiness.get("message") or default_result["message"]),
            )

        try:
            summary = self._read_step3_export_summary()
            if not isinstance(summary, dict) or not summary:
                return default_result

            dataset_path_raw = str(summary.get("gold_dataset_path", "") or "").strip()
            dataset_path = Path(dataset_path_raw) if dataset_path_raw else None
            validation_message = str(summary.get("gold_dataset_validation_message", "") or "").strip()
            summary_char_count = int(summary.get("exportable_char_count", 0) or 0)
            summary_plate_count = int(summary.get("exportable_plate_count", 0) or 0)
            label_object_count = 0
            if dataset_path is not None and dataset_path.exists():
                try:
                    label_stats = self._inspect_yolo_dataset_label_objects(dataset_path)
                    label_object_count = int(label_stats.get("objects", 0) or 0)
                except Exception:
                    label_object_count = 0

            if dataset_path is not None and dataset_path.exists():
                default_result.update(
                    exportable_plate_count=max(
                        int(default_result.get("exportable_plate_count", 0) or 0),
                        summary_plate_count,
                    ),
                    exportable_char_count=max(
                        int(default_result.get("exportable_char_count", 0) or 0),
                        summary_char_count,
                        label_object_count,
                    ),
                )

            if bool(summary.get("gold_dataset_created")) and dataset_path is not None and dataset_path.exists():
                if max(summary_char_count, label_object_count) <= 0:
                    merged = dict(default_result)
                    merged.update(
                        ok=False,
                        reason="missing_char_boxes",
                        ready_dataset=str(dataset_path),
                        dataset_hint=str(dataset_path),
                        validation_message=validation_message,
                        message=(
                            str(annotation_readiness.get("message") or "").strip()
                            or "Dataset znaków istnieje, ale nie zawiera żadnych etykiet z boxami znaków. Wróć do PZ2/PZ3 i wyeksportuj realne boxy znaków."
                        ),
                    )
                    return merged

                merged = dict(default_result)
                merged.update(
                    ok=bool(summary.get("gold_dataset_valid", True)),
                    reason=("" if bool(summary.get("gold_dataset_valid", True)) else "invalid_char_dataset"),
                    ready_dataset=str(dataset_path),
                    dataset_hint=str(dataset_path),
                    exportable_plate_count=max(int(default_result.get("exportable_plate_count", 0) or 0), summary_plate_count),
                    exportable_char_count=max(int(default_result.get("exportable_char_count", 0) or 0), summary_char_count, label_object_count),
                    validation_message=validation_message,
                    message=(
                        ""
                        if bool(summary.get("gold_dataset_valid", True))
                        else (validation_message or default_result["message"])
                    ),
                )
                return merged

            if summary.get("gold_dataset_created") is False or summary.get("gold_dataset_valid") is False:
                merged = dict(default_result)
                merged.update(
                    reason="invalid_char_dataset",
                    validation_message=validation_message,
                    message=(validation_message or default_result["message"]),
                )
                return merged
        except Exception as e:
            logger.debug(f"Nie udało się pobrac walidacji datasetu znaków dla kroku 3: {e}")

        return default_result

    def _get_step3_finish_block_message(self, readiness: dict | None = None) -> str:
        readiness = dict(readiness or {})
        if bool(readiness.get("ok")):
            return ""

        reason = str(readiness.get("reason", "") or "").strip().lower()
        train_images = int(readiness.get("train_images", 0) or 0)
        val_images = int(readiness.get("val_images", 0) or 0)
        test_images = int(readiness.get("test_images", 0) or 0)
        validation_msg = str(readiness.get("validation_message", "") or "").strip()

        if reason == "missing_char_boxes":
            return str(readiness.get("message") or "").strip() or (
                "E3 wymaga co najmniej jednej tablicy perfect z poprawnymi boxami znaków. "
                "Wróć do PZ2, oznacz znaki na tablicach i ponownie wykonaj eksport w PZ3."
            )

        if reason == "invalid_char_dataset":
            if validation_msg in {"Brak obrazów w images/val", "Brak obrazów w images/val"}:
                return (
                    f"Dataset znaków nadal nie ma walidacji: train={train_images}, val={val_images}, test={test_images}. "
                    "W PZ3 przebuduj eksport źródłowy, a wariant treningowy/split przygotuj w Z4."
                )
            if validation_msg in {"Brak obrazów w images/train", "Brak obrazów w images/train"}:
                return "Dataset znaków nie ma jeszcze danych treningowych. W PZ3 przebuduj eksport źródłowy, a split przygotuj w Z4."
            return (
                f"Dataset znaków nadal nie jest gotowy do treningu: train={train_images}, val={val_images}, test={test_images}. "
                "W PZ3 popraw eksport źródłowy, a wariant treningowy/split przygotuj w Z4."
            )

        return "Aby zakończyć etap 3, przygotuj źródłowy dataset znaków w PZ3, a wariant treningowy/split przygotuj w Z4."

    def _set_step3_finish_hint(self, text: str = "", tone: str = "muted"):
        action_card = getattr(self, "step3_finish_action_card", None)
        if action_card is not None:
            try:
                action_card.set_description(str(text or "").strip(), tone=str(tone or "muted"))
                return
            except Exception:
                pass

        label = getattr(self, "step3_finish_hint_lbl", None)
        if label is None:
            return

        msg = str(text or "").strip()
        try:
            self._set_inline_status_label_state(label, text=msg, tone=tone, emphasis=False)
        except Exception:
            try:
                label.configure(text=msg)
            except Exception:
                pass

    def _has_any_step3_export_outputs(self) -> bool:
        """
        Etap 3 można zakończyć dopiero wtedy, gdy istnieje realny dataset
        treningowy znaków dla etapu 4.

        Sam review export do CVAT nie wystarcza.
        """
        try:
            if getattr(self, "_step3_linear_mode", False) and CAMPAIGN.get_active_project_name():
                summary = self._read_step3_export_summary()
                if not isinstance(summary, dict) or not summary:
                    return False
                if summary.get("gold_dataset_created") is False or summary.get("gold_dataset_valid") is False:
                    return False
                summary_dataset_path = str(summary.get("gold_dataset_path", "") or "").strip()
                if not (summary.get("gold_dataset_created") and summary_dataset_path):
                    return False
                try:
                    return Path(summary_dataset_path).exists()
                except Exception:
                    return False
            return self._get_preferred_step3_training_dataset_dir() is not None
        except Exception:
            return False
    
    def _return_to_wizard_for_step3_rework(self):
        try:
            self._hide_campaign_detect_splash()
        except Exception:
            pass

        focus_step = 3
        status_message = "Wracasz do wizarda. Etap 3 pozostaje w toku."
        status_tone = "info"
        try:
            if CAMPAIGN.get_active_project_name():
                current_step = int(CAMPAIGN.get_current_step() or 3)
                current_status = str(CAMPAIGN.get_step3_status() or "").strip().lower() or "pending"
                readiness = self._get_campaign_step3_training_readiness()
                ready_for_approval = bool(
                    self._has_any_step3_export_outputs()
                    and bool(readiness.get("ok"))
                )

                if ready_for_approval:
                    CAMPAIGN.set_current_step(3)
                    CAMPAIGN.set_step3_ready()
                    status_message = "Wracasz do wizarda. E3 jest gotowe do zatwierdzenia."
                    status_tone = "success"
                elif current_status == "approved" or current_step >= 4:
                    CAMPAIGN.approve_step3()
                    CAMPAIGN.set_current_step(max(4, current_step))
                    focus_step = 4
                    status_message = "Wracasz do wizarda. E3 pozostaje zatwierdzone, więc możesz kontynuować E4."
                    status_tone = "info"
                elif current_status == "needs_rework":
                    CAMPAIGN.set_current_step(3)
                    CAMPAIGN.set_step3_needs_rework()
                    status_message = "Wracasz do wizarda w trybie poprawy kroku 3."
                    status_tone = "warning"
                else:
                    CAMPAIGN.set_current_step(3)
                    CAMPAIGN.set_step3_pending()
        except Exception as e:
            logger.debug(f"Nie udało się ustawić stanu powrotu dla kroku 3: {e}")

        try:
            campaign_tab = self.app.tabs.get("campaign")
            if campaign_tab:
                try:
                    campaign_tab.request_wizard_stage_focus(step_num=focus_step)
                except Exception:
                    pass
                campaign_tab._rebuild_roadmap_ui()
                campaign_tab._refresh_dashboard()
        except Exception as e:
            logger.debug(f"Nie udało się odświeżyć wizarda po powrocie z kroku 3: {e}")

        try:
            self.app.open_controlled_tab("campaign")
            self.app.update_campaign_tab_access()
            self.app.update_status(status_message, status_tone)
        except Exception as e:
            logger.debug(f"Nie udało się wrócić do wizarda dla kroku 3: {e}")

    def _resolve_step3_campaign_action_command(self, command_id: str):
        normalized = str(command_id or "").strip().lower()
        if normalized in {"return_to_wizard_rework", "return_to_wizard_step3"}:
            return self._return_to_wizard_for_step3_rework
        if normalized == "finalize_step3":
            return self._finalize_step3_from_existing_outputs
        return None

