    def _set_console_text(self, console_widget, text):
        if console_widget in (getattr(self, "export_console", None), getattr(self, "import_console", None)):
            self._hide_pz3_status_summary_section()
        if isinstance(console_widget, tk.Text):
            console_widget.config(state=tk.NORMAL)
            console_widget.delete(1.0, tk.END)
            console_widget.insert(tk.END, text)
            console_widget.config(state=tk.DISABLED)
            self.frame.update()
            return

        msg = str(text or "").strip()
        tone = "muted"
        if any(token in msg for token in ("❌", "BŁĄD", "ERROR")):
            tone = "danger"
        elif any(token in msg for token in ("⚠", "OSTRZEŻ", "WARNING")):
            tone = "warning"
        elif any(token in msg for token in ("✅", "sukcesem", "gotowy", "gotowa", "gotowe")):
            tone = "success"

        try:
            self._set_inline_status_label_state(console_widget, text=msg, tone=tone, emphasis=False)
            console_widget.update_idletasks()
        except Exception:
            try:
                console_widget.configure(text=msg)
            except Exception:
                pass

        if console_widget in (getattr(self, "export_console", None), getattr(self, "import_console", None)):
            self._remember_pz3_operation_message(console_widget, msg, tone)
            if tone == "danger":
                title = "Błąd importu PZ3" if console_widget is getattr(self, "import_console", None) else "Błąd eksportu PZ3"
                self._show_pz3_operation_summary_modal(title, msg, tone="error")
            try:
                self._hide_pz3_status_summary_section()
                self._refresh_pz3_status_panel_ui()
            except Exception:
                pass

    def _pick_file(self, var):
        initial = self.preview_dir_var.get().strip()
        if not initial or not Path(initial).exists():
            initial = str(CONFIG.WORKSPACE_DIR.absolute())
        p = filedialog.askopenfilename(initialdir=initial, filetypes=[("XML", "*.xml")])
        if p:
            var.set(p)

    def _get_active_preview_context(self) -> dict:
        preview_dir_raw = str(self.preview_dir_var.get() or "").strip()
        if not self._preview_dir_has_plate_entries(preview_dir_raw):
            fallback_preview_dir = self._get_preferred_step3_preview_dir(require_plates=True, allow_fallback=True)
            if fallback_preview_dir:
                preview_dir_raw = str(fallback_preview_dir)
                try:
                    self.preview_dir_var.set(preview_dir_raw)
                    self._save_local_setting("char_preview_dir", preview_dir_raw)
                except Exception:
                    pass

        if not preview_dir_raw:
            return {
                "ready": False,
                "reason": "missing_preview",
                "message": (
                    "Brak aktywnego preview runu. Utwórz go w [Z3]/[PZ1] przyciskiem „Wytnij tablice do PZ2”, "
                    "a potem przejdź do [PZ2]. Jeśli run już istnieje, w [PZ2] otwórz „Źródło PZ2” -> "
                    "„Zmień źródło preview” -> „Wybierz katalog” i wskaż folder z metadata.json oraz images/."
                ),
                "preview_dir": None,
                "meta_path": None,
                "images_dir": None,
                "plate_count": 0,
            }

        preview_dir = Path(preview_dir_raw)
        meta_path = preview_dir / "metadata.json"
        images_dir = preview_dir / "images"

        if not preview_dir.exists() or not preview_dir.is_dir():
            return {
                "ready": False,
                "reason": "missing_directory",
                "message": f"Aktywny preview run nie istnieje:\n{preview_dir}",
                "preview_dir": preview_dir,
                "meta_path": meta_path,
                "images_dir": images_dir,
                "plate_count": 0,
            }

        if not meta_path.exists():
            return {
                "ready": False,
                "reason": "missing_metadata",
                "message": f"W aktywnym preview runie brakuje metadata.json:\n{preview_dir}",
                "preview_dir": preview_dir,
                "meta_path": meta_path,
                "images_dir": images_dir,
                "plate_count": 0,
            }

        if not images_dir.exists() or not images_dir.is_dir():
            return {
                "ready": False,
                "reason": "missing_images",
                "message": f"W aktywnym preview runie brakuje katalogu images/:\n{preview_dir}",
                "preview_dir": preview_dir,
                "meta_path": meta_path,
                "images_dir": images_dir,
                "plate_count": 0,
            }

        plate_count = int(self._get_preview_dir_plate_count(preview_dir) or 0)
        if plate_count <= 0:
            return {
                "ready": False,
                "reason": "empty_preview",
                "message": f"Preview run jest pusty i nie zawiera tablic do eksportu:\n{preview_dir}",
                "preview_dir": preview_dir,
                "meta_path": meta_path,
                "images_dir": images_dir,
                "plate_count": 0,
            }

        return {
            "ready": True,
            "reason": "ok",
            "message": "",
            "preview_dir": preview_dir,
            "meta_path": meta_path,
            "images_dir": images_dir,
            "plate_count": plate_count,
        }

    def _refresh_preview_bound_action_states(self):
        context = self._get_active_preview_context()
        preview_ready = bool(context.get("ready"))
        button_state = "normal" if preview_ready else "disabled"

        for attr_name in ("btn_cvat_export", "btn_cvat_import"):
            self._set_widget_state(getattr(self, attr_name, None), button_state)

        export_hint = getattr(self, "cvat_export_state_lbl", None)
        if export_hint is not None:
            if preview_ready:
                preview_dir = context.get("preview_dir")
                plate_count = int(context.get("plate_count", 0) or 0)
                preview_name = preview_dir.name if isinstance(preview_dir, Path) else str(preview_dir or "")
                self._set_inline_status_label_state(
                    export_hint,
                    text=f"Aktywny preview z [PZ2]: {preview_name} | tablice do review: {plate_count}",
                    tone="muted",
                    emphasis=False,
                )
            else:
                self._set_inline_status_label_state(
                    export_hint,
                    text=(
                        "Preview run przygotujesz w [Z3]/[PZ1] przyciskiem „Wytnij tablice do PZ2”. "
                        "Gotowy run możesz wskazać w [PZ2] -> Źródło PZ2 -> Zmień źródło preview -> Wybierz katalog."
                    ),
                    tone="warning",
                    emphasis=False,
                )

        import_hint = getattr(self, "cvat_import_target_hint_lbl", None)
        if import_hint is not None:
            if preview_ready:
                self._set_inline_status_label_state(
                    import_hint,
                    text="Import dotyczy aktywnego preview runu wskazanego w sekcji [PZ2] -> Źródło PZ2.",
                    tone="muted",
                    emphasis=False,
                )
            else:
                self._set_inline_status_label_state(
                    import_hint,
                    text=(
                        "Import wymaga aktywnego preview runu. Utwórz go w [PZ1] albo wskaż w [PZ2] "
                        "przez Źródło PZ2 -> Zmień źródło preview."
                    ),
                    tone="warning",
                    emphasis=False,
                )

    def _run_cvat_export(self):
        preview_context = self._get_active_preview_context()
        if not bool(preview_context.get("ready")):
            self._set_console_text(
                self.export_console,
                f"❌ BŁĄD: {str(preview_context.get('message') or 'Najpierw wczytaj poprawny preview run.')}"
            )
            return

        work_dir = preview_context["preview_dir"]

        export_dir = work_dir

        project_review_dir = self._get_project_review_dir()
        if project_review_dir is not None:
            try:
                preview_name = work_dir.name if work_dir.name else "review_pack"
            except Exception:
                preview_name = "review_pack"

            export_dir = project_review_dir / preview_name
            export_dir.mkdir(parents=True, exist_ok=True)
        meta_path = work_dir / "metadata.json"
        out_xml = export_dir / "annotations.xml"
        out_zip = export_dir / "cvat_export.zip"

        self._set_console_text(self.export_console, "⌛ Eksportowanie do CVAT w toku...")

        try:
            import datetime
            with open(meta_path, 'r', encoding='utf-8') as f:
                metadata = json.load(f)

            if self.smart_export_var.get():
                filtered = {k: v for k, v in metadata.items() if v.get("status") != "perfect"}
                tmp_meta = work_dir / "temp_meta.json"
                with open(tmp_meta, 'w', encoding='utf-8') as f:
                    json.dump(filtered, f, indent=2, ensure_ascii=False)
                source_meta = tmp_meta
            else:
                source_meta = meta_path

            from ..cvat_tools.cvat_character_exporter import CVATCharacterExporter
            from ..cvat_tools.cvat_zip_manager import CVATZipManager

            if CVATCharacterExporter().export(source_meta, out_xml):
                xml_image_names = [f"{plate_id}.jpg" for plate_id in list((filtered if self.smart_export_var.get() else metadata).keys())]
                zip_ok, zip_msg = CVATZipManager.create_cvat_import_zip(
                    out_xml,
                    work_dir / "images",
                    out_zip,
                    image_names_allowlist=xml_image_names,
                )
                review_manifest = {
                    "review_manifest_id": f"review_{datetime.datetime.now().strftime('%Y%m%d_%H%M%S')}",
                    "created_at": datetime.datetime.now().isoformat(timespec="seconds"),
                    "source_preview_dir": str(work_dir),
                    "source_metadata_path": str(meta_path),
                    "smart_export": bool(self.smart_export_var.get()),
                    "exported_plate_ids": list((filtered if self.smart_export_var.get() else metadata).keys()),
                    "exported_image_names": xml_image_names,
                    "zip_path": str(out_zip),
                    "xml_path": str(out_xml),
                }
                try:
                    self._atomic_write_json(export_dir / "review_manifest.json", review_manifest)
                except Exception as e:
                    logger.debug(f"Nie udało się zapisać review_manifest.json: {e}")

                summary = self._build_step3_local_success_message(
                    "Przygotowano paczkę CVAT.",
                    out_zip,
                    "Otwórz CVAT, wykonaj poprawki i wróć do Z3 / PZ3 -> Import ręcznych poprawek.",
                )
                if not zip_ok:
                    summary += f"\n\nUwaga: ZIP zgłosił ostrzeżenie: {zip_msg}"
                self._set_console_text(self.export_console, summary)
                self._show_pz3_operation_summary_modal(
                    "Eksport CVAT zakończony",
                    summary,
                    tone=("warning" if not zip_ok else "success"),
                )
                try:
                    self._log(
                        self.export_console,
                        f"[INFO] Review pack zapisano w katalogu projektu: {export_dir}",
                        "INFO"
                    )
                    self._log(
                        self.export_console,
                        f"[INFO] review_manifest.json zapisano w: {export_dir / 'review_manifest.json'}",
                        "INFO"
                    )
                except Exception:
                    pass
                try:
                    self._update_step3_finish_button_state()
                except Exception:
                    pass

                if self.smart_export_var.get() and source_meta.exists():
                    source_meta.unlink()

        except Exception as e:
            self._set_console_text(self.export_console, f"❌ BŁĄD EKSPORTU CVAT:\n{e}")

    def _run_yolo_gold_export(self):
        selected_buckets = self._get_selected_gold_export_strategy_buckets()
        selected_labels = self._format_selected_gold_export_strategy_labels()

        if not selected_buckets:
            self._set_console_text(
                self.export_console,
                "❌ Nie wybrano żadnej strategii perfect do eksportu gold packa.\n\n"
                "Zaznacz co najmniej jedną z opcji: OCR exact, YOLO exact, OCR + YOLO rescue, YOLO boxy + OCR lub Manual / inne perfect."
            )
            return

        self._set_console_text(
            self.export_console,
            f"⌛ Zbieranie idealnych tablic...\nFiltr strategii: {selected_labels}"
        )

        base_chars_dir = self._get_step3_chars_root_dir()

        import datetime, uuid, shutil
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")

        base_datasets_dir = self._get_step3_datasets_root_dir()
        yolo_out = base_datasets_dir / f"YOLO_MegaDataset_Chars_{timestamp}"
        img_out, lbl_out = yolo_out / "images", yolo_out / "labels"

        try:
            img_out.mkdir(parents=True, exist_ok=True)
            lbl_out.mkdir(parents=True, exist_ok=True)

            char_map = {c: i for i, c in enumerate(CHAR_CLASS_ALPHABET)}
            copied, seen = 0, set()
            total_strategy_counts = self._empty_perfect_strategy_counts()
            copied_strategy_counts = self._empty_perfect_strategy_counts()

            meta_candidates = []
            for meta in base_chars_dir.rglob("metadata.json"):
                run_dir = meta.parent
                if (run_dir / "images").exists():
                    meta_candidates.append(meta)

            meta_candidates.sort(key=lambda p: p.stat().st_mtime, reverse=True)

            for meta in meta_candidates:
                run_dir = meta.parent
                with open(meta, "r", encoding="utf-8") as f:
                    metadata = json.load(f)

                for pid, data in {k: v for k, v in metadata.items() if v.get("status") == "perfect"}.items():
                    strategy_bucket = self._get_perfect_strategy_bucket(data)
                    total_strategy_counts[strategy_bucket] += 1
                    if strategy_bucket not in selected_buckets:
                        continue

                    uk = f"{data.get('source_image', 'u')}_{int(data.get('source_bbox', [0])[0]//10) if data.get('source_bbox') else 0}"
                    if uk in seen:
                        continue
                    seen.add(uk)

                    img_src = run_dir / "images" / f"{pid}.jpg"
                    if not img_src.exists():
                        continue

                    img = cv2.imread(str(img_src))
                    if img is None:
                        continue

                    ih, iw = img.shape[:2]
                    new_pid = f"mega_{uuid.uuid4().hex[:8]}_{pid}"
                    shutil.copy2(img_src, img_out / f"{new_pid}.jpg")

                    txt = []
                    for c in data.get("characters", []):
                        ch = str(c.get("character", "")).upper()
                        if ch not in char_map:
                            continue
                        x1, y1, x2, y2 = c.get("bbox", [0, 0, 0, 0])
                        if x2 <= x1 or y2 <= y1:
                            continue
                        xc = max(0.0, min(1.0, ((x1 + x2) / 2.0) / iw))
                        yc = max(0.0, min(1.0, ((y1 + y2) / 2.0) / ih))
                        w = max(0.0, min(1.0, (x2 - x1) / iw))
                        h = max(0.0, min(1.0, (y2 - y1) / ih))
                        txt.append(f"{char_map[ch]} {xc:.6f} {yc:.6f} {w:.6f} {h:.6f}")

                    if not txt:
                        continue

                    (lbl_out / f"{new_pid}.txt").write_text("\n".join(txt), encoding="utf-8")
                    copied += 1
                    copied_strategy_counts[strategy_bucket] += 1

            if copied == 0:
                msg = (
                    "❌ NIE UDAŁO SIĘ UTWORZYĆ DATASETU YOLO.\n\n"
                    f"Powód: po filtrze strategii ({selected_labels}) nie znaleziono ani jednej tablicy ze statusem 🟢 perfect.\n\n"
                    "Tablica perfect musi mieć przynajmniej jeden poprawny box znaku z etykietą. Puste tablice nie są eksportowane.\n\n"
                    f"Dostępne tablice perfect wg strategii przed deduplikacją:\n{self._format_perfect_strategy_counts(total_strategy_counts)}\n\n"
                    "CO DALEJ:\n"
                    "1. Możesz rozszerzyć zaznaczone strategie w pz3.\n"
                    "2. Możesz wrócić do pz2 i poprawić OCR / Laboratorium.\n"
                    "3. Możesz wykonać eksport do CVAT i później zaimportować poprawki.\n"
                    "4. Możesz też wrócić do wizarda i skorzystać z trybów naprawczych."
                )
                self._set_console_text(self.export_console, msg)
                try:
                    failure_summary = self._build_step3_export_summary(
                        gold_dataset_path="",
                        review_pack_path="",
                        retry_pack_path="",
                        note="Nie znaleziono tablic perfect po aktualnym filtrze strategii i zrodel."
                    )
                    failure_summary["gold_dataset_valid"] = False
                    failure_summary["gold_dataset_validation_message"] = msg
                    self._write_step3_export_summary(failure_summary)
                except Exception:
                    pass

                try:
                    if self._step3_linear_mode and CAMPAIGN.get_active_project_name():
                        CAMPAIGN.set_step3_needs_rework()
                except Exception:
                    pass

                try:
                    self._update_step3_finish_button_state()
                except Exception:
                    pass

                try:
                    self.app.update_status(
                        "Nie utworzono gold packa — pozostajesz w z3/pz3, aby kontynuować pracę.",
                        "warning"
                    )
                except Exception:
                    pass

                return

            yaml_content = f"path: {yolo_out.absolute().as_posix()}\ntrain: images\nval: images\nnc: 36\nnames:\n"
            for char, class_id in char_map.items():
                yaml_content += f"  {class_id}: '{char}'\n"
            (yolo_out / "data.yaml").write_text(yaml_content, encoding="utf-8")

            self._set_console_text(
                self.export_console,
                self._build_step3_local_success_message(
                    "Utworzono dataset YOLO znaków.",
                    yolo_out,
                    "Przejdź do Z4, aby użyć datasetu w treningu, albo zostań w Z3 / PZ3 i wykonaj kolejny eksport.",
                )
            )
            try:
                success_summary = self._build_step3_export_summary(
                    gold_dataset_path=str(yolo_out),
                    review_pack_path="",
                    retry_pack_path="",
                    note="Bieżący eksport gold packa znaków zakończył się powodzeniem."
                )
                success_summary["exportable_plate_count"] = int(copied)
                success_summary["gold_dataset_valid"] = True
                success_summary["gold_dataset_validation_message"] = ""
                self._write_step3_export_summary(success_summary)
            except Exception:
                pass
            self._log(
                self.export_console,
                f"[INFO] Dostępne tablice perfect we wszystkich paczkach przed deduplikacją i filtrem: {self._format_perfect_strategy_counts(total_strategy_counts)}",
                "INFO"
            )
            try:
                self._update_step3_finish_button_state()
                self._set_button_emphasis("btn_finish_step3_frame", True)
            except Exception:
                pass

            try:
                self.app.update_status(
                    "Paczka YOLO została utworzona poprawnie. Możesz zakończyć ten krok przyciskiem finish.",
                    "info"
                )
            except Exception:
                pass
            try:
                modal_lines = [
                    "Utworzono dataset YOLO znaków.",
                    "",
                    f"Katalog: {yolo_out}",
                ]
                if split_enabled:
                    modal_lines.append(
                        f"Split: train={int(split_stats.get('train', 0) or 0)}, "
                        f"val={int(split_stats.get('val', 0) or 0)}, "
                        f"test={int(split_stats.get('test', 0) or 0)}"
                    )
                else:
                    modal_lines.append("Split: wyłączony (flat images/labels)")
                modal_lines.extend(
                    [
                        "",
                        (
                            "Możesz wrócić do wizarda i zatwierdzić etap 3 "
                            "albo zostać w Z3 / PZ3 i wykonać kolejny eksport."
                            if self._step3_linear_mode and CAMPAIGN.get_active_project_name()
                            else "Możesz przejść do Z4, aby użyć datasetu w treningu, albo zostać w Z3 / PZ3 i wykonać kolejny eksport."
                        ),
                    ]
                )
                self.app.themed_info(
                    "Eksport zakończony",
                    "\n".join(modal_lines),
                    parent=self.frame,
                    tone="success",
                )
            except Exception:
                pass
        except Exception as e:
            self._set_console_text(self.export_console, f"❌ BŁĄD EKSPORTU YOLO:\n{e}")

    def _run_yolo_gold_export(self):
        selected_buckets = self._get_selected_gold_export_strategy_buckets()
        selected_labels = self._format_selected_gold_export_strategy_labels()
        selected_sources = self._get_selected_gold_export_source_buckets()
        selected_source_labels = self._format_selected_gold_export_source_labels()
        split_enabled = False
        train_pct, val_pct, test_pct = self._get_gold_export_split_percentages()

        if not selected_buckets:
            self._set_console_text(
                self.export_console,
                "❌ Nie wybrano żadnej strategii perfect do eksportu gold packa.\n\n"
                "Zaznacz co najmniej jedną z opcji: OCR exact, YOLO exact, OCR + YOLO rescue, YOLO boxy + OCR lub Manual / inne perfect."
            )
            return
        if not selected_sources:
            self._set_console_text(
                self.export_console,
                "❌ Nie wybrano żadnego źródła do eksportu gold packa.\n\n"
                "Zaznacz Auto z runu lub Ręczne poprawki lokalne. Poprawki CVAT po imporcie są dołączane automatycznie."
            )
            return

        split_line = "Wariant/split: przygotujesz w Z4"
        self._set_console_text(
            self.export_console,
            f"⏳ Zbieranie idealnych tablic...\nFiltr strategii: {selected_labels}\nŹródła: {selected_source_labels}\n{split_line}"
        )

        import datetime, uuid, shutil
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")

        base_datasets_dir = self._get_step3_datasets_root_dir()
        yolo_out = base_datasets_dir / f"YOLO_MegaDataset_Chars_{timestamp}"

        try:
            char_map = {c: i for i, c in enumerate(CHAR_CLASS_ALPHABET)}
            (
                plate_entries,
                total_strategy_counts,
                copied_strategy_counts,
                total_source_counts,
                copied_source_counts,
            ) = self._collect_gold_export_plate_candidates(selected_buckets, selected_sources)
            export_entries = []

            for plate_entry in plate_entries:
                pid = str(plate_entry.get("pid", "") or "")
                img_src = plate_entry.get("img_src")
                data = plate_entry.get("data", {})
                strategy_bucket = str(plate_entry.get("strategy_bucket", "") or "")
                source_bucket = str(plate_entry.get("source_bucket", "") or "")
                img = cv2.imread(str(img_src))
                if img is None:
                    continue

                ih, iw = img.shape[:2]
                new_pid = f"mega_{uuid.uuid4().hex[:8]}_{pid}"
                txt = []
                for c in data.get("characters", []):
                    ch = str(c.get("character", "")).upper()
                    if ch not in char_map:
                        continue
                    x1, y1, x2, y2 = c.get("bbox", [0, 0, 0, 0])
                    if x2 <= x1 or y2 <= y1:
                        continue
                    xc = max(0.0, min(1.0, ((x1 + x2) / 2.0) / iw))
                    yc = max(0.0, min(1.0, ((y1 + y2) / 2.0) / ih))
                    w = max(0.0, min(1.0, (x2 - x1) / iw))
                    h = max(0.0, min(1.0, (y2 - y1) / ih))
                    txt.append(f"{char_map[ch]} {xc:.6f} {yc:.6f} {w:.6f} {h:.6f}")

                if not txt:
                    continue

                export_entries.append(
                    {
                        "pid": new_pid,
                        "img_src": img_src,
                        "label_text": "\n".join(txt),
                        "strategy_bucket": strategy_bucket,
                        "source_bucket": source_bucket,
                    }
                )

            copied = len(export_entries)
            if copied == 0:
                msg = (
                    "❌ NIE UDAŁO SIĘ UTWORZYĆ DATASETU YOLO.\n\n"
                    f"Powód: po filtrze strategii ({selected_labels}) i źródeł ({selected_source_labels}) "
                    "nie znaleziono ani jednej tablicy ze statusem perfect.\n\n"
                    "Tablica perfect musi mieć przynajmniej jeden poprawny box znaku z etykietą. Puste tablice nie są eksportowane.\n\n"
                    f"Dostępne tablice perfect wg strategii przed deduplikacją:\n{self._format_perfect_strategy_counts(total_strategy_counts)}\n"
                    f"Dostępne tablice perfect wg źródeł: "
                    f"{' | '.join(f'{GOLD_SOURCE_LABELS[key]}: {int(total_source_counts.get(key, 0) or 0)}' for key, _ in GOLD_SOURCE_BUCKETS)}\n\n"
                    "CO DALEJ:\n"
                    "1. Możesz rozszerzyć zaznaczone strategie w pz3.\n"
                    "2. Możesz wrócić do pz2 i poprawić OCR / Laboratorium.\n"
                    "3. Możesz wykonać eksport do CVAT i później zaimportować poprawki.\n"
                    "4. Możesz też wrócić do wizarda i skorzystać z trybów naprawczych."
                )
                self._set_console_text(self.export_console, msg)

                try:
                    if self._step3_linear_mode and CAMPAIGN.get_active_project_name():
                        CAMPAIGN.set_step3_needs_rework()
                except Exception:
                    pass

                try:
                    self._update_step3_finish_button_state()
                except Exception:
                    pass

                try:
                    self.app.update_status(
                        "Nie utworzono gold packa — pozostajesz w z3/pz3, aby kontynuować pracę.",
                        "warning"
                    )
                except Exception:
                    pass

                return

            split_stats = {}
            if split_enabled:
                ratios = {
                    "train": train_pct / 100.0,
                    "val": val_pct / 100.0,
                    "test": test_pct / 100.0,
                }
                split_entries, split_preview_counts = self._build_split_entries(export_entries, ratios, shuffle_seed=42)
                preview_train = int(split_preview_counts.get("train", 0) or 0)
                preview_val = int(split_preview_counts.get("val", 0) or 0)
                preview_test = int(split_preview_counts.get("test", 0) or 0)
                if preview_train <= 0 or preview_val <= 0:
                    msg = (
                        "❌ NIE UDAŁO SIĘ PRZYGOTOWAĆ POPRAWNEGO DATASETU DO TRENINGU.\n\n"
                        f"Do gold packa przeszło tylko {copied} tablic(y), więc przy splicie "
                        f"{train_pct:.0f}/{val_pct:.0f}/{test_pct:.0f} dostaniesz:\n"
                        f"train={preview_train}, val={preview_val}, test={preview_test}\n\n"
                        "To nie wystarczy do treningu, bo dataset musi mieć co najmniej 1 obraz w train i 1 obraz w val.\n\n"
                        "CO DALEJ:\n"
                        "1. Dodaj więcej tablic perfect do gold packa.\n"
                        "2. Zmień proporcje splitu tak, aby train i val nie były puste.\n"
                        "3. Wróć do PZ2 / CVAT i popraw więcej tablic."
                    )
                    self._set_console_text(self.export_console, msg)
                    try:
                        failure_summary = self._build_step3_export_summary(
                            gold_dataset_path="",
                            review_pack_path="",
                            retry_pack_path="",
                            note="Gold pack znaków jest za mały, by przygotować poprawny split train / val / test."
                        )
                        failure_summary["gold_dataset_valid"] = False
                        failure_summary["gold_dataset_validation_message"] = msg
                        self._write_step3_export_summary(failure_summary)
                    except Exception:
                        pass

                    try:
                        if self._step3_linear_mode and CAMPAIGN.get_active_project_name():
                            CAMPAIGN.set_step3_needs_rework()
                    except Exception:
                        pass

                    try:
                        self._update_step3_finish_button_state()
                    except Exception:
                        pass

                    try:
                        self.app.update_status(
                            "Gold pack znaków jest jeszcze zbyt mały do poprawnego splitu train / val / test.",
                            "warning"
                        )
                    except Exception:
                        pass

                    return

                for split_name, items in split_entries.items():
                    (yolo_out / "images" / split_name).mkdir(parents=True, exist_ok=True)
                    (yolo_out / "labels" / split_name).mkdir(parents=True, exist_ok=True)
                    split_stats[split_name] = len(items)
                    for item in items:
                        shutil.copy2(item["img_src"], yolo_out / "images" / split_name / f"{item['pid']}.jpg")
                        (yolo_out / "labels" / split_name / f"{item['pid']}.txt").write_text(
                            item["label_text"],
                            encoding="utf-8"
                        )
            else:
                img_out, lbl_out = yolo_out / "images", yolo_out / "labels"
                img_out.mkdir(parents=True, exist_ok=True)
                lbl_out.mkdir(parents=True, exist_ok=True)
                for item in export_entries:
                    shutil.copy2(item["img_src"], img_out / f"{item['pid']}.jpg")
                    (lbl_out / f"{item['pid']}.txt").write_text(item["label_text"], encoding="utf-8")

            yaml_content = f"path: {yolo_out.absolute().as_posix()}\n"
            if split_enabled:
                yaml_content += "train: images/train\nval: images/val\ntest: images/test\n"
            else:
                yaml_content += "train: images\nval: images\n"
            yaml_content += "nc: 36\nnames:\n"
            for char, class_id in char_map.items():
                yaml_content += f"  {class_id}: '{char}'\n"
            (yolo_out / "data.yaml").write_text(yaml_content, encoding="utf-8")

            split_info = (
                f"\nSplit: train={split_stats.get('train', 0)}, val={split_stats.get('val', 0)}, test={split_stats.get('test', 0)}"
                if split_enabled
                else "\nSplit: wyłączony (flat images/labels)"
            )

            export_summary = self._build_step3_local_success_message(
                "Utworzono źródłowy dataset YOLO znaków.",
                yolo_out,
                "Przejdź do Z4, aby przygotować wariant treningowy i split, albo zostań w Z3 / PZ3 i wykonaj kolejny eksport źródłowy.",
            )
            self._set_console_text(self.export_console, export_summary)
            self._show_pz3_operation_summary_modal(
                "Eksport datasetu znaków zakończony",
                export_summary,
                tone="success",
            )
            try:
                exported_char_count = sum(
                    len([line for line in str(item.get("label_text", "") or "").splitlines() if line.strip()])
                    for item in export_entries
                )
                success_summary = self._build_step3_export_summary(
                    gold_dataset_path=str(yolo_out),
                    review_pack_path="",
                    retry_pack_path="",
                    note="Bieżący eksport źródłowego gold packa znaków zakończył się powodzeniem. Wariant treningowy i split przygotuj w Z4."
                )
                success_summary["exportable_plate_count"] = int(copied)
                success_summary["exportable_char_count"] = int(exported_char_count)
                success_summary["gold_dataset_valid"] = True
                success_summary["gold_dataset_validation_message"] = ""
                self._write_step3_export_summary(success_summary)
            except Exception:
                pass
            self._log(
                self.export_console,
                f"[INFO] Dostępne tablice perfect we wszystkich paczkach przed deduplikacją i filtrem: {self._format_perfect_strategy_counts(total_strategy_counts)}",
                "INFO"
            )
            self._log(
                self.export_console,
                "[INFO] Dostępne tablice perfect wg źródeł: "
                + " | ".join(
                    f"{GOLD_SOURCE_LABELS[key]}={int(total_source_counts.get(key, 0) or 0)}"
                    for key, _ in GOLD_SOURCE_BUCKETS
                ),
                "INFO"
            )
            try:
                self._update_step3_finish_button_state()
                self._set_button_emphasis("btn_finish_step3_frame", True)
            except Exception:
                pass

            try:
                self.app.update_status(
                    "Źródłowy dataset YOLO został utworzony. Wariant treningowy i split przygotujesz w Z4.",
                    "info"
                )
            except Exception:
                pass
        except Exception as e:
            self._set_console_text(self.export_console, f"❌ BŁĄD EKSPORTU YOLO:\n{e}")

    def _run_pz3_existing_dataset_split(self):
        src_raw = str(self.pz3_existing_dataset_var.get() or "").strip()
        source_dir = Path(src_raw) if src_raw else None
        source_info = self._inspect_pz3_dataset_source_dir(source_dir)

        if not source_info.get("ok"):
            self._set_console_text(
                self.export_console,
                "❌ Nie można wykonać nowego splitu.\n\n"
                + str(source_info.get("message") or "Wskaż poprawny dataset YOLO znaków.")
            )
            return

        split_enabled = bool(self.gold_export_split_var.get())
        train_pct, val_pct, test_pct = self._get_gold_export_split_percentages()
        if not split_enabled:
            self._set_console_text(
                self.export_console,
                "❌ Dla wskazanego datasetu włącz split train / val / test, aby utworzyć nowy podział."
            )
            return

        if source_dir is None:
            self._set_console_text(
                self.export_console,
                "❌ Brak źródła datasetu do podziału."
            )
            return

        ratios = {
            "train": train_pct / 100.0,
            "val": val_pct / 100.0,
            "test": test_pct / 100.0,
        }

        import datetime
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        base_datasets_dir = self._get_step3_datasets_root_dir()
        base_datasets_dir.mkdir(parents=True, exist_ok=True)
        out_dir = base_datasets_dir / f"{source_dir.name}_Split_{timestamp}"

        self._set_console_text(
            self.export_console,
            "⌛ Przygotowuję nowy split datasetu...\n"
            f"Źródło: {source_dir}\n"
            f"Rozklad: train={train_pct:.0f}, val={val_pct:.0f}, test={test_pct:.0f}\n"
            f"Par obraz + etykieta: {int(source_info.get('total_pairs', 0) or 0)}"
        )

        try:
            ok, msg, stats = self._pz3_dataset_splitter.split_dataset(source_dir, out_dir, ratios)
            if not ok:
                self._set_console_text(
                    self.export_console,
                    f"❌ Nowy split nie powiódł się:\n{msg}"
                )
                return

            split_summary = self._build_step3_local_success_message(
                "Utworzono nowy split datasetu.",
                out_dir,
                "Przejdź do Z4, aby użyć nowego splitu w treningu, albo zostań w Z3 / PZ3 i wykonaj kolejny eksport.",
            )
            self._set_console_text(self.export_console, split_summary)
            self._show_pz3_operation_summary_modal(
                "Split datasetu zakończony",
                split_summary,
                tone="success",
            )
            try:
                success_summary = self._build_step3_export_summary(
                    gold_dataset_path=str(out_dir),
                    review_pack_path="",
                    retry_pack_path="",
                    note="Bieżący split datasetu znaków zakończył się powodzeniem."
                )
                success_summary["gold_dataset_valid"] = True
                success_summary["gold_dataset_validation_message"] = ""
                self._write_step3_export_summary(success_summary)
            except Exception:
                pass
            try:
                self._update_step3_finish_button_state()
                self._set_button_emphasis("btn_finish_step3_frame", True)
            except Exception:
                pass
            try:
                self.app.update_status(
                    "Nowy split datasetu znaków został zapisany w katalogu projektu.",
                    "info"
                )
            except Exception:
                pass
        except Exception as exc:
            self._set_console_text(
                self.export_console,
                f"❌ Błąd nowego splitu datasetu:\n{exc}"
            )

    def _build_gold_export_plate_unique_key(self, data: dict) -> str:
        if not isinstance(data, dict):
            return ""

        source_image = str(data.get("source_image", "u") or "u")
        source_bbox = data.get("source_bbox") or []
        try:
            bbox_bucket = int(float(source_bbox[0]) // 10) if source_bbox else 0
        except Exception:
            bbox_bucket = 0
        return f"{source_image}_{bbox_bucket}"

    def _collect_gold_export_plate_candidates(self, selected_buckets, selected_sources=None) -> tuple[list[dict], dict, dict, dict, dict]:
        selected = set(selected_buckets or [])
        selected_source_buckets = set(selected_sources or [])
        base_chars_dir = self._get_step3_chars_root_dir()
        total_strategy_counts = self._empty_perfect_strategy_counts()
        selected_strategy_counts = self._empty_perfect_strategy_counts()
        total_source_counts = self._empty_gold_source_counts()
        selected_source_counts = self._empty_gold_source_counts()
        plate_entries = []
        seen = set()

        meta_candidates = self._get_gold_export_meta_candidates()

        for meta in meta_candidates:
            run_dir = meta.parent
            with open(meta, "r", encoding="utf-8") as f:
                metadata = json.load(f)

            for pid, data in {k: v for k, v in metadata.items() if v.get("status") == "perfect"}.items():
                self._ensure_plate_source_metadata(data, plate_id=str(pid or ""), meta_path=meta)
                strategy_bucket = self._get_perfect_strategy_bucket(data)
                source_bucket = self._get_plate_source_bucket(data, meta_path=meta)
                total_strategy_counts[strategy_bucket] += 1
                if source_bucket in total_source_counts:
                    total_source_counts[source_bucket] += 1
                if selected and strategy_bucket not in selected:
                    continue
                if selected_source_buckets and source_bucket not in selected_source_buckets:
                    continue

                unique_key = self._build_gold_export_plate_unique_key(data)
                if unique_key in seen:
                    continue

                img_src = run_dir / "images" / f"{pid}.jpg"
                if not img_src.exists():
                    continue

                seen.add(unique_key)
                selected_strategy_counts[strategy_bucket] += 1
                if source_bucket in selected_source_counts:
                    selected_source_counts[source_bucket] += 1
                plate_entries.append(
                    {
                        "pid": str(pid),
                        "data": data,
                        "run_dir": run_dir,
                        "img_src": img_src,
                        "strategy_bucket": strategy_bucket,
                        "source_bucket": source_bucket,
                    }
                )

        return plate_entries, total_strategy_counts, selected_strategy_counts, total_source_counts, selected_source_counts

    def _normalize_classification_char_crop_bbox(
        self,
        bbox,
        image_shape,
        *,
        pad_x_ratio: float = 0.12,
        pad_y_ratio: float = 0.16,
        min_pad: int = 2,
        min_size: int = 4,
    ):
        if not isinstance(bbox, (list, tuple)) or len(bbox) < 4:
            return None

        try:
            x1, y1, x2, y2 = (float(v) for v in bbox[:4])
        except Exception:
            return None

        if x2 < x1:
            x1, x2 = x2, x1
        if y2 < y1:
            y1, y2 = y2, y1

        img_h, img_w = image_shape[:2]
        width = max(float(min_size), x2 - x1)
        height = max(float(min_size), y2 - y1)
        pad_x = max(int(round(width * float(pad_x_ratio))), int(min_pad))
        pad_y = max(int(round(height * float(pad_y_ratio))), int(min_pad))

        crop_x1 = max(0, min(int(img_w), int(x1) - pad_x))
        crop_y1 = max(0, min(int(img_h), int(y1) - pad_y))
        crop_x2 = max(0, min(int(img_w), int(x2) + pad_x))
        crop_y2 = max(0, min(int(img_h), int(y2) + pad_y))

        if crop_x2 - crop_x1 < int(min_size):
            crop_x2 = min(int(img_w), crop_x1 + int(min_size))
        if crop_y2 - crop_y1 < int(min_size):
            crop_y2 = min(int(img_h), crop_y1 + int(min_size))

        if crop_x2 <= crop_x1 or crop_y2 <= crop_y1:
            return None

        return [int(crop_x1), int(crop_y1), int(crop_x2), int(crop_y2)]

    def _run_char_classification_export(self):
        selected_buckets = self._get_selected_gold_export_strategy_buckets()
        selected_labels = self._format_selected_gold_export_strategy_labels()
        selected_sources = self._get_selected_gold_export_source_buckets()
        selected_source_labels = self._format_selected_gold_export_source_labels()
        split_enabled = False
        train_pct, val_pct, test_pct = self._get_gold_export_split_percentages()

        if not selected_buckets:
            self._set_console_text(
                self.export_console,
                "❌ Nie wybrano żadnej strategii perfect do eksportu znaków.\n\n"
                "Zaznacz co najmniej jedną z opcji: OCR exact, YOLO exact, OCR + YOLO rescue, YOLO boxy + OCR lub Manual / inne perfect."
            )
            return
        if not selected_sources:
            self._set_console_text(
                self.export_console,
                "❌ Nie wybrano żadnego źródła do eksportu znaków.\n\n"
                "Zaznacz Auto z runu lub Ręczne poprawki lokalne. Poprawki CVAT po imporcie są dołączane automatycznie."
            )
            return

        split_line = "Podział klasyfikacyjny: bez splitu w PZ3"
        self._set_console_text(
            self.export_console,
            f"⏳ Zbieranie poprawnych znaków...\nFiltr strategii: {selected_labels}\nŹródła: {selected_source_labels}\n{split_line}"
        )

        import datetime, uuid

        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        base_datasets_dir = self._get_step3_char_classification_datasets_root_dir(ensure_exists=True)
        out_dir = base_datasets_dir / f"CharClassificationDataset_{timestamp}"

        try:
            (
                plate_entries,
                total_strategy_counts,
                exported_plate_strategy_counts,
                total_source_counts,
                exported_source_counts,
            ) = self._collect_gold_export_plate_candidates(selected_buckets, selected_sources)
            if not plate_entries:
                msg = (
                    "❌ NIE UDAŁO SIĘ UTWORZYĆ DATASETU ZNAKÓW.\n\n"
                    f"Powód: po filtrze strategii ({selected_labels}) i źródeł ({selected_source_labels}) "
                    "nie znaleziono ani jednej tablicy ze statusem perfect.\n\n"
                    f"Dostępne tablice perfect wg strategii przed deduplikacją:\n{self._format_perfect_strategy_counts(total_strategy_counts)}\n"
                    f"Dostępne tablice perfect wg źródeł: "
                    f"{' | '.join(f'{GOLD_SOURCE_LABELS[key]}: {int(total_source_counts.get(key, 0) or 0)}' for key, _ in GOLD_SOURCE_BUCKETS)}\n\n"
                    "CO DALEJ:\n"
                    "1. Możesz rozszerzyć zaznaczone strategie w pz3.\n"
                    "2. Możesz wrócić do pz2 i poprawić wykrycia lub odczyt.\n"
                    "3. Możesz wykonać eksport do CVAT i później zaimportować poprawki."
                )
                self._set_console_text(self.export_console, msg)
                return

            char_entries = []
            skipped_chars = 0

            for plate_entry in plate_entries:
                data = plate_entry.get("data", {})
                img_src = plate_entry.get("img_src")
                pid = str(plate_entry.get("pid", "") or "")
                strategy_bucket = str(plate_entry.get("strategy_bucket", "") or "")
                source_bucket = str(plate_entry.get("source_bucket", "") or "")

                img = cv2.imread(str(img_src))
                if img is None:
                    continue

                for idx, rec in enumerate(list(data.get("characters", []) or [])):
                    if not isinstance(rec, dict):
                        skipped_chars += 1
                        continue

                    symbol = self._sanitize_preview_char_symbol(rec.get("character", ""))
                    if not symbol:
                        skipped_chars += 1
                        continue

                    crop_bbox = self._normalize_classification_char_crop_bbox(rec.get("bbox"), img.shape)
                    if crop_bbox is None:
                        skipped_chars += 1
                        continue

                    x1, y1, x2, y2 = crop_bbox
                    crop = img[y1:y2, x1:x2]
                    if crop is None or getattr(crop, "size", 0) == 0:
                        skipped_chars += 1
                        continue

                    crop_name = f"{symbol}_{uuid.uuid4().hex[:10]}_{pid}_{idx:02d}.png"
                    source_tag = self._get_character_source_tag(rec, data=data, fallback_index=idx)
                    confidence = float(rec.get("confidence", 0.0) or 0.0)

                    char_entries.append(
                        {
                            "symbol": symbol,
                            "filename": crop_name,
                            "image": crop,
                            "plate_id": pid,
                            "source_image": str(data.get("source_image", "") or ""),
                            "strategy_bucket": strategy_bucket,
                            "fusion_strategy": str(data.get("fusion_strategy", "") or ""),
                            "source_tag": str(source_tag or ""),
                            "source_bucket": source_bucket,
                            "source_kind": str(self._get_character_source_kind(rec, data=data)),
                            "confidence": confidence,
                            "bbox": [float(v) for v in (rec.get("bbox", []) or [])[:4]],
                        }
                    )

            if not char_entries:
                msg = (
                    "❌ NIE UDAŁO SIĘ UTWORZYĆ DATASETU ZNAKÓW.\n\n"
                    "Wybrano tablice perfect, ale nie udało się wyciąć żadnego poprawnego znaku z końcowych ramek."
                )
                self._set_console_text(self.export_console, msg)
                return

            split_entries = {}
            split_stats = {}
            if split_enabled:
                ratios = {
                    "train": train_pct / 100.0,
                    "val": val_pct / 100.0,
                    "test": test_pct / 100.0,
                }
                split_entries, split_stats = self._build_split_entries(char_entries, ratios, shuffle_seed=42)
            else:
                split_entries = {"train": list(char_entries)}

            manifest_items = []
            saved_class_counts = {}
            for split_name, items in split_entries.items():
                split_stats[split_name] = len(items)
                for item in items:
                    class_dir = out_dir / split_name / str(item["symbol"])
                    class_dir.mkdir(parents=True, exist_ok=True)
                    target_path = class_dir / str(item["filename"])
                    if not cv2.imwrite(str(target_path), item["image"]):
                        continue

                    saved_symbol = str(item["symbol"])
                    saved_class_counts[saved_symbol] = int(saved_class_counts.get(saved_symbol, 0) or 0) + 1

                    manifest_items.append(
                        {
                            "path": str(target_path.relative_to(out_dir).as_posix()),
                            "split": split_name,
                            "character": str(item["symbol"]),
                            "plate_id": str(item["plate_id"]),
                            "source_image": str(item["source_image"]),
                            "strategy_bucket": str(item["strategy_bucket"]),
                            "fusion_strategy": str(item["fusion_strategy"]),
                            "source_tag": str(item["source_tag"]),
                            "source_bucket": str(item["source_bucket"]),
                            "source_kind": str(item["source_kind"]),
                            "confidence": float(item["confidence"]),
                            "bbox": list(item["bbox"]),
                        }
                    )

            if not manifest_items:
                self._set_console_text(
                    self.export_console,
                    "❌ NIE UDAŁO SIĘ UTWORZYĆ DATASETU ZNAKÓW.\n\nNie udało się zapisać żadnego cropa znaku na dysku."
                )
                return

            present_classes = [char for char in CHAR_CLASS_ALPHABET if int(saved_class_counts.get(char, 0) or 0) > 0]
            manifest = {
                "dataset_type": "char_classification",
                "created_at": timestamp,
                "selected_strategies": sorted(selected_buckets),
                "selected_sources": sorted(selected_sources),
                "split_enabled": bool(split_enabled),
                "split_stats": {key: int(value) for key, value in split_stats.items()},
                "plate_count": int(len(plate_entries)),
                "character_count": int(len(manifest_items)),
                "skipped_characters": int(skipped_chars),
                "present_classes": list(present_classes),
                "class_counts": {char: int(saved_class_counts.get(char, 0) or 0) for char in CHAR_CLASS_ALPHABET if int(saved_class_counts.get(char, 0) or 0) > 0},
                "exported_plate_strategy_counts": dict(exported_plate_strategy_counts),
                "available_plate_strategy_counts": dict(total_strategy_counts),
                "exported_plate_source_counts": dict(exported_source_counts),
                "available_plate_source_counts": dict(total_source_counts),
                "items": manifest_items,
            }
            self._atomic_write_json(out_dir / "manifest.json", manifest)
            (out_dir / "classes.txt").write_text("\n".join(present_classes), encoding="utf-8")

            split_info = "Podział klasyfikacyjny: wszystkie znaki zapisano w train/"
            classifier_summary = self._build_step3_local_success_message(
                "Utworzono dataset znaków do klasyfikacji.",
                out_dir,
                "To dataset OCR/klasyfikacji znaków (manifest.json), nie wejście Z4/PZ1/PZ2 YOLO. "
                "Zostań w Z3 / PZ3 i wykonaj kolejny eksport albo użyj go w module klasyfikacyjnym.",
            )
            self._set_console_text(self.export_console, classifier_summary)
            self._show_pz3_operation_summary_modal(
                "Eksport datasetu klasyfikacyjnego zakończony",
                classifier_summary,
                tone="success",
            )
            self._log(
                self.export_console,
                f"[INFO] Dostępne tablice perfect we wszystkich paczkach przed deduplikacją i filtrem: {self._format_perfect_strategy_counts(total_strategy_counts)}",
                "INFO"
            )
            self._log(
                self.export_console,
                "[INFO] Dostępne tablice perfect wg źródeł: "
                + " | ".join(
                    f"{GOLD_SOURCE_LABELS[key]}={int(total_source_counts.get(key, 0) or 0)}"
                    for key, _ in GOLD_SOURCE_BUCKETS
                ),
                "INFO"
            )
            self._log(
                self.export_console,
                f"[INFO] Rozkład klas i metadane źródła zapisano w: {out_dir / 'manifest.json'}",
                "INFO"
            )

            try:
                self._update_step3_finish_button_state()
                self._set_button_emphasis("btn_finish_step3_frame", True)
            except Exception:
                pass

            try:
                self.app.update_status(
                    "Paczka znaków do klasyfikacji została utworzona poprawnie.",
                    "info"
                )
            except Exception:
                pass
        except Exception as e:
            self._set_console_text(self.export_console, f"❌ BŁĄD EKSPORTU ZNAKÓW:\n{e}")

    def _run_cvat_import(self):
        xml_in = Path(self.import_cvat_xml_var.get().strip())
        preview_dir_raw = str(self.preview_dir_var.get() or "").strip()
        preview_dir = Path(preview_dir_raw) if preview_dir_raw else None
        meta_path = preview_dir / "metadata.json" if preview_dir is not None else None
        images_dir = preview_dir / "images" if preview_dir is not None else None

        if not xml_in.exists():
            self._set_console_text(self.import_console, "❌ BŁĄD: Wybrany plik XML nie istnieje.")
            return
        if preview_dir is None or not preview_dir.exists() or not preview_dir.is_dir():
            self._set_console_text(
                self.import_console,
                (
                    "❌ BŁĄD: Brak aktywnego preview runu. Utwórz go w [Z3]/[PZ1] przyciskiem "
                    "„Wytnij tablice do PZ2” albo wskaż gotowy katalog w [PZ2] -> Źródło PZ2 -> "
                    "Zmień źródło preview -> Wybierz katalog."
                )
            )
            return
        if meta_path is None or not meta_path.exists():
            self._set_console_text(
                self.import_console,
                f"❌ BŁĄD: W aktywnym preview runie brakuje metadata.json:\n{preview_dir}"
            )
            return
        if images_dir is None or not images_dir.exists() or not images_dir.is_dir():
            self._set_console_text(
                self.import_console,
                f"❌ BŁĄD: W aktywnym preview runie brakuje katalogu images/:\n{preview_dir}"
            )
            return

        self._set_console_text(self.import_console, "⌛ Wczytywanie danych z XML...")

        try:
            with open(meta_path, 'r', encoding='utf-8') as f:
                metadata = json.load(f)

            if not isinstance(metadata, dict):
                raise RuntimeError("metadata.json ma nieprawidłowy format.")

            from ..cvat_tools.cvat_character_importer import CVATCharacterImporter

            importer = CVATCharacterImporter()
            import_ok, import_msg, import_stats = importer.import_annotations(xml_in)
            if not import_ok:
                self._set_console_text(self.import_console, f"❌ BŁĄD IMPORTU:\n{import_msg}")
                return

            imported_annotations = importer.get_all_annotations()
            xml_images_total = len(imported_annotations)
            review_manifest_id = ""
            review_manifest_mismatch = False
            review_manifest_path = xml_in.parent / "review_manifest.json"
            if review_manifest_path.exists():
                try:
                    review_manifest = json.loads(review_manifest_path.read_text(encoding="utf-8"))
                    if isinstance(review_manifest, dict):
                        review_manifest_id = str(review_manifest.get("review_manifest_id", "") or "").strip()
                        source_preview_dir = str(review_manifest.get("source_preview_dir", "") or "").strip()
                        if source_preview_dir:
                            try:
                                review_manifest_mismatch = Path(source_preview_dir).resolve() != preview_dir.resolve()
                            except Exception:
                                review_manifest_mismatch = str(Path(source_preview_dir)) != str(preview_dir)
                except Exception as e:
                    logger.debug(f"Nie udało się odczytać review_manifest.json przy imporcie CVAT: {e}")
            matched_images = 0
            skipped_empty = 0
            skipped_unknown = 0
            updated = 0
            changed_characters = 0
            import_batch_id = f"cvat_import_{Path(xml_in).stem}"
            try:
                import datetime
                import_batch_id = f"cvat_import_{datetime.datetime.now().strftime('%Y%m%d_%H%M%S')}"
            except Exception:
                pass

            matched_plate_ids = []
            report_items = []

            for image_name, detections in imported_annotations.items():
                pid = Path(str(image_name or "")).stem
                if pid not in metadata:
                    skipped_unknown += 1
                    continue

                matched_images += 1
                clean_chars = []
                for det in list(detections or []):
                    symbol = self._sanitize_preview_char_symbol(getattr(det, "character", ""))
                    bbox = self._normalize_preview_char_bbox(getattr(det, "bbox", None))
                    if not symbol or bbox is None:
                        continue
                    try:
                        confidence = float(getattr(det, "confidence", 1.0) or 1.0)
                    except Exception:
                        confidence = 1.0
                    clean_chars.append(
                        {
                            "character": symbol,
                            "bbox": bbox,
                            "confidence": confidence,
                            "method": "cvat_manual",
                            "source_tag": "manual",
                            "source_kind": "cvat_manual",
                            "source_batch_id": import_batch_id,
                        }
                    )

                if not clean_chars:
                    skipped_empty += 1
                    report_items.append(
                        {
                            "plate_id": pid,
                            "image_name": image_name,
                            "status": "skipped_empty",
                            "characters": 0,
                        }
                    )
                    continue

                clean_chars = self._sort_character_records_by_x(clean_chars)
                target_data = metadata.get(pid, {})
                previous_chars = list(target_data.get("characters", [])) if isinstance(target_data.get("characters"), list) else []
                previous_status = str(target_data.get("status", "unknown") or "unknown").strip().lower()
                target_data["characters"] = clean_chars
                target_data["fusion_strategy"] = "manual_correction"
                target_data["fusion_details"] = {
                    "source": "cvat_import",
                    "import_batch_id": import_batch_id,
                    "xml_path": str(xml_in),
                }
                target_data["import_source_xml"] = str(xml_in)
                status_probe = dict(target_data)
                status_probe["plate_id"] = str(pid)
                status_now = self._derive_preview_status_from_data(status_probe, clean_chars)
                if (
                    status_now == "perfect"
                    and previous_status == "perfect"
                    and len(clean_chars) != len(previous_chars)
                    and not self._get_preview_expected_texts(status_probe)
                ):
                    status_now = "needs_fix"
                target_data["status"] = status_now
                self._ensure_plate_source_metadata(
                    target_data,
                    plate_id=str(pid),
                    meta_path=meta_path,
                    default_bucket="cvat_manual",
                    default_origin="cvat_import",
                    import_batch_id=import_batch_id,
                    review_manifest_id=review_manifest_id,
                    modified_by="human",
                )
                metadata[pid] = target_data
                updated += 1
                changed_characters += len(clean_chars)
                matched_plate_ids.append(str(pid))
                report_items.append(
                    {
                        "plate_id": pid,
                        "image_name": image_name,
                        "status": str(status_now),
                        "characters": len(clean_chars),
                    }
                )

            if matched_images == 0:
                self._set_console_text(
                    self.import_console,
                    "❌ BŁĄD IMPORTU:\nWybrany XML nie pasuje do aktywnego preview runu. "
                    "Nie znaleziono żadnej wspólnej tablicy po nazwie pliku."
                )
                return
            if updated == 0:
                self._set_console_text(
                    self.import_console,
                    "❌ BŁĄD IMPORTU:\nXML pasuje do aktywnego runu, ale żadna tablica nie zawiera poprawnych znaków do zapisania."
                )
                return

            backup_path = self._backup_json_before_import(meta_path)
            self._atomic_write_json(meta_path, metadata)
            self._apply_preview_metadata_update(metadata, preserve_selection=True)
            self._loaded_meta_path = meta_path
            try:
                self._loaded_meta_mtime = meta_path.stat().st_mtime
            except Exception:
                self._loaded_meta_mtime = None
            self._set_preview_import_focus(
                matched_plate_ids,
                import_batch_id=import_batch_id,
                activate=True,
            )

            report_payload = {
                "import_batch_id": import_batch_id,
                "source_xml": str(xml_in),
                "preview_dir": str(preview_dir),
                "matched_images": int(matched_images),
                "updated_images": int(updated),
                "skipped_empty": int(skipped_empty),
                "skipped_unknown": int(skipped_unknown),
                "xml_images_total": int(xml_images_total),
                "xml_characters_total": int(import_stats.get("characters", 0) or 0) if isinstance(import_stats, dict) else 0,
                "saved_characters": int(changed_characters),
                "review_manifest_id": review_manifest_id,
                "review_manifest_mismatch": bool(review_manifest_mismatch),
                "matched_plate_ids": list(matched_plate_ids),
                "items": report_items,
            }
            report_path = preview_dir / f"{import_batch_id}_report.json"
            try:
                self._atomic_write_json(report_path, report_payload)
            except Exception as e:
                logger.debug(f"Nie udało się zapisać raportu importu CVAT: {e}")

            import_summary = self._build_step3_local_success_message(
                "Zaimportowano ręczne poprawki z CVAT.",
                preview_dir,
                "Sprawdź tablice na liście po lewej albo przejdź do Budowy datasetu w Z3 / PZ3.",
            )
            final_import_summary = import_summary
            self._set_console_text(self.import_console, import_summary)
            try:
                stored_dir = self._store_current_preview_in_manual_char_pool(metadata)
                final_import_summary = self._build_step3_local_success_message(
                    "Zaimportowano ręczne poprawki z CVAT.",
                    stored_dir,
                    "Sprawdź tablice na liście po lewej albo przejdź do Budowy datasetu w Z3 / PZ3.",
                )
                self._set_console_text(self.import_console, final_import_summary)
            except Exception as e:
                logger.debug(f"Nie udało się zapisać paczki do manual_char_pool: {e}")
            self._show_pz3_operation_summary_modal(
                "Import CVAT zakończony",
                final_import_summary,
                tone="success",
            )
            try:
                self._update_step3_finish_button_state()
            except Exception:
                pass

        except Exception as e:
            self._set_console_text(self.import_console, f"❌ BŁĄD IMPORTU:\n{e}")

    # =========================================================
    # Ranking presetów OCR
    # =========================================================

    def _run_preset_ranking(self):
        sample_bundle = self._get_ocr_ranking_sample_bundle()
        if sample_bundle.get("mode") != "preview":
            self._set_ocr_ranking_modal_status(
                str(sample_bundle.get("message") or "Ranking OCR wymaga wczytanego katalogu wyodrębnionych tablic."),
                tone="warning",
            )
            messagebox.showinfo(
                "Ranking OCR",
                sample_bundle.get("message") or "Ranking OCR wymaga wczytanego katalogu wyodrębnionych tablic.",
            )
            return

        sample_records = list(sample_bundle.get("samples") or [])
        if not sample_records:
            self._set_ocr_ranking_modal_status(
                str(sample_bundle.get("message") or "Brak próbek do rankingu OCR."),
                tone="warning",
            )
            messagebox.showinfo("Brak", sample_bundle.get("message") or "Brak próbek do rankingu OCR.")
            return

        preset_files = list(self.presets_dir.glob("*.json"))
        preset_files = [f for f in preset_files if f.name != "global_ranking.json"]
        if not preset_files:
            self._set_ocr_ranking_modal_status(
                "Brak presetów OCR. Otwórz Laboratorium OCR i zapisz co najmniej jeden preset.",
                tone="warning",
            )
            messagebox.showinfo("Brak presetów", "Brak presetów! Otwórz Laboratorium OCR i zapisz co najmniej jeden preset.")
            return
            return messagebox.showinfo("Brak presetów", "Brak presetów! Otwórz Laboratorium i zapisz filtry jako JSON.")

        ranking_mode = str(sample_bundle.get("mode") or "preview")
        demo_mode = ranking_mode == "demo"
        total_imgs = len(sample_records)
        total_presets = len(preset_files)
        ranking_state = {"error": ""}

        self.test_log_text.delete(1.0, tk.END)
        if not self._lock_ui_for_testing("pz2.ocr_ranking.run", "PZ2: ranking presetów OCR"):
            return
        self._set_ocr_ranking_modal_running(True)
        self._set_ocr_ranking_modal_source(
            self._compose_ocr_ranking_source_text(source_desc="", total_imgs=total_imgs, ranking_mode=ranking_mode, preset_count=total_presets),
            tone="muted",
        )
        self._update_ocr_ranking_modal_progress(0, total_presets, sample_count=total_imgs, demo_mode=demo_mode)
        self._set_ocr_ranking_modal_status("Ranking presetów OCR w toku", "warning")
        self._log(self.test_log_text, "=======================================================", "HEADER")
        self._log(self.test_log_text, "ROZPOCZYNAM RANKING PRESETÓW OCR", "HEADER")

        cache_file = Path(sample_bundle.get("cache_file") or (self.presets_dir / "global_ranking.json"))
        dataset_signature = str(sample_bundle.get("dataset_signature") or "")
        source_desc = str(sample_bundle.get("description") or "wczytana lista tablic")
        session_token = self._project_reset_token
        self._set_ocr_ranking_modal_source(
            self._compose_ocr_ranking_source_text(source_desc, total_imgs, ranking_mode, total_presets),
            tone="muted",
        )
        self._log(self.test_log_text, f"Źródło próbek: {source_desc}", "INFO")
        effective_ocr_device = self._device_to_ocr(self._get_effective_detection_device_choice())

        def worker():
            try:
                try:
                    cache_file.parent.mkdir(parents=True, exist_ok=True)
                except Exception:
                    pass

                ranking_cache = {}
                if cache_file.exists():
                    try:
                        loaded_cache = self._load_json_file_safely(cache_file)
                        if isinstance(loaded_cache, dict):
                            ranking_cache = loaded_cache
                    except Exception:
                        pass

                ocr_engine = PlateOCR(device=effective_ocr_device)
                detector = CharacterDetector(method=DetectionMethod.OCR, ocr_engine=ocr_engine)

                results_table = []

                for p_idx, p_file in enumerate(preset_files):
                    if session_token != self._project_reset_token:
                        return

                    preset_name = p_file.stem
                    try:
                        with open(p_file, 'r', encoding='utf-8') as f:
                            preset_params = json.load(f)
                    except Exception:
                        continue

                    clean_params = {k: v for k, v in preset_params.items() if not k.startswith("char_do_") and k != "char_ocr_conf"}
                    param_signature = str(sorted(clean_params.items()))
                    cached_entry = ranking_cache.get(preset_name, {}) if isinstance(ranking_cache, dict) else {}

                    if (
                        isinstance(cached_entry, dict)
                        and cached_entry.get("signature") == param_signature
                        and str(cached_entry.get("dataset_signature") or "") == dataset_signature
                    ):
                        results_table.append((cached_entry["acc"], cached_entry["matches"], preset_name, True))
                        self.frame.after(
                            0,
                            lambda processed=(p_idx + 1), total=total_presets, samples=total_imgs, is_demo=demo_mode: (
                                self._update_ocr_ranking_modal_progress(processed, total, sample_count=samples, demo_mode=is_demo)
                                if session_token == self._project_reset_token else None
                            )
                        )
                        continue

                    ocr_engine.custom_prep_params = clean_params
                    if "char_ocr_conf" in preset_params:
                        ocr_engine.confidence_threshold = float(preset_params.get("char_ocr_conf", 0.25))

                    perfect_matches = 0
                    for sample in sample_records:
                        if session_token != self._project_reset_token:
                            return

                        img_path = Path(str(sample.get("image_path") or "").strip())
                        if not img_path.exists():
                            continue
                        plate_img = cv2.imread(str(img_path))
                        if plate_img is None:
                            continue

                        expected = [
                            str(text or "").strip().upper()
                            for text in (sample.get("expected_texts") or [])
                            if str(text or "").strip()
                        ]
                        if not expected:
                            continue
                        chars = detector.detect(plate_img)
                        detected_text = "".join([str(c.character) for c in chars]).strip().upper()
                        if detected_text and detected_text in expected:
                            perfect_matches += 1

                    acc = (perfect_matches / total_imgs) * 100 if total_imgs > 0 else 0
                    ranking_cache[preset_name] = {
                        "name": preset_name,
                        "acc": acc,
                        "matches": perfect_matches,
                        "signature": param_signature,
                        "dataset_signature": dataset_signature,
                        "params": preset_params
                    }
                    results_table.append((acc, perfect_matches, preset_name, False))
                    self.frame.after(
                        0,
                        lambda processed=(p_idx + 1), total=total_presets, samples=total_imgs, is_demo=demo_mode: (
                            self._update_ocr_ranking_modal_progress(processed, total, sample_count=samples, demo_mode=is_demo)
                            if session_token == self._project_reset_token else None
                        )
                    )

                if session_token != self._project_reset_token:
                    return

                with open(cache_file, 'w', encoding='utf-8') as f:
                    json.dump(ranking_cache, f, indent=4, ensure_ascii=False)

                results_table.sort(key=lambda x: x[0], reverse=True)

                self._log(self.test_log_text, "=" * 55, "HEADER")
                for i, (acc, matches, name, from_cache) in enumerate(results_table):
                    self._log(self.test_log_text, f"#{i+1}. {name.ljust(22)} | {acc:5.1f}%  ({matches}/{total_imgs})", "SUCCESS" if i == 0 else "INFO")

                self.frame.after(
                    0,
                    lambda table=list(results_table), total=total_imgs, source=source_desc, mode=ranking_mode: (
                        None if mode == "demo" else self._update_winner_label(),
                        self._remember_ocr_ranking_results(table, total, source, mode),
                        self._refresh_ocr_ranking_modal_results()
                    )
                )

            except Exception as e:
                ranking_state["error"] = str(e)
                self.frame.after(
                    0,
                    lambda err=str(e): self._set_ocr_ranking_modal_status(
                        f"Błąd rankingu OCR: {err}",
                        tone="error",
                    )
                )
                self._log(self.test_log_text, f"\n❌ BŁĄD RANKINGU: {e}", "ERROR")
            finally:
                def finalize():
                    if session_token != self._project_reset_token:
                        return

                    if self._step3_linear_mode and CAMPAIGN.get_active_project_name():
                        self.unlock_dataset_subtab()

                    if not ranking_state["error"]:
                        self._update_ocr_ranking_modal_progress(
                            total_presets,
                            total_presets,
                            sample_count=total_imgs,
                            demo_mode=demo_mode,
                            finished=True,
                        )
                        final_status = "Turniej demo zakończony." if ranking_mode == "demo" else "Turniej zakończony!"
                        self._set_ocr_ranking_modal_status(final_status, "success")
                    self._set_ocr_ranking_modal_running(False)
                    self._unlock_ui_after_testing()

                self.frame.after(0, finalize)

        threading.Thread(target=worker, daemon=True).start()

    def _open_filter_lab(self):
        sample_bundle = self._get_ocr_lab_sample_bundle()
        sample_pool = list(sample_bundle.get("samples") or [])
        if not sample_pool:
            return messagebox.showinfo("Brak", sample_bundle.get("message") or "Brak próbek do laboratorium OCR.")
            return messagebox.showinfo("Brak", "Wczytaj najpierw listę tablic.")

        demo_mode = str(sample_bundle.get("mode") or "") == "demo"
        allow_random = bool(sample_bundle.get("allow_random", False))

        def roll_images():
            res = []
            if demo_mode:
                chosen_samples = list(sample_pool[: min(3, len(sample_pool))])
            else:
                s = min(3, len(sample_pool))
                chosen_samples = random.sample(sample_pool, s)
            for item in chosen_samples:
                i = cv2.imread(str(item.get("image_path") or ""))
                if i is not None:
                    res.append((str(item.get("sample_id") or ""), i, item))
            return res

        self.lab_current_images = roll_images()
        if not self.lab_current_images:
            return

        best_preset_data, best_acc = self._get_best_preset()
        palette = getattr(self.app, "palette", {})
        panel_bg = palette.get("panel", "#252526")
